  select 'De acuerdo con el artículo 87 de la Constitución, la iniciativa legislativa popular:', 'El art. 87.3 CE exige al menos 500.000 firmas acreditadas y excluye las materias propias de ley orgánica, las tributarias, las de carácter internacional y la prerrogativa de gracia.', 'jus_01_constitucion', (select id from public.topics where slug = 'jus-01-constitucion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 87.3 CE', 'En todo caso se exigirán no menos de 500.000 firmas acreditadas. No procederá dicha iniciativa en materias propias de ley orgánica, tributarias o de carácter internacional, ni en lo relativo a la prerrogativa de gracia.', null, '9a94f6b96d6e3f7737fd6689693044097e1fe754cb8c3824f0dae05cf2899072', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9a94f6b96d6e3f7737fd6689693044097e1fe754cb8c3824f0dae05cf2899072')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exige no menos de 500.000 firmas acreditadas y procede en cualquier materia salvo la tributaria.', false), ('B', 'Exige no menos de 750.000 firmas acreditadas y no procede en materias propias de ley orgánica.', false), ('C', 'Exige no menos de 500.000 firmas acreditadas y no procede en materias propias de ley orgánica.', true), ('D', 'Exige no menos de 300.000 firmas acreditadas y no procede en materia de carácter internacional.', false)) as v(label, body, ok)
)
