with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 2/1979, del Tribunal Constitucional, ¿cómo están compuestas las Salas del Tribunal?', 'El art. 7 LOTC establece dos Salas de seis Magistrados cada una, nombrados por el Pleno; el Presidente del Tribunal preside la Sala Primera y el Vicepresidente la Sala Segunda. Las Secciones (art. 8) se componen del Presidente respectivo y dos Magistrados.', 'jus_01_constitucion', (select id from public.topics where slug = 'jus-01-constitucion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23709'), 'Art. 7 LOTC', 'Uno. El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.', null, 'f5ce6cb40c67f3d6352b69f9df98a92ee3a85edd49154ba8161b0f1854a96ec3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f5ce6cb40c67f3d6352b69f9df98a92ee3a85edd49154ba8161b0f1854a96ec3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Hay tres Salas, compuestas cada una por cuatro Magistrados nombrados por el Presidente.', false), ('B', 'Hay dos Salas, compuestas cada una por seis Magistrados designados por sorteo.', false), ('C', 'Hay dos Salas, compuestas cada una por tres Magistrados nombrados por el Tribunal en Pleno.', false), ('D', 'Hay dos Salas, compuestas cada una por seis Magistrados nombrados por el Tribunal en Pleno.', true)) as v(label, body, ok)
)
