with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley Orgánica del Tribunal Constitucional, con carácter general, el recurso de inconstitucionalidad se formulará dentro del plazo de:', 'El art. 33.1 LOTC fija el plazo general de tres meses desde la publicación; el de nueve meses (art. 33.2) solo cabe para el Presidente del Gobierno y los órganos colegiados ejecutivos autonómicos si se reúne la Comisión Bilateral y se cumplen los demás requisitos.', 'jus_01_constitucion', (select id from public.topics where slug = 'jus-01-constitucion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23709'), 'Art. 33.1 LOTC', 'El recurso de inconstitucionalidad se formulará dentro del plazo de tres meses a partir de la publicación de la Ley, disposición o acto con fuerza de Ley impugnado', null, '1f423e14f627f5c2abaa6bfbac088f20eb71ce2910ebd7c7ad98acd777e8ecdc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1f423e14f627f5c2abaa6bfbac088f20eb71ce2910ebd7c7ad98acd777e8ecdc')
  returning id
), o as (
