insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Tribunal Constitucional, cuando la violación del derecho susceptible de amparo tenga su origen inmediato y directo en un acto u omisión de un órgano judicial, el plazo para interponer el recurso de amparo será de:', 'El art. 44.2 LOTC fija 30 días para el amparo contra actos u omisiones de órganos judiciales; el de 20 días del art. 43.2 LOTC es para las violaciones originadas por el Gobierno y las Administraciones.', 'jus_01_constitucion', (select id from public.topics where slug = 'jus-01-constitucion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1979-23709'), 'Art. 44.2 LOTC', '2. El plazo para interponer el recurso de amparo será de 30 días, a partir de la notificación de la resolución recaída en el proceso judicial.', null, 'f45e08d05a15cced4c09ebb5202e073de10b2060d3a4e61e3c6f74bbbb02391d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f45e08d05a15cced4c09ebb5202e073de10b2060d3a4e61e3c6f74bbbb02391d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '30 días, a partir de la notificación de la resolución recaída en el proceso judicial.', true), ('B', '20 días, a partir de la notificación de la resolución recaída en el proceso judicial.', false), ('C', '3 meses, a partir de la firmeza de la resolución judicial.', false), ('D', '10 días, a partir de la notificación de la resolución recaída en el proceso judicial.', false)) as v(label, body, ok)
)
