insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 4/2023, de 28 de febrero, para la igualdad real y efectiva de las personas trans y para la garantía de los derechos de las personas LGTBI (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-5366', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-02-igualdad', 'Tema 2. Igualdad y no discriminación: LO 3/2007, LO 1/2004, Ley 15/2022 y Ley 4/2023') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-02-igualdad' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 4/2023, para la igualdad real y efectiva de las personas trans y para la garantía de los derechos de las personas LGTBI, ¿quién puede solicitar por sí misma ante el Registro Civil la rectificación de la mención registral relativa al sexo?', 'El art. 43.1 de la Ley 4/2023 legitima a las personas españolas mayores de dieciséis años; entre catorce y dieciséis pueden solicitarla asistidas por sus representantes legales (art. 43.2), y entre doce y catorce, solo mediante autorización judicial (art. 43.4).', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-5366'), 'Art. 43.1 LGTBI', 'Toda persona de nacionalidad española mayor de dieciséis años podrá solicitar por sí misma ante el Registro Civil la rectificación de la mención registral relativa al sexo.', null, '14a333086f3fe89689c703a60e8a9c069cb05c502111f51a448f10b60402d514', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '14a333086f3fe89689c703a60e8a9c069cb05c502111f51a448f10b60402d514')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Toda persona de nacionalidad española mayor de dieciséis años.', true), ('B', 'Toda persona de nacionalidad española mayor de dieciocho años.', false), ('C', 'Toda persona residente en España mayor de catorce años.', false), ('D', 'Toda persona de nacionalidad española mayor de doce años.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 44 de la Ley 4/2023, la persona encargada del Registro Civil deberá citar a la persona legitimada para que comparezca de nuevo y ratifique su solicitud de rectificación registral del sexo en el plazo máximo de:', 'El art. 44.8 de la Ley 4/2023 fija tres meses para la segunda comparecencia de ratificación; después, la resolución debe dictarse en el plazo máximo de un mes desde esa segunda comparecencia (art. 44.9).', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-5366'), 'Art. 44.8 LGTBI', 'En el plazo máximo de tres meses desde la comparecencia inicial reiterando la solicitud de rectificación inicial, la persona encargada del Registro Civil deberá citar a la persona legitimada para que comparezca de nuevo y ratifique su solicitud, aseverando la persistencia de su decisión.', null, 'da3ee71d0fc3f36f9fc95c89154a903c7f91b680890bdc6162491915678de0bf', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'da3ee71d0fc3f36f9fc95c89154a903c7f91b680890bdc6162491915678de0bf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes desde la presentación de la solicitud.', false), ('B', 'Seis meses desde la comparecencia inicial.', false), ('C', 'Quince días desde la comparecencia inicial.', false), ('D', 'Tres meses desde la comparecencia inicial reiterando la solicitud.', true)) as v(label, body, ok)
)
