with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 4/2023, las personas que hubieran promovido la rectificación de la mención registral relativa al sexo podrán recuperar la mención que figuraba previamente transcurrido:', 'El art. 47 de la Ley 4/2023 permite la reversión transcurridos seis meses desde la inscripción, por el mismo procedimiento.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-5366'), 'Art. 47 LGTBI', 'Transcurridos seis meses desde la inscripción en el Registro Civil de la rectificación de la mención registral relativa al sexo, las personas que hubieran promovido dicha rectificación podrán recuperar la mención registral del sexo que figuraba previamente a dicha rectificación en el Registro Civil', null, '10e42b28f7b89725c390ad6cbece9b5323349a7c96548a3085643fbf2b3a48fa', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '10e42b28f7b89725c390ad6cbece9b5323349a7c96548a3085643fbf2b3a48fa')
