insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 15/2022, de 12 de julio, integral para la igualdad de trato y la no discriminación (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-02-igualdad', 'Tema 2. Igualdad y no discriminación: LO 3/2007, LO 1/2004, Ley 15/2022 y Ley 4/2023') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-02-igualdad' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 2 de la Ley 15/2022, integral para la igualdad de trato y la no discriminación, el derecho a la igualdad de trato se reconoce a toda persona:', 'El art. 2.1 de la Ley 15/2022 reconoce el derecho a toda persona sin atender a nacionalidad, edad ni situación de residencia, y enumera las causas de discriminación prohibidas.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589'), 'Art. 2.1 LITND', 'Se reconoce el derecho de toda persona a la igualdad de trato y no discriminación con independencia de su nacionalidad, de si son menores o mayores de edad o de si disfrutan o no de residencia legal.', null, '82937c0c0a4aabb1acb81aa0a7baae3d070fed80669afadb11c112343068a6dc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '82937c0c0a4aabb1acb81aa0a7baae3d070fed80669afadb11c112343068a6dc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre que sea de nacionalidad española o tenga residencia legal en España.', false), ('B', 'Mayor de edad, con independencia de su nacionalidad.', false), ('C', 'Que tenga nacionalidad de un Estado miembro de la Unión Europea.', false), ('D', 'Con independencia de su nacionalidad, de si son menores o mayores de edad o de si disfrutan o no de residencia legal.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 15/2022, la discriminación que se funda en una apreciación incorrecta acerca de las características de la persona o personas discriminadas se denomina:', 'El art. 6.2 de la Ley 15/2022 distingue la discriminación por asociación (por la relación con otra persona en quien concurre una causa) y la discriminación por error (basada en una apreciación incorrecta).', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589'), 'Art. 6.2 LITND', 'b) La discriminación por error es aquella que se funda en una apreciación incorrecta acerca de las características de la persona o personas discriminadas.', null, '6f6a45188d52cf1dee325ce27a376cc0605c9c0030d57273b640d6375c9e5fa4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6f6a45188d52cf1dee325ce27a376cc0605c9c0030d57273b640d6375c9e5fa4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Discriminación por error.', true), ('B', 'Discriminación por asociación.', false), ('C', 'Discriminación indirecta.', false), ('D', 'Discriminación interseccional.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley 15/2022, el mandato de la persona que ocupe la presidencia de la Autoridad Independiente para la Igualdad de Trato y la No Discriminación será de:', 'El art. 41.4 de la Ley 15/2022 fija un mandato de cinco años no renovable; la presidencia es nombrada por el Gobierno mediante Real Decreto, previa comparecencia ante las comisiones del Congreso y del Senado.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589'), 'Art. 41.4 LITND', 'Su mandato será de cinco años sin posibilidad de renovación.', null, '78401d4ea1c8f0968626c9831454b35338af361ab8a960e33ccd06e1874f5fd5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '78401d4ea1c8f0968626c9831454b35338af361ab8a960e33ccd06e1874f5fd5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuatro años, renovable por una sola vez.', false), ('B', 'Cinco años sin posibilidad de renovación.', true), ('C', 'Seis años sin posibilidad de renovación.', false), ('D', 'Cinco años, renovable por una sola vez.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 51 de la Ley 15/2022, las infracciones calificadas como muy graves prescribirán:', 'El art. 51 de la Ley 15/2022 fija la prescripción de las infracciones en un año (leves), tres años (graves) y cuatro años (muy graves); la de las sanciones, en un año, cuatro y cinco años, respectivamente.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589'), 'Art. 51 LITND', 'Las infracciones a que se refiere la presente ley calificadas como leves prescribirán al año, las calificadas como graves a los tres años y las calificadas como muy graves a los cuatro años.', null, 'd8b31c1750bece7eacccd035469efaa0d52f31f45e19b223bbbc867b3e5d22c7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd8b31c1750bece7eacccd035469efaa0d52f31f45e19b223bbbc867b3e5d22c7')
