insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-02-igualdad', 'Tema 2. Igualdad y no discriminación: LO 3/2007, LO 1/2004, Ley 15/2022 y Ley 4/2023') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-02-igualdad' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 3/2007, para la igualdad efectiva de mujeres y hombres, la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro constituye:', 'El art. 6.2 LOI define la discriminación indirecta; la directa (art. 6.1) es el trato menos favorable en atención al sexo frente a otra persona en situación comparable.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 6.2 LOI', 'Se considera discriminación indirecta por razón de sexo la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro, salvo que dicha disposición, criterio o práctica puedan justificarse objetivamente en atención a una finalidad legítima y que los medios para alcanzar dicha finalidad sean necesarios y adecuados.', null, '9e88faa877f0f64fabdc28999cc1cf61d82d9b49f72834f369c53e4692ee7707', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9e88faa877f0f64fabdc28999cc1cf61d82d9b49f72834f369c53e4692ee7707')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Discriminación indirecta por razón de sexo, salvo que pueda justificarse objetivamente en atención a una finalidad legítima con medios necesarios y adecuados.', true), ('B', 'Discriminación directa por razón de sexo, en todo caso.', false), ('C', 'Acoso por razón de sexo.', false), ('D', 'Una acción positiva, siempre que sea razonable y proporcionada.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley Orgánica 3/2007, todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad constituye:', 'El art. 8 LOI califica expresamente como discriminación directa por razón de sexo todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 8 LOI', 'Constituye discriminación directa por razón de sexo todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad.', null, '1c1c7c517454ceee0620bbd409df2640b3b68f43ca238e6f8244db00b44bdb27', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1c1c7c517454ceee0620bbd409df2640b3b68f43ca238e6f8244db00b44bdb27')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Discriminación indirecta por razón de sexo.', false), ('B', 'Acoso sexual.', false), ('C', 'Una infracción laboral leve, sin carácter discriminatorio.', false), ('D', 'Discriminación directa por razón de sexo.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 12 de la Ley Orgánica 3/2007, en los litigios sobre acoso sexual y acoso por razón de sexo, ¿quién está legitimado?', 'Aunque en general la legitimación corresponde a las personas físicas y jurídicas con interés legítimo (art. 12.2 LOI), en los litigios sobre acoso sexual y acoso por razón de sexo la persona acosada es la única legitimada (art. 12.3 LOI).', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 12.3 LOI', 'La persona acosada será la única legitimada en los litigios sobre acoso sexual y acoso por razón de sexo.', null, '5c6184066bbaa377ec8601f28d3458323281ed4a5bb86b04a20ca6121f69773c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5c6184066bbaa377ec8601f28d3458323281ed4a5bb86b04a20ca6121f69773c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La persona acosada y los sindicatos más representativos.', false), ('B', 'Cualquier persona física o jurídica con interés legítimo.', false), ('C', 'Únicamente la persona acosada.', true), ('D', 'La persona acosada y el Ministerio Fiscal, de forma indistinta.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 13 de la Ley Orgánica 3/2007, la regla por la que corresponde a la persona demandada probar la ausencia de discriminación cuando las alegaciones de la parte actora se fundamenten en actuaciones discriminatorias por razón de sexo:', 'El art. 13.1 LOI invierte la carga de la prueba en los procedimientos en que se aleguen actuaciones discriminatorias por razón de sexo, pero el art. 13.2 la excluye de los procesos penales.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 13 LOI', 'corresponderá a la persona demandada probar la ausencia de discriminación en las medidas adoptadas y su proporcionalidad. […] 2. Lo establecido en el apartado anterior no será de aplicación a los procesos penales.', null, 'e1aad0786dfaea7642879ce8d07dc9e587911c1db1b84eb986bd77335bea8870', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e1aad0786dfaea7642879ce8d07dc9e587911c1db1b84eb986bd77335bea8870')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No es de aplicación a los procesos contencioso-administrativos.', false), ('B', 'No es de aplicación a los procesos penales.', true), ('C', 'Solo se aplica en los procesos laborales.', false), ('D', 'Se aplica en todos los órdenes jurisdiccionales sin excepción.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 45 de la Ley Orgánica 3/2007, ¿qué empresas deben elaborar y aplicar un plan de igualdad, con carácter general?', 'El art. 45.2 LOI obliga a las empresas de cincuenta o más trabajadores a elaborar y aplicar un plan de igualdad; también deben hacerlo cuando lo establezca el convenio colectivo o lo acuerde la autoridad laboral (arts. 45.3 y 45.4), y es voluntario para las demás (art. 45.5).', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'Art. 45.2 LOI', 'En el caso de las empresas de cincuenta o más trabajadores, las medidas de igualdad a que se refiere el apartado anterior deberán dirigirse a la elaboración y aplicación de un plan de igualdad', null, '0c8ad39bd5f8ec48441925b96663a6ffaf6b5f604a11bfd27f749d11d298b937', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0c8ad39bd5f8ec48441925b96663a6ffaf6b5f604a11bfd27f749d11d298b937')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las empresas de doscientos cincuenta o más trabajadores.', false), ('B', 'Las empresas de cincuenta o más trabajadores.', true), ('C', 'Las empresas de cien o más trabajadores.', false), ('D', 'Todas las empresas, cualquiera que sea su plantilla.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A los efectos de la Ley Orgánica 3/2007, se entiende por composición equilibrada la presencia de mujeres y hombres de forma que, en el conjunto a que se refiera, las personas de cada sexo:', 'La disposición adicional primera LOI fija la horquilla 60 %-40 %.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'DA 1.ª LOI', 'A los efectos de esta Ley, se entenderá por composición equilibrada la presencia de mujeres y hombres de forma que, en el conjunto a que se refiera, las personas de cada sexo no superen el sesenta por ciento ni sean menos del cuarenta por ciento.', null, 'cd1dcc4d8a33539593c09623c112bd857e76dcf40a051b72a82b0bcd5a94d3a4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cd1dcc4d8a33539593c09623c112bd857e76dcf40a051b72a82b0bcd5a94d3a4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No superen el setenta por ciento ni sean menos del treinta por ciento.', false), ('B', 'Representen exactamente el cincuenta por ciento.', false), ('C', 'No superen el sesenta por ciento ni sean menos del cuarenta por ciento.', true), ('D', 'No superen el cincuenta y cinco por ciento ni sean menos del cuarenta y cinco por ciento.', false)) as v(label, body, ok)
)
