with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la exposición de motivos de la Ley Orgánica 1/2004, entre los antecedentes internacionales de la ley, ¿qué foro reconoció ya que la violencia contra las mujeres es un obstáculo para lograr los objetivos de igualdad, desarrollo y paz?', 'La exposición de motivos (apartado I) recuerda que la ONU, en la IV Conferencia Mundial de 1995, reconoció que la violencia contra las mujeres es un obstáculo para la igualdad, el desarrollo y la paz y la definió como manifestación de relaciones de poder históricamente desiguales.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Exposición de motivos I LOVG', 'La Organización de Naciones Unidas en la IV Conferencia Mundial de 1995 reconoció ya que la violencia contra las mujeres es un obstáculo para lograr los objetivos de igualdad, desarrollo y paz y viola y menoscaba el disfrute de los derechos humanos y las libertades fundamentales.', null, '17cf86aa2730ee3d2c6b5ee835c6aa8e0f24298aa68c04c9e786331f241148f5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '17cf86aa2730ee3d2c6b5ee835c6aa8e0f24298aa68c04c9e786331f241148f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La IV Conferencia Mundial de 1995 de la Organización de Naciones Unidas.', true), ('B', 'El Consejo de Europa en el Convenio de Estambul de 2011.', false), ('C', 'La Asamblea General de Naciones Unidas en 1979.', false), ('D', 'El Tribunal Europeo de Derechos Humanos en 2003.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley Orgánica 1/2004, la ley actúa contra la violencia que se ejerce sobre las mujeres por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad:', 'El art. 1.1 LOVG incluye expresamente las relaciones similares de afectividad «aun sin convivencia».', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.1 LOVG', 'se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.', null, '33a2ee3d01369f246f85017bd010771fc265deb3ff354f9e7315388db114ebab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '33a2ee3d01369f246f85017bd010771fc265deb3ff354f9e7315388db114ebab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre que exista o haya existido convivencia.', false), ('B', 'Solo si la relación se ha inscrito en un registro público.', false), ('C', 'Solo si la relación ha durado al menos un año.', false), ('D', 'Aun sin convivencia.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
