with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 1 de la Ley Orgánica 1/2004, la violencia de género a que se refiere la ley comprende también la violencia que, con el objetivo de causar perjuicio o daño a las mujeres, se ejerza:', 'El art. 1.4 LOVG incluye la llamada violencia vicaria: la ejercida sobre familiares o allegados menores de edad para dañar a la mujer, por las personas del apartado 1.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.4 LOVG', 'La violencia de género a que se refiere esta Ley también comprende la violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus familiares o allegados menores de edad por parte de las personas indicadas en el apartado primero.', null, '824ddcabba0726e3b09c84e1d930b4413bfe07be0764a4ad92f1fee9b37bcb0a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '824ddcabba0726e3b09c84e1d930b4413bfe07be0764a4ad92f1fee9b37bcb0a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sobre cualquier persona con la que convivan, sea cual sea su edad.', false), ('B', 'Sobre sus familiares o allegados menores de edad por parte de las personas indicadas en el apartado primero.', true), ('C', 'Sobre sus bienes, únicamente cuando sean de titularidad exclusiva de la mujer.', false), ('D', 'Sobre sus compañeros de trabajo por parte de cualquier persona.', false)) as v(label, body, ok)
)
