with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 20 de la Ley Orgánica 1/2004, las víctimas de violencia de género tienen derecho a recibir asesoramiento jurídico gratuito:', 'El art. 20.1 LOVG reconoce el asesoramiento jurídico gratuito en el momento inmediatamente previo a la denuncia y la defensa y representación gratuitas por abogado y procurador en los procesos y procedimientos administrativos con causa directa o indirecta en la violencia padecida.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 20.1 LOVG', 'Las víctimas de violencia de género tienen derecho a recibir asesoramiento jurídico gratuito en el momento inmediatamente previo a la interposición de la denuncia', null, '71dc60860828af58253a2109176cef90120e50d8feaf42e0505200e51525fa71', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '71dc60860828af58253a2109176cef90120e50d8feaf42e0505200e51525fa71')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
