with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 23 de la Ley Orgánica 1/2004, además de por sentencia condenatoria u orden de protección, las situaciones de violencia de género que dan lugar al reconocimiento de los derechos de la ley pueden acreditarse mediante:', 'El art. 23 LOVG admite como títulos de acreditación la sentencia condenatoria, la orden de protección u otra resolución judicial que acuerde una medida cautelar, el informe del Ministerio Fiscal con indicios y también los informes de los servicios sociales, especializados o de acogida.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 23 LOVG', 'Las situaciones de violencia de género que dan lugar al reconocimiento de los derechos regulados en esta ley se acreditarán mediante una sentencia condenatoria por cualquiera de las manifestaciones de la violencia contra las mujeres previstas en esta ley, una orden de protección o cualquier otra resolución judicial que acuerde una medida cautelar a favor de la víctima, o bien por el informe del Ministerio Fiscal que indique la existencia de indicios de que la demandante es víctima de violencia de género.', null, 'ec20126ca004cd4e54d194793dcff946cf312b05dfcb4101942c47e8bfc1410d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ec20126ca004cd4e54d194793dcff946cf312b05dfcb4101942c47e8bfc1410d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La declaración responsable de la propia víctima ante el órgano que concede el derecho.', false), ('B', 'La simple presentación de la denuncia ante las Fuerzas y Cuerpos de Seguridad.', false), ('C', 'El certificado del Letrado de la Administración de Justicia que acredite la incoación de diligencias.', false), ('D', 'El informe del Ministerio Fiscal que indique la existencia de indicios de que la demandante es víctima de violencia de género.', true)) as v(label, body, ok)
)
