with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 27 de la Ley Orgánica 1/2004, con carácter general, el importe de la ayuda social de pago único a las víctimas de violencia de género sin responsabilidades familiares será equivalente al de:', 'El art. 27.2 LOVG fija seis meses de subsidio (doce si la víctima tiene una discapacidad igual o superior al 33 %); con responsabilidades familiares puede llegar a 18 o 24 meses (art. 27.4).', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 27.2 LOVG', 'El importe de esta ayuda será equivalente al de seis meses de subsidio por desempleo. Cuando la víctima de la violencia ejercida contra la mujer tuviera reconocida oficialmente una discapacidad en grado igual o superior al 33 por 100, el importe será equivalente a doce meses de subsidio por desempleo.', null, 'b477939d272802887535e234ebfcc7064aa2f9e513e91c614ad1c9eac0847dc5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b477939d272802887535e234ebfcc7064aa2f9e513e91c614ad1c9eac0847dc5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Doce meses de subsidio por desempleo.', false), ('B', 'Tres meses de subsidio por desempleo.', false), ('C', 'Seis meses de subsidio por desempleo.', true), ('D', 'Dieciocho meses de subsidio por desempleo.', false)) as v(label, body, ok)
)
