with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 1/2004, ¿qué órgano formula las políticas públicas en relación con la violencia de género a desarrollar por el Gobierno y elabora la Macroencuesta de Violencia contra las Mujeres?', 'El art. 29.1 LOVG atribuye esas funciones a la Delegación del Gobierno contra la Violencia de Género, adscrita al Ministerio de Igualdad o al departamento competente; el Observatorio (art. 30) es un órgano colegiado de asesoramiento y evaluación.', 'jus_02_igualdad', (select id from public.topics where slug = 'jus-02-igualdad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 29.1 LOVG', 'La Delegación del Gobierno contra la Violencia de Género, adscrita al Ministerio de Igualdad o al departamento con competencias en la materia, formulará las políticas públicas en relación con la violencia de género a desarrollar por el Gobierno y elaborará la Macroencuesta de Violencia contra las Mujeres.', null, '931b8ca8b469e6d448c758d2c8b09af4e6351fa7a7340bd19c28bcce9e670cd1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '931b8ca8b469e6d448c758d2c8b09af4e6351fa7a7340bd19c28bcce9e670cd1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Observatorio Estatal de Violencia sobre la Mujer.', false), ('B', 'El Consejo de Participación de la Mujer.', false), ('C', 'La Delegación del Gobierno contra la Violencia de Género.', true), ('D', 'La Fiscalía contra la Violencia sobre la Mujer.', false)) as v(label, body, ok)
)
