with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 97 de la Constitución Española, el Gobierno ejerce:', 'El art. 97 CE dispone que el Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado, y ejerce la función ejecutiva y la potestad reglamentaria.', 'jus_03_gobierno', (select id from public.topics where slug = 'jus-03-gobierno'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 97 CE', 'El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado. Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.', null, '4063406003c3e34e5581a19f84bb0d825797bb571d2e1a504e7792c0165cb322', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4063406003c3e34e5581a19f84bb0d825797bb571d2e1a504e7792c0165cb322')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La función ejecutiva y la potestad legislativa ordinaria.', false), ('B', 'La función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.', true), ('C', 'La potestad reglamentaria y el control de la acción de las Cortes Generales.', false), ('D', 'La función ejecutiva y la potestad jurisdiccional en materia administrativa.', false)) as v(label, body, ok)
)
