select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 99 de la Constitución, si en la primera votación de investidura el candidato no obtiene la mayoría absoluta del Congreso, la misma propuesta se someterá a nueva votación:', 'El art. 99.3 CE exige mayoría absoluta en la primera votación y, en su defecto, mayoría simple en una nueva votación cuarenta y ocho horas después.', 'jus_03_gobierno', (select id from public.topics where slug = 'jus-03-gobierno'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 99.3 CE', 'Si el Congreso de los Diputados, por el voto de la mayoría absoluta de sus miembros, otorgare su confianza a dicho candidato, el Rey le nombrará Presidente. De no alcanzarse dicha mayoría, se someterá la misma propuesta a nueva votación cuarenta y ocho horas después de la anterior, y la confianza se entenderá otorgada si obtuviere la mayoría simple.', null, 'e08a50fd2b0e41c1c5077cc8599fa1c02afe14bc4a84ffd74beb38e6b23de39e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e08a50fd2b0e41c1c5077cc8599fa1c02afe14bc4a84ffd74beb38e6b23de39e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Veinticuatro horas después de la anterior, y la confianza se entenderá otorgada si obtuviere la mayoría simple.', false), ('B', 'Cuarenta y ocho horas después de la anterior, exigiéndose de nuevo la mayoría absoluta.', false), ('C', 'Siete días después de la anterior, y la confianza se entenderá otorgada por mayoría de tres quintos.', false), ('D', 'Cuarenta y ocho horas después de la anterior, y la confianza se entenderá otorgada si obtuviere la mayoría simple.', true)) as v(label, body, ok)
)
