with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 99 de la Constitución, si ningún candidato obtiene la confianza del Congreso, el Rey disolverá ambas Cámaras y convocará nuevas elecciones una vez transcurrido el plazo de:', 'El art. 99.5 CE fija dos meses desde la primera votación de investidura; la disolución se refrenda por el Presidente del Congreso.', 'jus_03_gobierno', (select id from public.topics where slug = 'jus-03-gobierno'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 99.5 CE', 'Si transcurrido el plazo de dos meses, a partir de la primera votación de investidura, ningún candidato hubiere obtenido la confianza del Congreso, el Rey disolverá ambas Cámaras y convocará nuevas elecciones con el refrendo del Presidente del Congreso.', null, '81a6ca27e38afd48a0610b53ee5a502a243da075c9b656ebf94d8e76ccfbbf6e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '81a6ca27e38afd48a0610b53ee5a502a243da075c9b656ebf94d8e76ccfbbf6e')
  returning id
