with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 101 de la Constitución, ¿en cuál de los siguientes supuestos cesa el Gobierno?', 'El art. 101.1 CE enumera las causas de cese: celebración de elecciones generales, pérdida de la confianza parlamentaria en los casos constitucionales y dimisión o fallecimiento del Presidente. El Gobierno cesante continúa en funciones hasta la toma de posesión del nuevo.', 'jus_03_gobierno', (select id from public.topics where slug = 'jus-03-gobierno'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 101.1 CE', 'El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de la confianza parlamentaria previstos en la Constitución, o por dimisión o fallecimiento de su Presidente.', null, 'd2f91e7df718a7a12b206903231873463923d7a6d78b6807d77bf37335d2efda', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd2f91e7df718a7a12b206903231873463923d7a6d78b6807d77bf37335d2efda')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por dimisión o fallecimiento de su Presidente.', true), ('B', 'Por dimisión de cualquiera de sus Vicepresidentes.', false), ('C', 'Por la aprobación de una moción de reprobación de un Ministro en el Senado.', false), ('D', 'Por el rechazo del Proyecto de Ley de Presupuestos Generales del Estado.', false)) as v(label, body, ok)
)
