with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 102 de la Constitución, si la acusación contra el Presidente o los demás miembros del Gobierno fuere por traición o por cualquier delito contra la seguridad del Estado en el ejercicio de sus funciones, solo podrá ser planteada:', 'El art. 102.2 CE exige iniciativa de una cuarta parte del Congreso y aprobación por su mayoría absoluta; la responsabilidad criminal se exige ante la Sala de lo Penal del Tribunal Supremo (art. 102.1) y no cabe la prerrogativa de gracia (art. 102.3).', 'jus_03_gobierno', (select id from public.topics where slug = 'jus-03-gobierno'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 102.2 CE', 'Si la acusación fuere por traición o por cualquier delito contra la seguridad del Estado en el ejercicio de sus funciones, sólo podrá ser planteada por iniciativa de la cuarta parte de los miembros del Congreso, y con la aprobación de la mayoría absoluta del mismo.', null, '24e50b737904b6c04c55aa530c8c575bc19b82c467c48a09e3a89c9237b4b71f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '24e50b737904b6c04c55aa530c8c575bc19b82c467c48a09e3a89c9237b4b71f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por iniciativa de la cuarta parte de los miembros del Congreso, y con la aprobación de la mayoría absoluta del mismo.', true), ('B', 'Por iniciativa de la décima parte de los miembros del Congreso, y con la aprobación de la mayoría simple del mismo.', false), ('C', 'Por iniciativa del Ministerio Fiscal, previa autorización del Senado por mayoría absoluta.', false), ('D', 'Por iniciativa de la cuarta parte de los miembros de cada Cámara, y con la aprobación de tres quintos de ambas.', false)) as v(label, body, ok)
)
