insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 1451/2005, de 7 de diciembre, Reglamento de Ingreso, Provisión de Puestos de Trabajo y Promoción Profesional del Personal Funcionario al Servicio de la Administración de Justicia (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2005-21264', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
