with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 137 de la Constitución Española, el Estado se organiza territorialmente en:', 'El art. 137 CE enumera municipios, provincias y Comunidades Autónomas, y reconoce a todas estas entidades autonomía para la gestión de sus respectivos intereses.', 'jus_04_organizacion_territorial', (select id from public.topics where slug = 'jus-04-organizacion-territorial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 137 CE', 'El Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan. Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses.', null, 'ec2f4c65dcfb689fb5dec35dbfdb29ae4adf0a40952ba6f8cf290f7109d99c43', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ec2f4c65dcfb689fb5dec35dbfdb29ae4adf0a40952ba6f8cf290f7109d99c43')
  returning id
), o as (
