with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 151 de la Constitución, para no tener que esperar el plazo de cinco años del artículo 148.2, la iniciativa autonómica debía ser acordada, además de por las Diputaciones u órganos interinsulares, por:', 'El art. 151.1 CE exige tres cuartas partes de los municipios con la mayoría del censo de cada provincia y ratificación en referéndum por el voto afirmativo de la mayoría absoluta de los electores de cada provincia.', 'jus_04_organizacion_territorial', (select id from public.topics where slug = 'jus-04-organizacion-territorial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 151.1 CE', 'por las tres cuartas partes de los municipios de cada una de las provincias afectadas que representen, al menos, la mayoría del censo electoral de cada una de ellas y dicha iniciativa sea ratificada mediante referéndum por el voto afirmativo de la mayoría absoluta de los electores de cada provincia', null, 'cc95125f76297811e2c21acada4abdeb2ca21f06220a6d97f9fc5968cda8af26', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cc95125f76297811e2c21acada4abdeb2ca21f06220a6d97f9fc5968cda8af26')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
