  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 7/1985, la Junta de Gobierno Local existe:', 'El art. 20.1.b) LBRL vincula la existencia obligatoria de la Junta de Gobierno Local a los municipios de más de 5.000 habitantes; el Alcalde, los Tenientes de Alcalde y el Pleno existen en todos (art. 20.1.a).', 'jus_04_organizacion_territorial', (select id from public.topics where slug = 'jus-04-organizacion-territorial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392'), 'Art. 20.1 LBRL', 'b) La Junta de Gobierno Local existe en todos los municipios con población superior a 5.000 habitantes y en los de menos, cuando así lo disponga su reglamento orgánico o así lo acuerde el Pleno de su ayuntamiento.', null, '0db79b2d0d28b088eb5c8a1f967909803a5302fc58208264f89ab1e178dea468', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0db79b2d0d28b088eb5c8a1f967909803a5302fc58208264f89ab1e178dea468')
  returning id
