  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 31 del Estatuto Orgánico del Ministerio Fiscal, el mandato del Fiscal General del Estado:', 'El art. 31 EOMF fija un mandato de cuatro años, no renovable salvo ejercicio inferior a dos años. Entre las causas de cese anticipado figura el cese del Gobierno que lo hubiera propuesto.', 'jus_06_poder_judicial', (select id from public.topics where slug = 'jus-06-poder-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1982-837'), 'Art. 31 EOMF', 'Uno. El mandato del Fiscal General del Estado tendrá una duración de cuatro años. […] Dos. El mandato del Fiscal General del Estado no podrá ser renovado, excepto en los supuestos en que el titular hubiera ostentado el cargo durante un periodo inferior a dos años.', null, '323251475e7031d058978cf114aa943912045d15723c664b97d7529ec9906f87', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '323251475e7031d058978cf114aa943912045d15723c664b97d7529ec9906f87')
