with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 9 de la Ley Orgánica del Poder Judicial, ¿qué orden jurisdiccional conoce, además de las materias que le son propias, de todas aquellas que no estén atribuidas a otro orden jurisdiccional?', 'El art. 9.2 LOPJ atribuye al orden civil una competencia residual: conoce de las materias que le son propias y de todas las que no estén atribuidas a otro orden jurisdiccional.', 'jus_06_poder_judicial', (select id from public.topics where slug = 'jus-06-poder-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 9.2 LOPJ', '2. Los jueces y juezas, así como los Tribunales del orden civil conocerán, además de las materias que les son propias, de todas aquellas que no estén atribuidas a otro orden jurisdiccional.', null, '9d5a08ccd9366f4ddb18b0c833143550ad082bb43801b8bae5037d93169cbc86', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9d5a08ccd9366f4ddb18b0c833143550ad082bb43801b8bae5037d93169cbc86')
  returning id
