  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El orden penal.', false), ('B', 'El orden contencioso-administrativo.', false), ('C', 'El orden civil.', true), ('D', 'El orden social.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 12 de la Ley Orgánica del Poder Judicial, ¿pueden el Consejo General del Poder Judicial o los Tribunales superiores dictar instrucciones a sus inferiores sobre la aplicación o interpretación del ordenamiento jurídico en el ejercicio de la función jurisdiccional?', 'El art. 12.3 LOPJ prohíbe a Jueces, Tribunales, órganos de gobierno y al CGPJ dictar instrucciones, generales o particulares, a sus inferiores sobre la aplicación o interpretación del ordenamiento jurídico. Solo pueden corregirla al resolver los recursos legalmente previstos (art. 12.2).', 'jus_06_poder_judicial', (select id from public.topics where slug = 'jus-06-poder-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 12.3 LOPJ', '3. Tampoco podrán los Jueces y Tribunales, órganos de gobierno de los mismos o el Consejo General del Poder Judicial dictar instrucciones, de carácter general o particular, dirigidas a sus inferiores, sobre la aplicación o interpretación del ordenamiento jurídico que lleven a cabo en el ejercicio de su función jurisdiccional.', null, '48bc09628e0d7eeec276835ce417ed29f96fe7c19d2af985cea958ccc745a18d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '48bc09628e0d7eeec276835ce417ed29f96fe7c19d2af985cea958ccc745a18d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
