  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 561 de la Ley Orgánica del Poder Judicial, el Consejo General del Poder Judicial emitirá los informes sobre los anteproyectos de ley y disposiciones generales sometidos a su consideración en el plazo improrrogable de:', 'El art. 561.2 LOPJ fija treinta días (quince si es urgente). Si el informe no se emite en plazo, se tiene por cumplido el trámite (art. 561.3).', 'jus_06_poder_judicial', (select id from public.topics where slug = 'jus-06-poder-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 561.2 LOPJ', '2. El Consejo General del Poder Judicial emitirá su informe en el plazo improrrogable de treinta días. Si en la orden de remisión se hiciere constar la urgencia del informe, el plazo será de quince días.', null, 'fede7c3ee4919ee501913d59660e13509f24c5c9b965c985567bf03b2d899e71', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fede7c3ee4919ee501913d59660e13509f24c5c9b965c985567bf03b2d899e71')
