with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley Orgánica del Poder Judicial, quienes ejerciendo un empleo, cargo o profesión incompatible fueren nombrados Jueces o Magistrados deberán optar por uno u otro cargo, o cesar en la actividad incompatible, en el plazo de:', 'El art. 390.1 LOPJ da ocho días para optar; si no se ejerce la opción, se entiende que se renuncia al nombramiento judicial (art. 390.2).', 'jus_06_poder_judicial', (select id from public.topics where slug = 'jus-06-poder-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 390.1 LOPJ', '1. Los que ejerciendo cualquier empleo, cargo o profesión de los expresados en el artículo anterior fueren nombrados Jueces o Magistrados, deberán optar, en el plazo de ocho días, por uno u otro cargo, o cesar en el ejercicio de la actividad incompatible.', null, 'cd4ed6b0afa13af54826101d0c297045a338b2fd128c76023747d8fff70ac052', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cd4ed6b0afa13af54826101d0c297045a338b2fd128c76023747d8fff70ac052')
  returning id
), o as (
