with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 53 de la Ley Orgánica del Poder Judicial, el Tribunal Supremo, con sede en la villa de Madrid, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de:', 'El art. 53 LOPJ (y el art. 123.1 CE) exceptúa las garantías constitucionales, que corresponden al Tribunal Constitucional. Ningún otro órgano puede tener el título de Supremo.', 'jus_07_ts_an_tsj_ap', (select id from public.topics where slug = 'jus-07-ts-an-tsj-ap'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 53 LOPJ', 'El Tribunal Supremo, con sede en la villa de Madrid, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías Constitucionales. Tendrá jurisdicción en toda España y ningún otro podrá tener el título de Supremo.', null, '945d99b2d190ee898945d2d338b9c44e1926adb0831afb2931ded30019e0431b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '945d99b2d190ee898945d2d338b9c44e1926adb0831afb2931ded30019e0431b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Derecho de la Unión Europea.', false), ('B', 'Jurisdicción militar.', false), ('C', 'Garantías constitucionales.', true), ('D', 'Derecho civil foral o especial.', false)) as v(label, body, ok)
)
