  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley Orgánica del Poder Judicial, ¿qué órgano es competente para la instrucción y enjuiciamiento de las causas penales contra los Diputados y Senadores?', 'El art. 57.1.2.º LOPJ atribuye a la Sala Segunda del Tribunal Supremo la instrucción y enjuiciamiento de las causas contra, entre otros, el Presidente del Gobierno, los miembros del Gobierno, los Diputados y Senadores y el Fiscal General del Estado.', 'jus_07_ts_an_tsj_ap', (select id from public.topics where slug = 'jus-07-ts-an-tsj-ap'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 57.1 LOPJ', '2.º De la instrucción y enjuiciamiento de las causas contra el Presidente del Gobierno, Presidentes del Congreso y del Senado, Presidente del Tribunal Supremo y del Consejo General del Poder Judicial, Presidente del Tribunal Constitucional, miembros del Gobierno, Diputados y Senadores', null, '9cf77217f966cb427ab9da1e91e42cbe2995b3ade8463dc3ce74a8d2982af045', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9cf77217f966cb427ab9da1e91e42cbe2995b3ade8463dc3ce74a8d2982af045')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Sala de lo Penal de la Audiencia Nacional.', false), ('B', 'La Sala de lo Civil y Penal del Tribunal Superior de Justicia de la Comunidad Autónoma donde se cometió el hecho.', false), ('C', 'La Audiencia Provincial de Madrid.', false), ('D', 'La Sala de lo Penal del Tribunal Supremo.', true)) as v(label, body, ok)
)
