insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 65 de la Ley Orgánica del Poder Judicial, la Sala de lo Penal de la Audiencia Nacional conocerá, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, del enjuiciamiento de las causas por:', 'El art. 65.1.º e) LOPJ incluye los delitos cometidos fuera del territorio nacional. El tráfico de drogas solo le corresponde si lo cometen bandas o grupos organizados con efectos en distintas Audiencias, y las causas contra Diputados y Senadores son de la Sala de lo Penal del Tribunal Supremo.', 'jus_07_ts_an_tsj_ap', (select id from public.topics where slug = 'jus-07-ts-an-tsj-ap'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 65 LOPJ', 'e) Delitos cometidos fuera del territorio nacional, cuando conforme a las leyes o a los tratados corresponda su enjuiciamiento a los Tribunales españoles.', null, '4059a0174aa16b83154c6e4a5f0579de618baf02c509a02321206e724e580860', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4059a0174aa16b83154c6e4a5f0579de618baf02c509a02321206e724e580860')
