  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, la resolución de los procedimientos judiciales de extradición pasiva corresponde a:', 'El art. 65.4.º LOPJ atribuye a la Sala de lo Penal de la Audiencia Nacional la resolución de los procedimientos de extradición pasiva, con independencia del lugar de residencia o detención.', 'jus_07_ts_an_tsj_ap', (select id from public.topics where slug = 'jus-07-ts-an-tsj-ap'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 65 LOPJ', 'la resolución de los procedimientos judiciales de extradición pasiva, sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento.', null, '373b405fb77816bb682aebc197e9483e56b185c946d1c5329ab8da6e5b9536cb', false
