insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, la Sala de lo Social de la Audiencia Nacional conocerá en única instancia de los procesos sobre conflictos colectivos cuya resolución haya de surtir efecto en un ámbito territorial:', 'El art. 67 LOPJ atribuye a la Sala de lo Social de la Audiencia Nacional los conflictos colectivos y la impugnación de convenios colectivos de ámbito superior al de una Comunidad Autónoma. Los de ámbito no superior a la Comunidad corresponden a la Sala de lo Social del TSJ (art. 75).', 'jus_07_ts_an_tsj_ap', (select id from public.topics where slug = 'jus-07-ts-an-tsj-ap'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 67 LOPJ', '2.º De los procesos sobre conflictos colectivos cuya resolución haya de surtir efecto en un ámbito territorial superior al de una Comunidad Autónoma.', null, '728c92797770e865746f305b75c79230015e31ecfb0258569280139caeae70c1', false
