  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, las apelaciones promovidas contra sentencias y autos dictados por las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia se conocen, en segunda instancia, por:', 'El art. 74.2 LOPJ atribuye a las Salas de lo Contencioso-Administrativo de los TSJ las apelaciones y los recursos de queja contra resoluciones de las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia.', 'jus_07_ts_an_tsj_ap', (select id from public.topics where slug = 'jus-07-ts-an-tsj-ap'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 74.2 LOPJ', '2. Conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados en las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia y de los correspondientes recursos de queja.', null, '035d1f4c16a6be4d64ee9cacb2c3202144ee79fe22b29bdd5634e3f25608c25c', false
