with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 80 de la Ley Orgánica del Poder Judicial, las Audiencias Provinciales tendrán su sede:', 'El art. 80.1 LOPJ sitúa la sede de las Audiencias Provinciales en la capital de la provincia y extiende su jurisdicción a toda ella, aunque pueden crearse Secciones fuera de la capital (art. 80.2).', 'jus_07_ts_an_tsj_ap', (select id from public.topics where slug = 'jus-07-ts-an-tsj-ap'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 80.1 LOPJ', '1. Las Audiencias Provinciales, que tendrán su sede en la capital de la provincia, de la que tomarán su nombre, extenderán su jurisdicción a toda ella', null, '03ac510435dfa2b6180f2a9af22e7af3b2b2efa28dc2f2d39106c9f3dcf1da99', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '03ac510435dfa2b6180f2a9af22e7af3b2b2efa28dc2f2d39106c9f3dcf1da99')
