with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, con carácter general las Audiencias Provinciales se compondrán de:', 'El art. 81.1 LOPJ fija la composición ordinaria: Presidente y dos o más magistrados; pueden existir dos o más Secciones con la misma composición. Si hay pocos asuntos, la plantilla puede ser de uno a dos magistrados, incluido el Presidente (art. 81.2).', 'jus_07_ts_an_tsj_ap', (select id from public.topics where slug = 'jus-07-ts-an-tsj-ap'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 81.1 LOPJ', '1. Las Audiencias Provinciales se compondrán de un Presidente y dos o más magistrados.', null, '74f46bbfc6b18889a6ff10f373be8807d82e1056b01543d31de953cfa126a913', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '74f46bbfc6b18889a6ff10f373be8807d82e1056b01543d31de953cfa126a913')
  returning id
