)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 84 de la Ley Orgánica del Poder Judicial, las Secciones del Tribunal de Instancia contarán con una Presidencia de Sección cuando concurran, entre otras circunstancias, que en la Sección existan:', 'El art. 84.3 LOPJ exige que haya dos o más Secciones en el Tribunal, ocho o más plazas en la Sección y doce o más plazas en todo el Tribunal. Cada Tribunal de Instancia cuenta siempre con una Presidencia.', 'jus_08_tribunales_instancia', (select id from public.topics where slug = 'jus-08-tribunales-instancia'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 84.3 LOPJ', 'a) Que en el Tribunal de Instancia hubiere dos o más Secciones. b) Que en la Sección de que se trate existan ocho o más plazas judiciales. c) Que el número total de plazas judiciales del Tribunal de Instancia sea igual o superior a doce.', null, 'e9951bf18d26c37a2dfd098049301974d95c0157186a65344a7978302dccd377', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e9951bf18d26c37a2dfd098049301974d95c0157186a65344a7978302dccd377')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ocho o más plazas judiciales y que el número total de plazas judiciales del Tribunal de Instancia sea igual o superior a doce.', true), ('B', 'Cinco o más plazas judiciales y que el número total de plazas judiciales del Tribunal de Instancia sea igual o superior a diez.', false), ('C', 'Diez o más plazas judiciales y que el número total de plazas judiciales del Tribunal de Instancia sea igual o superior a veinte.', false), ('D', 'Tres o más plazas judiciales, cualquiera que sea el número total de plazas del Tribunal de Instancia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, ¿qué Sección del Tribunal de Instancia conoce, en el orden civil, de los recursos que establezca la ley contra las resoluciones de los jueces y las juezas de paz del partido?', 'El art. 85.3.º LOPJ atribuye a las Secciones Civiles o Únicas de los Tribunales de Instancia los recursos contra las resoluciones civiles de los jueces de paz del partido, además de los juicios no atribuidos a otros órganos y la jurisdicción voluntaria.', 'jus_08_tribunales_instancia', (select id from public.topics where slug = 'jus-08-tribunales-instancia'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 85 LOPJ', 'Con carácter general, en los Tribunales de Instancia, las Secciones Civiles o las Civiles y de Instrucción que constituyan una Sección Única extenderán su jurisdicción a un partido judicial. Estas Secciones conocerán, en el orden civil: […] 3.º De los recursos que establezca la ley contra las resoluciones de los jueces y las juezas de paz del partido.', null, 'a715e2cd7211aecfc283cfa591aac0d1953030ae005de44765517c0b609620df', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a715e2cd7211aecfc283cfa591aac0d1953030ae005de44765517c0b609620df')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Sección de Familia, Infancia y Capacidad.', false), ('B', 'La Audiencia Provincial, en todo caso.', false), ('C', 'La Sección Civil o la Sección Única, Civil y de Instrucción.', true), ('D', 'La Sección de lo Mercantil.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 86 de la Ley Orgánica del Poder Judicial, la jurisdicción de las Secciones de Familia, Infancia y Capacidad es exclusiva y excluyente, entre otras materias, en:', 'El art. 86.5 g) LOPJ incluye entre las materias exclusivas de las Secciones de Familia, Infancia y Capacidad las medidas de apoyo a personas con discapacidad y los internamientos no voluntarios. Las sociedades mercantiles son de la Sección de lo Mercantil (art. 87) y el habeas corpus de las Secciones de Instrucción (art. 88).', 'jus_08_tribunales_instancia', (select id from public.topics where slug = 'jus-08-tribunales-instancia'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 86.5 LOPJ', 'g) Las que versen sobre adopción de medidas judiciales de apoyo a personas con discapacidad, incluyendo los internamientos no voluntarios por razón de trastorno psíquico.', null, '5717ec30e8c4972e77a1377a3e6e854a47657fbb3f03f9f81b4c0259475107e4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5717ec30e8c4972e77a1377a3e6e854a47657fbb3f03f9f81b4c0259475107e4')
  returning id
), o as (
