  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las acciones relativas a sociedades mercantiles y cooperativas.', false), ('B', 'La adopción de medidas judiciales de apoyo a personas con discapacidad, incluyendo los internamientos no voluntarios por razón de trastorno psíquico.', true), ('C', 'Los procedimientos de habeas corpus.', false), ('D', 'Las reclamaciones de cantidad derivadas de contratos de arrendamiento de vivienda.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, ¿qué órgano tiene competencia exclusiva para conocer en primera instancia, con jurisdicción en todo el territorio nacional, de las acciones ejercitadas al amparo del Reglamento (UE) 2017/1001 sobre la marca de la Unión Europea?', 'El art. 87.10 LOPJ atribuye esta competencia a la Sección de lo Mercantil del Tribunal de Instancia de Alicante, que a estos efectos se denomina Tribunal de Marca de la Unión Europea.', 'jus_08_tribunales_instancia', (select id from public.topics where slug = 'jus-08-tribunales-instancia'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 87.10 LOPJ', 'la Sección de lo Mercantil del Tribunal de Instancia de Alicante tendrá competencia exclusiva para conocer en primera instancia con jurisdicción en todo el territorio nacional de aquellas acciones que se ejerciten al amparo de lo establecido en el Reglamento (UE) 2017/1001 del Parlamento y del Consejo, de 14 de junio de 2017, sobre la marca de la Unión Europea', null, '78e21e500be08f7b0df017e68cf1ad9c391a222a9f7196f0f4a03df6cfedbf2a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '78e21e500be08f7b0df017e68cf1ad9c391a222a9f7196f0f4a03df6cfedbf2a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
