with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, las Oficinas de Justicia en los municipios son aquellas unidades que:', 'El art. 439 ter.1 LOPJ define las Oficinas de Justicia en los municipios como unidades no integradas en la Oficina judicial; existe una en cada municipio donde no tenga su sede un Tribunal de Instancia (art. 439 ter.2).', 'jus_08_tribunales_instancia', (select id from public.topics where slug = 'jus-08-tribunales-instancia'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 439 ter.1 LOPJ', '1. Las Oficinas de Justicia en los municipios son aquellas unidades que, sin estar integradas en la estructura de la Oficina judicial, se constituyen en el ámbito de la organización de la Administración de Justicia para la prestación de servicios a la ciudadanía de los respectivos municipios.', null, 'ad7b883ede2d7d0d561817b5f056f7a4fac36f8ac1819e545ec8697115087760', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ad7b883ede2d7d0d561817b5f056f7a4fac36f8ac1819e545ec8697115087760')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sin estar integradas en la estructura de la Oficina judicial, se constituyen en el ámbito de la organización de la Administración de Justicia para la prestación de servicios a la ciudadanía de los respectivos municipios.', true), ('B', 'Se integran en la estructura de la Oficina judicial como servicios comunes procesales de ámbito municipal.', false), ('C', 'Dependen orgánicamente del Ayuntamiento y prestan servicios de registro administrativo municipal.', false), ('D', 'Se integran en el Tribunal de Instancia del partido judicial como Sección de Paz.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 439 quinquies de la Ley Orgánica del Poder Judicial, la Secretaría de las Oficinas de Justicia de municipios de más de 7.000 habitantes será desempeñada por personal:', 'El art. 439 quinquies.1 LOPJ dispone que esas Oficinas (y aquellas en que la carga de trabajo lo justifique) estén servidas por funcionarios de la Administración de Justicia y que su Secretaría corresponda al Cuerpo de Gestión Procesal y Administrativa.', 'jus_08_tribunales_instancia', (select id from public.topics where slug = 'jus-08-tribunales-instancia'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 439 quinquies.1 LOPJ', '1. Las Oficinas de Justicia de municipios de más de 7.000 habitantes y aquellas otras en las que la carga de trabajo lo justifique estarán servidas por funcionarios de los Cuerpos al servicio de la Administración de Justicia […] En todo caso, la Secretaría de estas Oficinas de Justicia será desempeñada por personal del Cuerpo de Gestión Procesal y Administrativa, conforme se determine en la correspondiente relación de puestos de trabajo.', null, '02625d0dc753b6cc9cb8dcbfa31b2dac6149a9fed22893339e14acc8afe6bfca', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '02625d0dc753b6cc9cb8dcbfa31b2dac6149a9fed22893339e14acc8afe6bfca')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Del Cuerpo de Letrados de la Administración de Justicia.', false), ('B', 'Del Cuerpo de Tramitación Procesal y Administrativa.', false), ('C', 'Del Cuerpo de Gestión Procesal y Administrativa.', true), ('D', 'Funcionario del Ayuntamiento, designado por el Alcalde.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, el Ministerio de Justicia o las comunidades autónomas con competencias en materia de Justicia podrán establecer agrupaciones de Oficinas de Justicia de:', 'El art. 439 quinquies.3 LOPJ permite agrupar Oficinas de Justicia de municipios limítrofes del mismo partido judicial; la Oficina del municipio cabecera debe estar dotada con personal de la Administración de Justicia.', 'jus_08_tribunales_instancia', (select id from public.topics where slug = 'jus-08-tribunales-instancia'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 439 quinquies.3 LOPJ', '3. El Ministerio de Justicia o las comunidades autónomas con competencias en materia de Justicia, en sus respectivos ámbitos, podrán establecer agrupaciones de Oficinas de Justicia de municipios limítrofes de un mismo partido judicial para la prestación a la ciudadanía de los servicios a que se refiere el artículo anterior. En tales casos se determinará el municipio cabecera de la agrupación.', null, 'b7fd0e46c7c4ee91387242fa3e2c72c4fafd9e4136ed5317d711e942a715ec1d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b7fd0e46c7c4ee91387242fa3e2c72c4fafd9e4136ed5317d711e942a715ec1d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Municipios de una misma provincia, aunque pertenezcan a distintos partidos judiciales, sin necesidad de municipio cabecera.', false), ('B', 'Municipios limítrofes de un mismo partido judicial, determinándose el municipio cabecera de la agrupación.', true), ('C', 'Municipios de distintas comunidades autónomas, mediante convenio entre ellas.', false), ('D', 'Cualesquiera municipios de menos de 7.000 habitantes, a propuesta de la Sala de Gobierno del Tribunal Superior de Justicia.', false)) as v(label, body, ok)
)
