insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 1/1996, de 10 de enero, de asistencia jurídica gratuita (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-09-carta-derechos', 'Tema 9. La carta de Derechos de los Ciudadanos ante la Justicia. El Derecho a la Justicia Gratuita') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-09-carta-derechos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley 1/1996, de asistencia jurídica gratuita, se reconocerá el derecho a las personas físicas no integradas en ninguna unidad familiar que, careciendo de patrimonio suficiente, cuenten con recursos e ingresos económicos brutos anuales que no superen:', 'El art. 3.1 de la Ley 1/1996 fija el umbral en dos veces el IPREM para personas no integradas en unidad familiar, dos veces y media para unidades familiares de menos de cuatro miembros y el triple para las de cuatro o más o familias numerosas. El quíntuplo es el límite del reconocimiento excepcional (art. 5).', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 3.1 AJG', 'a) Dos veces el indicador público de renta de efectos múltiples vigente en el momento de efectuar la solicitud cuando se trate de personas no integradas en ninguna unidad familiar.', null, '4f321f63aebc812c168814bd77c7315409352e4299da423923547abacbc37d8d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4f321f63aebc812c168814bd77c7315409352e4299da423923547abacbc37d8d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos veces y media el indicador público de renta de efectos múltiples.', false), ('B', 'El triple del indicador público de renta de efectos múltiples.', false), ('C', 'Dos veces el indicador público de renta de efectos múltiples.', true), ('D', 'El quíntuplo del indicador público de renta de efectos múltiples.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley 1/1996, a las víctimas de violencia de género, de terrorismo y de trata de seres humanos se les reconoce el derecho de asistencia jurídica gratuita en los procesos vinculados a su condición de víctimas:', 'El art. 2 h) de la Ley 1/1996 reconoce a estas víctimas el derecho con independencia de sus recursos y de forma inmediata; la condición de víctima se adquiere con la denuncia o querella o al iniciarse el procedimiento penal.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 2 AJG', 'h) Con independencia de la existencia de recursos para litigar, se reconoce el derecho de asistencia jurídica gratuita, que se les prestará de inmediato, a las víctimas de violencia de género, de terrorismo y de trata de seres humanos en aquellos procesos que tengan vinculación, deriven o sean consecuencia de su condición de víctimas', null, '8355a7226aa857220d7ced18064b61b122a0953aed076168ee900cca5045520b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8355a7226aa857220d7ced18064b61b122a0953aed076168ee900cca5045520b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Con independencia de la existencia de recursos para litigar, prestándose de inmediato.', true), ('B', 'Solo si acreditan ingresos inferiores a dos veces el indicador público de renta de efectos múltiples.', false), ('C', 'Solo una vez dictada sentencia condenatoria firme.', false), ('D', 'Solo en el orden penal y siempre que lo acuerde el juez mediante auto.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley 1/1996, ¿qué órgano es responsable de efectuar el reconocimiento del derecho a la asistencia jurídica gratuita en su ámbito territorial?', 'El art. 9 de la Ley 1/1996 crea una Comisión de Asistencia Jurídica Gratuita en cada capital de provincia, en Ceuta y Melilla y en cada isla con uno o más partidos judiciales, como órgano responsable del reconocimiento del derecho.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 9 AJG', 'En cada capital de provincia, en las ciudades de Ceuta y Melilla y en cada isla en que existan uno o más partidos judiciales, se constituirá una Comisión de Asistencia Jurídica Gratuita como órgano responsable, en su correspondiente ámbito territorial, de efectuar el reconocimiento del derecho regulado en la presente Ley.', null, 'f0f933c769ed4a166972c54c52cc7865490dfbbe93aab328b5c586fb6919fee6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f0f933c769ed4a166972c54c52cc7865490dfbbe93aab328b5c586fb6919fee6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El juez o tribunal que conozca del proceso.', false), ('B', 'La Comisión de Asistencia Jurídica Gratuita.', true), ('C', 'El Letrado de la Administración de Justicia del órgano judicial.', false), ('D', 'El Decano del Colegio de Abogados.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 1/1996, el reconocimiento del derecho a la asistencia jurídica gratuita se instará por los solicitantes ante:', 'El art. 12.2 de la Ley 1/1996 dispone que la solicitud se presenta ante el Colegio de Abogados del lugar del órgano judicial competente o ante el juzgado del domicilio, que dará traslado al Colegio territorialmente competente.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 12.2 AJG', 'se instará por los solicitantes ante el Colegio de Abogados del lugar en que se halle el juzgado o tribunal que haya de conocer del proceso principal para el que aquél se solicita, o ante el juzgado de su domicilio.', null, '45008f818c61b0346b89caefdd64ee749e1bf56784516636f873bb0b386a91b1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '45008f818c61b0346b89caefdd64ee749e1bf56784516636f873bb0b386a91b1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Colegio de Abogados del lugar en que se halle el juzgado o tribunal que haya de conocer del proceso principal, o ante el juzgado de su domicilio.', true), ('B', 'La Comisión de Asistencia Jurídica Gratuita del domicilio del solicitante, exclusivamente.', false), ('C', 'El Ministerio de Justicia o la consejería competente de la Comunidad Autónoma.', false), ('D', 'El Colegio de Procuradores del domicilio del solicitante.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley 1/1996, si el Colegio de Abogados constata deficiencias en la solicitud de asistencia jurídica gratuita, requerirá al interesado para que la complete en el plazo de:', 'El art. 14 de la Ley 1/1996 concede diez días hábiles para subsanar; si no se completa la documentación, el Colegio de Abogados archiva la petición.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 14 AJG', 'requiriéndole para que la complete en el plazo de diez días hábiles. Transcurrido este plazo sin que se haya aportado la documentación requerida, el Colegio de Abogados archivará la petición.', null, '2b543d415f20b36c4248276dfb9bba866cd683e908b676c32d86b1a14d93eb66', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2b543d415f20b36c4248276dfb9bba866cd683e908b676c32d86b1a14d93eb66')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinco días hábiles; transcurrido sin aportar la documentación, se entenderá denegado el derecho.', false), ('B', 'Quince días hábiles; transcurrido sin aportar la documentación, el Colegio trasladará la solicitud a la Comisión.', false), ('C', 'Diez días hábiles; transcurrido sin aportar la documentación, el Colegio archivará la petición.', true), ('D', 'Un mes; transcurrido sin aportar la documentación, el Colegio archivará la petición.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 15 de la Ley 1/1996, acreditado que el peticionario está incluido en el ámbito del artículo 2, el Colegio de Abogados procederá a la designación provisional de abogado en el plazo máximo de:', 'El art. 15 de la Ley 1/1996 fija quince días para la designación provisional de abogado (desde la recepción de la solicitud o la subsanación) y tres días para la del procurador.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 15 AJG', 'el Colegio de Abogados, subsanados los defectos advertidos, procederá en el plazo máximo de quince días, contado a partir de la recepción de la solicitud por dicho Colegio o de la subsanación de los defectos, a la designación provisional de abogado, comunicándolo inmediatamente al Colegio de Procuradores a fin de que, en caso de ser preceptivo, en el plazo máximo de tres días, se designe procurador que asuma la representación.', null, 'bfd9344c05387a4aca95a8d2db0be4a5bcdf200d4e596259770f7d1ad57e4a7d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bfd9344c05387a4aca95a8d2db0be4a5bcdf200d4e596259770f7d1ad57e4a7d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Diez días, comunicándolo al Colegio de Procuradores para que, si es preceptivo, designe procurador en el plazo máximo de cinco días.', false), ('B', 'Tres días, comunicándolo al Colegio de Procuradores para que, si es preceptivo, designe procurador en el plazo máximo de quince días.', false), ('C', 'Treinta días, comunicándolo a la Comisión de Asistencia Jurídica Gratuita para que designe procurador.', false), ('D', 'Quince días, comunicándolo al Colegio de Procuradores para que, si es preceptivo, designe procurador en el plazo máximo de tres días.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley 1/1996, la solicitud de reconocimiento del derecho a la asistencia jurídica gratuita:', 'El art. 16.1 de la Ley 1/1996 establece que la solicitud no suspende el proceso, si bien el secretario judicial (hoy Letrado de la Administración de Justicia) o el órgano administrativo pueden decretar la suspensión para evitar preclusión de trámites o indefensión.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 16.1 AJG', '1. La solicitud de reconocimiento del derecho a la asistencia jurídica gratuita no suspenderá el curso del proceso o expediente administrativo. No obstante, a fin de evitar que el transcurso de los plazos pueda provocar la preclusión de un trámite o la indefensión de cualquiera de las partes, el secretario judicial o el órgano administrativo, de oficio o a petición de éstas, podrá decretar la suspensión', null, '68ab3945cbd85b622cef0f9faa319043f0963ad489d72ad05028c5ea23bf0ab5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '68ab3945cbd85b622cef0f9faa319043f0963ad489d72ad05028c5ea23bf0ab5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Suspenderá automáticamente el curso del proceso hasta que la Comisión resuelva.', false), ('B', 'Suspenderá el curso del proceso solo en el orden penal.', false), ('C', 'No suspenderá el curso del proceso, aunque podrá decretarse la suspensión para evitar la preclusión de un trámite o la indefensión.', true), ('D', 'No suspenderá el curso del proceso en ningún caso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 1/1996, ¿en qué plazo debe la Comisión de Asistencia Jurídica Gratuita dictar resolución reconociendo o denegando el derecho, y qué ocurre si no resuelve expresamente?', 'El art. 17.2 de la Ley 1/1996 da a la Comisión treinta días desde la recepción del expediente; transcurrido sin resolución expresa, quedan ratificadas las decisiones previas de los Colegios, sin perjuicio de la obligación de resolver.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 17.2 AJG', '2. La Comisión, una vez efectuadas las comprobaciones anteriores, dictará resolución, en el plazo máximo de treinta días, contados a partir de la recepción del expediente por la Comisión, reconociendo o denegando el derecho a la asistencia jurídica gratuita y determinando cuáles de las prestaciones son de aplicación a la solicitud. Transcurrido dicho plazo sin que la Comisión haya resuelto expresamente la solicitud, quedarán ratificadas las decisiones que previamente hubieran podido adoptar los Colegios de Abogados o de Procuradores', null, 'bd2b46ca9a28b7064df3c8a81e490b8d56872091bbd9e56a8bb01d70348ad9d9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bd2b46ca9a28b7064df3c8a81e490b8d56872091bbd9e56a8bb01d70348ad9d9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quince días desde la recepción del expediente; si no resuelve, se entiende denegado el derecho.', false), ('B', 'Treinta días desde la recepción del expediente; si no resuelve, quedan ratificadas las decisiones que previamente hubieran podido adoptar los Colegios de Abogados o de Procuradores.', true), ('C', 'Un mes desde la presentación de la solicitud; si no resuelve, decide el juez del proceso mediante auto.', false), ('D', 'Treinta días desde la recepción del expediente; si no resuelve, quedan sin efecto las designaciones provisionales.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley 1/1996, la impugnación de las resoluciones que de modo definitivo reconozcan, revoquen o denieguen el derecho a la asistencia jurídica gratuita:', 'El art. 20.1 de la Ley 1/1996 regula una impugnación sin abogado preceptivo, en diez días, ante el secretario de la Comisión, que la remite al juzgado o tribunal competente; este resuelve por auto contra el que no cabe recurso (art. 20.3).', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 20.1 AJG', 'Tal impugnación, para la que no será preceptiva la intervención de abogado, habrá de realizarse por escrito y de forma motivada, en el plazo de diez días desde la notificación de la resolución o desde que haya sido conocida por cualquiera de los legitimados para interponerla, ante el secretario de la Comisión de Asistencia Jurídica Gratuita.', null, '943722b196b1b855083c675b3c1bb656aeea020aacb6fb03a30f0b03870ad797', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '943722b196b1b855083c675b3c1bb656aeea020aacb6fb03a30f0b03870ad797')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se realiza mediante recurso de alzada ante el Ministerio de Justicia en el plazo de un mes.', false), ('B', 'Se realiza mediante recurso contencioso-administrativo en el plazo de dos meses, con abogado y procurador.', false), ('C', 'Se realiza por escrito motivado, con intervención preceptiva de abogado, en el plazo de cinco días ante el juez que conozca del proceso.', false), ('D', 'Se realiza por escrito motivado, sin que sea preceptiva la intervención de abogado, en el plazo de diez días ante el secretario de la Comisión de Asistencia Jurídica Gratuita.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
