with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 36 de la Ley 1/1996, si es condenado en costas quien obtuvo el reconocimiento del derecho a la asistencia jurídica gratuita, quedará obligado a pagar las causadas en su defensa y las de la parte contraria si viniere a mejor fortuna dentro de:', 'El art. 36.2 de la Ley 1/1996 fija tres años desde la terminación del proceso; se presume la mejor fortuna si los ingresos superan el doble del módulo del art. 3 o han cambiado sustancialmente las circunstancias.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 36.2 AJG', 'éste quedará obligado a pagar las causadas en su defensa y las de la parte contraria, si dentro de los tres años siguientes a la terminación del proceso viniere a mejor fortuna', null, 'a83ada4a523eaabf31ff6967e7151e390831e4d05f97d2b16b9136e287e65ace', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a83ada4a523eaabf31ff6967e7151e390831e4d05f97d2b16b9136e287e65ace')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los tres años siguientes a la terminación del proceso.', true), ('B', 'El año siguiente a la terminación del proceso.', false), ('C', 'Los cinco años siguientes a la terminación del proceso.', false), ('D', 'Los dos años siguientes a la firmeza de la sentencia.', false)) as v(label, body, ok)
)
