with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 119 de la Constitución Española, la justicia será gratuita cuando así lo disponga la ley y, en todo caso, respecto de:', 'El art. 119 CE garantiza en todo caso la justicia gratuita a quienes acrediten insuficiencia de recursos para litigar; la Ley 1/1996 desarrolla este derecho.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 119 CE', 'La justicia será gratuita cuando así lo disponga la ley y, en todo caso, respecto de quienes acrediten insuficiencia de recursos para litigar.', null, 'a894419f87455b1d8c039a3209e3028f9d38079ebb87cfd7561ab9a2dd3df02a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a894419f87455b1d8c039a3209e3028f9d38079ebb87cfd7561ab9a2dd3df02a')
