with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 234 de la Ley Orgánica del Poder Judicial, los Letrados de la Administración de Justicia y funcionarios competentes de la oficina judicial facilitarán a los interesados cuanta información soliciten sobre el estado de las actuaciones procesales:', 'El art. 234.1 LOPJ reconoce el derecho de los interesados a ser informados del estado de las actuaciones y a examinarlas, con el único límite de las actuaciones declaradas secretas o reservadas.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 234.1 LOPJ', '1. Los Letrados de la Administración de Justicia y funcionarios competentes de la oficina judicial y de la oficina fiscal facilitarán a los interesados cuanta información soliciten sobre el estado de las actuaciones procesales, que podrán examinar y conocer, salvo que sean o hubieren sido declaradas secretas o reservadas conforme a la ley.', null, 'c5aff4eedebcbe9ee1aaa768230f78735988cddb9d9d97ae2af0d4d9986c8f3b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c5aff4eedebcbe9ee1aaa768230f78735988cddb9d9d97ae2af0d4d9986c8f3b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Salvo que sean o hubieren sido declaradas secretas o reservadas conforme a la ley.', true), ('B', 'Únicamente si actúan asistidos de abogado.', false), ('C', 'Solo después de dictada sentencia firme.', false), ('D', 'Previa autorización escrita del juez o magistrado en cada caso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley Orgánica del Poder Judicial, la relación de señalamientos de cada órgano judicial deberá publicarse en un lugar visible al público:', 'El art. 232.2 LOPJ obliga a publicar la relación de señalamientos el primer día hábil de cada semana, con fecha y hora, tipo de actuación y número de procedimiento; los Letrados de la Administración de Justicia velan por su cumplimiento.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 232.2 LOPJ', 'Los Letrados de la Administración de Justicia velarán por que los funcionarios competentes de la Oficina judicial publiquen en un lugar visible al público, el primer día hábil de cada semana, la relación de señalamientos correspondientes a su respectivo órgano judicial, con indicación de la fecha y hora de su celebración, tipo de actuación y número de procedimiento.', null, '4ab90ea0e888485c9b7c415bf57aaaf8a3920eabbb99d9363eb02c52ed2d94a4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4ab90ea0e888485c9b7c415bf57aaaf8a3920eabbb99d9363eb02c52ed2d94a4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El último día hábil de cada semana.', false), ('B', 'El primer día hábil de cada mes.', false), ('C', 'Con al menos diez días de antelación a cada vista.', false), ('D', 'El primer día hábil de cada semana.', true)) as v(label, body, ok)
)
