)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley Orgánica del Poder Judicial, en los procedimientos laborales y de Seguridad Social la representación técnica podrá ser ostentada por:', 'El art. 545.2 LOPJ permite que en los procedimientos laborales y de Seguridad Social la representación técnica la ostente un Graduado Social, sujeto a las obligaciones propias de su función.', 'jus_09_carta_derechos', (select id from public.topics where slug = 'jus-09-carta-derechos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 545.2 LOPJ', '2. En los procedimientos laborales y de Seguridad Social la representación técnica podrá ser ostentada por un Graduado Social', null, '53b0897cad710c2277942be981920d68a3dace29ada2305ed84a7855ee008d53', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '53b0897cad710c2277942be981920d68a3dace29ada2305ed84a7855ee008d53')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
