insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-10-oficina-judicial' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 273 de la Ley de Enjuiciamiento Civil, ¿cuál de los siguientes sujetos está obligado, en todo caso, a intervenir a través de medios electrónicos con la Administración de Justicia?', 'El art. 273.3 LEC obliga, entre otros, a las personas jurídicas, entidades sin personalidad, profesionales de colegiación obligatoria, notarios y registradores. Las personas físicas sin procurador pueden elegir el medio (art. 273.2).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 273.3 LEC', '3. En todo caso, estarán obligados a intervenir a través de medios electrónicos con la Administración de Justicia, al menos, los siguientes sujetos: a) Las personas jurídicas.', null, '4970fc532d510d530cb78b8e69b325ed5548a3476da56c35925c65fc4585f7fd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4970fc532d510d530cb78b8e69b325ed5548a3476da56c35925c65fc4585f7fd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las personas jurídicas.', true), ('B', 'Las personas físicas que no estén representadas por procurador.', false), ('C', 'Los testigos citados a juicio.', false), ('D', 'Los menores de edad emancipados.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de Enjuiciamiento Civil, si un escrito se presenta por medios telemáticos en día u hora inhábil a efectos procesales:', 'El art. 135.1 LEC permite presentar escritos electrónicos todos los días del año durante las veinticuatro horas; el recibo indica número de registro, fecha y hora, y si es inhábil se entiende presentado el primer día y hora hábil siguiente.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 135.1 LEC', 'Se podrán presentar escritos y documentos en formato electrónico todos los días del año durante las veinticuatro horas. […] En caso de que la presentación tenga lugar en día u hora inhábil a efectos procesales conforme a la ley, se entenderá efectuada el primer día y hora hábil siguiente.', null, '75814403bd74df64b71cf05846b57d2b1b39446d9b28ae0f22f22a953b0958c4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '75814403bd74df64b71cf05846b57d2b1b39446d9b28ae0f22f22a953b0958c4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se tendrá por no presentado y deberá presentarse de nuevo en día hábil.', false), ('B', 'Se entenderá presentado el día anterior hábil.', false), ('C', 'Se entenderá efectuada la presentación el primer día y hora hábil siguiente.', true), ('D', 'Solo será válido si se ratifica en papel ante la oficina judicial.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 273 de la Ley de Enjuiciamiento Civil, el escrito principal presentado por vía telemática o electrónica deberá incorporar:', 'El art. 273.4 LEC exige que el escrito principal incorpore firma electrónica basada en certificado cualificado y que los escritos indiquen tipo, número y año del expediente con un índice electrónico.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 273.4 LEC', 'El escrito principal deberá incorporar firma electrónica basada en un certificado cualificado y se adaptará a lo establecido en la normativa reguladora del uso de las tecnologías en la Administración de Justicia.', null, '24d6e11813b1e6f517c3c1fc1229aa03903ea01d2b417d3da21407153d111ddb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '24d6e11813b1e6f517c3c1fc1229aa03903ea01d2b417d3da21407153d111ddb')
