)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 129 bis de la Ley de Enjuiciamiento Civil, constituido el Juzgado o Tribunal en su sede, los actos procesales se realizarán preferentemente mediante presencia telemática, siempre que la oficina judicial disponga de los medios técnicos necesarios, y la intervención telemática se practicará siempre a través de:', 'El art. 129 bis.1 LEC establece la preferencia por la presencia telemática y exige que se practique a través de punto de acceso seguro; las declaraciones de partes, testigos o peritos exigen, como regla, presencia física (art. 129 bis.2).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 129 bis.1 LEC', 'se realizarán preferentemente mediante presencia telemática, siempre que las oficinas judiciales tengan a su disposición los medios técnicos necesarios para ello. La intervención mediante presencia telemática se practicará siempre a través de punto de acceso seguro', null, '16ddc7db3dd0440a29ce6b549f513857921037e28d9054cf97aa1e7e07a6d53a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '16ddc7db3dd0440a29ce6b549f513857921037e28d9054cf97aa1e7e07a6d53a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Punto de acceso seguro.', true), ('B', 'El domicilio del interviniente, previa identificación con DNI.', false), ('C', 'Cualquier aplicación de videollamada elegida por la parte.', false), ('D', 'La Oficina de Justicia en el municipio del Ayuntamiento del interviniente, en todo caso.', false)) as v(label, body, ok)
)
