insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-10-oficina-judicial', 'Tema 10. La modernización de la oficina judicial y las nuevas tecnologías') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-10-oficina-judicial' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 435 de la Ley Orgánica del Poder Judicial, la Oficina judicial es:', 'El art. 435.1 LOPJ define la Oficina judicial como organización instrumental de soporte y apoyo a la actividad jurisdiccional. Las unidades administrativas, en cambio, no están integradas en ella (art. 439).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 435.1 LOPJ', '1. La Oficina judicial es la organización de carácter instrumental que sirve de soporte y apoyo a la actividad jurisdiccional de jueces y tribunales.', null, '89720988a9de286d4c7af7a84d3c12b8a1c80fa8ee1f9d9c3addd1a6c32d72ef', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '89720988a9de286d4c7af7a84d3c12b8a1c80fa8ee1f9d9c3addd1a6c32d72ef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El órgano de gobierno de cada Tribunal de Instancia.', false), ('B', 'La organización de carácter instrumental que sirve de soporte y apoyo a la actividad jurisdiccional de jueces y tribunales.', true), ('C', 'La unidad administrativa que gestiona los recursos humanos y materiales de la Administración de Justicia.', false), ('D', 'El conjunto de jueces y magistrados destinados en un mismo partido judicial.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley Orgánica del Poder Judicial, la estructura básica de la Oficina judicial, homogénea en todo el territorio nacional, estará basada en los principios de:', 'El art. 435.2 LOPJ basa la estructura de la Oficina judicial en jerarquía, división de funciones y coordinación; su funcionamiento se rige por criterios de agilidad, eficacia, eficiencia y racionalización del trabajo, entre otros (art. 435.3).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 435.2 LOPJ', '2. La estructura básica de la Oficina judicial, que será homogénea en todo el territorio nacional como consecuencia del carácter único del Poder al que sirve, estará basada en los principios de jerarquía, división de funciones y coordinación.', null, '101b031a177bfdfae0f29f5d0f05f2a0dd137e71e3ee5328cb9c70ee26dd6198', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '101b031a177bfdfae0f29f5d0f05f2a0dd137e71e3ee5328cb9c70ee26dd6198')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Unidad de actuación y dependencia jerárquica.', false), ('B', 'Descentralización, desconcentración y eficacia.', false), ('C', 'Independencia, inamovilidad y responsabilidad.', false), ('D', 'Jerarquía, división de funciones y coordinación.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, la dirección de cada servicio común de la Oficina judicial corresponderá a:', 'El art. 436.6 LOPJ atribuye la dirección de cada servicio común a un letrado de la Administración de Justicia, del que dependen funcionalmente los demás letrados y el personal del servicio.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 436.6 LOPJ', '6. La dirección de cada servicio común corresponderá a un letrado o una letrada de la Administración de Justicia', null, '198daea9b1999512ffab4defd3fef5c311d19d51529e611c3939c50fe51857ae', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '198daea9b1999512ffab4defd3fef5c311d19d51529e611c3939c50fe51857ae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El juez o magistrado que presida el Tribunal de Instancia.', false), ('B', 'Un funcionario del Cuerpo de Gestión Procesal y Administrativa.', false), ('C', 'Un letrado o una letrada de la Administración de Justicia.', true), ('D', 'El Secretario de Gobierno del Tribunal Superior de Justicia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley Orgánica del Poder Judicial, se entiende por servicio común de tramitación aquella unidad de la Oficina judicial que:', 'El art. 437.1 LOPJ define el servicio común de tramitación por la ordenación del procedimiento; cada Tribunal de Instancia, Audiencia Provincial, TSJ, la Audiencia Nacional, el Tribunal Supremo y el Tribunal Central de Instancia son asistidos por uno (art. 437.2).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 437.1 LOPJ', '1. A los efectos de esta ley orgánica se entiende por servicio común de tramitación aquella unidad de la Oficina judicial que realiza todas las funciones requeridas para la ordenación del procedimiento.', null, 'ae90f4cfee5b5997b601da5ac42af02c8787da78aabedd830c3b8d2367d9ae7b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ae90f4cfee5b5997b601da5ac42af02c8787da78aabedd830c3b8d2367d9ae7b')
  returning id
