)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, las unidades administrativas que se constituyen en el ámbito de la organización de la Administración de Justicia:', 'El art. 439.1 LOPJ define la unidad administrativa como no integrada en la Oficina judicial y excluye de sus servicios las funciones procesales propias del personal de los Cuerpos de la Administración de Justicia.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 439.1 LOPJ', '1. A los efectos de esta ley, se entiende por unidad administrativa aquélla que, sin estar integrada en la Oficina judicial, se constituye en el ámbito de la organización de la Administración de Justicia para la prestación de servicios que se consideren necesarios o convenientes para el funcionamiento del servicio público de Justicia. Estos servicios no comprenderán la realización de funciones de carácter procesal que correspondan al personal funcionario de los Cuerpos de la Administración de Justicia.', null, 'ed10d374bd1c908c98801cf89f85192a459cfa1dc75d84bf85cdbb9db69460e2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ed10d374bd1c908c98801cf89f85192a459cfa1dc75d84bf85cdbb9db69460e2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Están integradas en la Oficina judicial y realizan funciones de ordenación del procedimiento.', false), ('B', 'Están integradas en la Oficina judicial bajo la dirección de un juez.', false), ('C', 'No están integradas en la Oficina judicial y sus servicios no comprenden funciones de carácter procesal que correspondan a los Cuerpos de la Administración de Justicia.', true), ('D', 'No están integradas en la Oficina judicial, pero asumen la práctica de los actos de comunicación procesal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
