  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, para el tratamiento de los datos personales en el ejercicio de la actividad jurisdiccional:', 'El art. 236 ter.3 LOPJ exime del consentimiento del interesado el tratamiento de datos en el ejercicio de la actividad jurisdiccional, sin perjuicio de las normas procesales sobre validez de la prueba.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 236 ter.3 LOPJ', '3. No será necesario el consentimiento del interesado para que se proceda al tratamiento de los datos personales en el ejercicio de la actividad jurisdiccional, ya sean éstos facilitados por las partes o recabados a solicitud de los órganos competentes, sin perjuicio de lo dispuesto en las normas procesales para la validez de la prueba.', null, 'fee5b21541918f515933c85289e5077e3cb0b8dc66373e6f27b567a4a4504cc2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fee5b21541918f515933c85289e5077e3cb0b8dc66373e6f27b567a4a4504cc2')
  returning id
