insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-10-oficina-judicial' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto-ley 6/2023, cuando un documento no pueda adjuntarse al envío electrónico de un escrito, el original deberá presentarse ante el órgano judicial:', 'El art. 43.4 del RDL 6/2023 exige presentar el original el día hábil siguiente al envío electrónico, haciendo referencia a los datos identificativos de ese envío; de lo contrario, el documento se tiene por no presentado a todos los efectos.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 43.4 RDL 6/2023', 'presentando el original ante el órgano judicial en el día hábil siguiente a aquel en que se hubiera efectuado el envío electrónico del escrito, que deberá acompañar en todo caso. Si no se presentara en este plazo, el documento se tendrá por no presentado a todos los efectos.', null, 'f01ce6af9f19f4522a0a85c5459ab224563fd2203bdfb0b30e2c3a9eec95b5d3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f01ce6af9f19f4522a0a85c5459ab224563fd2203bdfb0b30e2c3a9eec95b5d3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el día hábil siguiente a aquel en que se hubiera efectuado el envío electrónico del escrito; si no se presenta en ese plazo, se tendrá por no presentado.', true), ('B', 'En los tres días hábiles siguientes al envío; si no se presenta, se requerirá su subsanación en diez días.', false), ('C', 'En el mismo día del envío electrónico, antes de las quince horas.', false), ('D', 'En cualquier momento antes de la celebración de la vista.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el Real Decreto-ley 6/2023, el expediente judicial electrónico es:', 'El art. 47.1 del RDL 6/2023 define el expediente judicial electrónico como conjunto ordenado de datos, documentos, trámites, actuaciones y grabaciones de un procedimiento, cualquiera que sea su formato.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 47.1 RDL 6/2023', '1. El expediente judicial electrónico es el conjunto ordenado de datos, documentos, trámites y actuaciones electrónicas, así como de grabaciones audiovisuales, correspondientes a un procedimiento judicial, cualquiera que sea el tipo de información que contengan y el formato en el que se hayan generado.', null, 'c63d2c49dc9f4356173efc78dd007f1ea8ad8f2f8585082fc563fd6659f38807', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c63d2c49dc9f4356173efc78dd007f1ea8ad8f2f8585082fc563fd6659f38807')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La copia en papel de las actuaciones judiciales firmada por el letrado de la Administración de Justicia.', false), ('B', 'El conjunto ordenado de datos, documentos, trámites y actuaciones electrónicas, así como de grabaciones audiovisuales, correspondientes a un procedimiento judicial.', true), ('C', 'El registro de los escritos presentados por los profesionales a través de la sede judicial electrónica.', false), ('D', 'El índice de las resoluciones judiciales dictadas en un procedimiento.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto-ley 6/2023, a cada expediente judicial electrónico se asignará un número de identificación general que será:', 'El art. 47.2 del RDL 6/2023 asigna un número de identificación general único e inalterable que permite identificar el expediente por cualquier tribunal u oficina. Además, todo expediente tiene un índice electrónico firmado (art. 47.3).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 47.2 RDL 6/2023', '2. Se asignará un número de identificación general a cada expediente judicial electrónico, que será único e inalterable a lo largo de todo el proceso', null, '2c3c84efe026168e6d5d3b4b1bf5daf8d77d5253a70f137aa83c753a219b9513', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2c3c84efe026168e6d5d3b4b1bf5daf8d77d5253a70f137aa83c753a219b9513')
  returning id
), o as (
