)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al Real Decreto-ley 6/2023, el cotejo de la autenticidad e integridad de los documentos con Código Seguro de Verificación se realizará:', 'El art. 26.1 del RDL 6/2023 dispone que el cotejo de documentos con CSV se hace en la sede judicial electrónica del órgano emisor; el documento debe indicar la dirección electrónica de cotejo (art. 26.2).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 26.1 RDL 6/2023', 'El cotejo de los documentos con Código Seguro de Verificación se realizará en la sede judicial electrónica correspondiente al órgano que emitió el documento.', null, '49d126edd3e0ba795f242bf82256a4f3342a4703f9e75b5ecd9f79c05972ff34', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '49d126edd3e0ba795f242bf82256a4f3342a4703f9e75b5ecd9f79c05972ff34')
  returning id
