)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto-ley 6/2023, los intervinientes en una videoconferencia deberán observar:', 'El art. 60.6 del RDL 6/2023 equipara las exigencias de decoro, vestimenta y respeto de la videoconferencia a las de las actuaciones presenciales. Los intervinientes deben identificarse al inicio del acto (art. 60.1).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 60.6 RDL 6/2023', '6. Los intervinientes en una videoconferencia deberán observar las mismas normas de decoro, vestimenta y respeto exigidas en las actuaciones realizadas presencialmente en las salas de vistas y en las sedes de los tribunales, oficinas judiciales y oficinas fiscales.', null, '67830b67e5b5b27849b986b2f5b6796fbf85c91d542ad0ce998b67bc9feba0b2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '67830b67e5b5b27849b986b2f5b6796fbf85c91d542ad0ce998b67bc9feba0b2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Normas de decoro propias y menos exigentes que las de las actuaciones presenciales.', false), ('B', 'Únicamente las normas de vestimenta que fije cada Colegio profesional.', false), ('C', 'Las normas que determine libremente cada interviniente desde su domicilio.', false), ('D', 'Las mismas normas de decoro, vestimenta y respeto exigidas en las actuaciones realizadas presencialmente.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
