  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Determina en todo caso la nulidad de pleno derecho de la actuación.', false), ('B', 'Obliga a repetir la actuación de forma presencial en el plazo de diez días.', false), ('C', 'No priva por sí solo de efectos procesales y jurídicos a la actuación, ni supone su ineficacia o nulidad.', true), ('D', 'Supone la anulabilidad de la actuación, que deberá declararse de oficio.', false)) as v(label, body, ok)
