  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un número equivalente al veinticinco por ciento de las ofrecidas al turno libre, con al menos dos años de servicios efectivos en el Cuerpo de Gestión.', false), ('B', 'Un número equivalente al cincuenta por ciento de las ofrecidas al turno libre, con al menos cinco años de servicios efectivos en el Cuerpo de Gestión.', false), ('C', 'Un número equivalente al quince por ciento de las ofrecidas al turno libre, con al menos tres años de servicios efectivos en el Cuerpo de Gestión.', false), ('D', 'Un número equivalente al cincuenta por ciento de las ofrecidas al turno libre, con al menos dos años de servicios efectivos en el Cuerpo de Gestión.', true)) as v(label, body, ok)
)
