  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 450 de la Ley Orgánica del Poder Judicial, los puestos de Letrado de la Administración de Justicia en el Tribunal Supremo se cubren por libre designación entre candidatos de la primera o segunda categoría con una antigüedad mínima de:', 'El art. 450.1 LOPJ exige para el Tribunal Supremo veinte años en la primera o segunda categoría (o entre ambas) y quince años de servicio en el orden jurisdiccional correspondiente.', 'jus_11_letrado', (select id from public.topics where slug = 'jus-11-letrado'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 450.1 LOPJ', 'Los puestos de trabajo de Letrado de la Administración de Justicia en el Tribunal Supremo se cubrirán por el sistema de libre designación entre aquellos candidatos que pertenezcan a la primera o segunda categoría, con una antigüedad de al menos veinte años en una de ellas o entre ambas y quince años de servicio en el orden jurisdiccional correspondiente.', null, '05aabd2c11b607f412786385870293aa7a3b520365cf80b47d1a8eaee87942d5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '05aabd2c11b607f412786385870293aa7a3b520365cf80b47d1a8eaee87942d5')
