  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 464 de la Ley Orgánica del Poder Judicial, el Secretario de Gobierno se elige entre miembros del Cuerpo de Letrados de la Administración de Justicia que, como mínimo:', 'El art. 464.1 LOPJ exige al Secretario de Gobierno al menos diez años de servicio en puestos de segunda categoría; además ejerce como Secretario de la Sala de Gobierno de su tribunal.', 'jus_11_letrado', (select id from public.topics where slug = 'jus-11-letrado'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 464.1 LOPJ', 'Habrá un Secretario de Gobierno en el Tribunal Supremo, en la Audiencia Nacional y en cada Tribunal Superior de Justicia, así como en las ciudades de Ceuta y Melilla, elegido entre miembros integrantes del Cuerpo de Letrados de la Administración de Justicia que, como mínimo, hayan prestado servicio durante diez años en puestos de segunda categoría', null, '453c7b1ed73689b80abe8bb204cc80dc0cafb78fa4d9b68e0d75be50a40cf846', false
