with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 471 de la Ley Orgánica del Poder Judicial, las competencias sobre el estatuto y régimen jurídico del personal de los Cuerpos al servicio de la Administración de Justicia (selección, provisión, situaciones, jornada, régimen disciplinario, etc.) corresponden:', 'El art. 471.1 LOPJ atribuye esas competencias al Ministerio de Justicia o, en su caso, a las comunidades autónomas con competencias asumidas.', 'jus_12_cuerpos_funcionarios', (select id from public.topics where slug = 'jus-12-cuerpos-funcionarios'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 471.1 LOPJ', 'Las competencias respecto de todo el personal al servicio de la Administración de Justicia al que se refiere el artículo anterior, corresponden en los términos establecidos en esta ley, al Ministerio de Justicia o, en su caso, a las comunidades autónomas con competencias asumidas, en todas las materias relativas a su estatuto y régimen jurídico, comprendidas la selección, formación inicial y continuada, provisión de destinos, ascensos, situaciones administrativas, jornada laboral, horario de trabajo y régimen disciplinario.', null, 'aec607ea82a170eb78a310732ce856ac8831da5e0a2f629b1374c4587d82a06d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'aec607ea82a170eb78a310732ce856ac8831da5e0a2f629b1374c4587d82a06d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Consejo General del Poder Judicial.', false), ('B', 'A las Salas de Gobierno de los Tribunales Superiores de Justicia.', false), ('C', 'A los Secretarios de Gobierno de cada Tribunal Superior de Justicia.', false), ('D', 'Al Ministerio de Justicia o, en su caso, a las comunidades autónomas con competencias asumidas.', true)) as v(label, body, ok)
)
