with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 472 de la Ley Orgánica del Poder Judicial, podrán nombrarse funcionarios interinos que desarrollen las funciones propias de los Cuerpos al servicio de la Administración de Justicia:', 'El art. 472.2 LOPJ permite nombrar interinos por razones de urgencia o necesidad, en tanto no sea posible el desempeño por funcionarios de carrera o permanezcan las razones del nombramiento.', 'jus_12_cuerpos_funcionarios', (select id from public.topics where slug = 'jus-12-cuerpos-funcionarios'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 472.2 LOPJ', 'Por razones de urgencia o necesidad, podrán nombrarse funcionarios interinos, que desarrollarán las funciones propias de dichos cuerpos, en tanto no sea posible su desempeño por funcionarios de carrera o permanezcan las razones que motivaron su nombramiento.', null, 'e43ef2539c255179f13d39e481e01aac6052a0f1fe68d5861efa8a15005a6660', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e43ef2539c255179f13d39e481e01aac6052a0f1fe68d5861efa8a15005a6660')
  returning id
