with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario del Cuerpo de Auxilio Judicial practica una citación en el domicilio de un testigo. Según el artículo 478 de la Ley Orgánica del Poder Judicial, en la práctica de ese acto de comunicación el funcionario:', 'El art. 478.a) LOPJ atribuye al Cuerpo de Auxilio Judicial la práctica de notificaciones, citaciones, emplazamientos y requerimientos, con capacidad de certificación y las credenciales necesarias. La fe pública judicial es exclusiva e indelegable del LAJ (arts. 452.1 y 453.1).', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 478.a LOPJ', 'a) La práctica de los actos de comunicación que consistan en notificaciones, citaciones, emplazamientos y requerimientos, en la forma prevista en las leyes procesales, a cuyo efecto ostentará capacidad de certificación y dispondrá de las credenciales necesarias.', null, 'dc68a58b48c5d139fc12942d7441c16ae95043d6d7792c8cdb67112036133cb4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dc68a58b48c5d139fc12942d7441c16ae95043d6d7792c8cdb67112036133cb4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ejerce la fe pública judicial por delegación del Letrado de la Administración de Justicia.', false), ('B', 'Ostenta capacidad de certificación y dispone de las credenciales necesarias.', true), ('C', 'Debe ir acompañado del Letrado de la Administración de Justicia.', false), ('D', 'Necesita la intervención de dos testigos que firmen la diligencia.', false)) as v(label, body, ok)
)
