  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 482 de la Ley Orgánica del Poder Judicial, en las ofertas de empleo público de los Cuerpos al servicio de la Administración de Justicia se reservará para personas con discapacidad un cupo de las vacantes:', 'El art. 482.5 LOPJ reserva un cupo no inferior al 7 % de las vacantes para personas con discapacidad.', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 482.5 LOPJ', 'En las ofertas de empleo público se reservará un cupo no inferior al siete por ciento de las vacantes para ser cubiertas entre personas con discapacidad', null, '2bf1770c287c1310fd162df9252e14a5f7c0aa9ea8a8190548ecbf3b39aee910', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2bf1770c287c1310fd162df9252e14a5f7c0aa9ea8a8190548ecbf3b39aee910')
  returning id
), o as (
