)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 486 de la Ley Orgánica del Poder Judicial, la Presidencia de la Comisión de Selección de Personal corresponde a:', 'El art. 486.1 LOPJ compone la Comisión con cuatro vocales del Ministerio de Justicia (uno de ellos preside con voto dirimente) y cuatro representantes de las comunidades autónomas (uno de ellos ocupa la Vicepresidencia).', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 486.1 LOPJ', 'Cuatro vocales representantes del Ministerio de Justicia, uno de los cuales asumirá la Presidencia de la Comisión y tendrá voto dirimente en caso de empate en la adopción de acuerdos.', null, 'e9e165547faf1d101104878f3be0dbc945fb6e22622f1420bfbe10ae79aeb6eb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e9e165547faf1d101104878f3be0dbc945fb6e22622f1420bfbe10ae79aeb6eb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
