with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 490 de la Ley Orgánica del Poder Judicial, las plazas convocadas por el turno de promoción interna de los Cuerpos al servicio de la Administración de Justicia que no resulten cubiertas:', 'El art. 490.2 LOPJ prohíbe que las plazas de promoción interna no cubiertas acrezcan al turno libre o se incorporen a la OEP. Para el Cuerpo de Letrados, en cambio, el art. 442.2 sí prevé que las no cubiertas por promoción interna acrezcan al turno libre.', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 490.2 LOPJ', 'En ambos casos, las plazas convocadas por el turno de promoción interna que no resulten cubiertas no podrán, en ningún caso, acrecer a las convocadas por turno libre ni incorporarse a la Oferta de Empleo Público.', null, 'b5a44d925fca4753c4955b5756c2d228626d673b8079cd5394e3a5a469c83118', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b5a44d925fca4753c4955b5756c2d228626d673b8079cd5394e3a5a469c83118')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No podrán, en ningún caso, acrecer a las convocadas por turno libre ni incorporarse a la Oferta de Empleo Público.', true), ('B', 'Acrecerán a las convocadas por turno libre.', false), ('C', 'Se incorporarán automáticamente a la Oferta de Empleo Público del año siguiente.', false), ('D', 'Se ofertarán a los funcionarios interinos que hayan superado algún ejercicio.', false)) as v(label, body, ok)
)
