with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 492 de la Ley Orgánica del Poder Judicial, los funcionarios de los Cuerpos al servicio de la Administración de Justicia pueden prolongar voluntariamente su permanencia en el servicio activo como máximo hasta que cumplan:', 'El art. 492.3 LOPJ permite la prolongación voluntaria en el servicio activo como máximo hasta los 70 años; la Administración debe resolver motivadamente su aceptación o denegación.', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 492.3 LOPJ', 'No obstante, los funcionarios podrán prolongar voluntariamente su permanencia en el servicio activo, como máximo hasta que cumplan 70 años de edad.', null, '02a7cf126675c92565184b725b9d0cee9837323fa017fe132f5e22735ac3bc85', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '02a7cf126675c92565184b725b9d0cee9837323fa017fe132f5e22735ac3bc85')
