)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 493 de la Ley Orgánica del Poder Judicial, los funcionarios que hayan sido separados del servicio como consecuencia de sanción disciplinaria:', 'El art. 493 LOPJ admite la rehabilitación de quienes perdieron la condición por pérdida de nacionalidad o incapacidad permanente, por inhabilitación o condena (extinguidas sus responsabilidades) y también de los separados por sanción disciplinaria. La competencia es del Ministro de Justicia (art. 494.1).', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 493 LOPJ', 'Asimismo podrán ser rehabilitados, los funcionarios que hayan sido separados del servicio como consecuencia de sanción disciplinaria.', null, '9f93c239d4c2f42e957427e7f4a394e0e9ea053ca5f0b390e0026716a180de9d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9f93c239d4c2f42e957427e7f4a394e0e9ea053ca5f0b390e0026716a180de9d')
  returning id
), o as (
