  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No podrán ser rehabilitados en ningún caso.', false), ('B', 'Solo podrán ser rehabilitados si recuperan la nacionalidad española.', false), ('C', 'Solo podrán ser rehabilitados por acuerdo del Consejo General del Poder Judicial.', false), ('D', 'Podrán ser rehabilitados mediante el procedimiento que reglamentariamente se establezca.', true)) as v(label, body, ok)
