  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 497 de la Ley Orgánica del Poder Judicial, los funcionarios de la Administración de Justicia están obligados a dar a conocer su identidad y categoría a los interesados que lo requieran:', 'El art. 497.j) LOPJ impone ese deber salvo que no sea posible por razones de seguridad.', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 497.j LOPJ', 'j) Dar a conocer su identidad y categoría a los interesados que lo requieran, salvo cuando ello no fuera posible por razones de seguridad.', null, 'e997d13cae5deef772dc7b1cc288262222acf36ef1f4c8ecc22574e02e740bcd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e997d13cae5deef772dc7b1cc288262222acf36ef1f4c8ecc22574e02e740bcd')
