with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionaria del Cuerpo de Tramitación Procesal y Administrativa quiere asesorar jurídicamente, sin cobrar, a una asociación vecinal. Según el artículo 498 de la Ley Orgánica del Poder Judicial, esa actividad:', 'El art. 498.3.b).2.º LOPJ declara incompatible para los Cuerpos Generales todo tipo de asesoramiento jurídico, sea retribuido o no.', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 498.3.b LOPJ', '2.º El desempeño de todo tipo de asesoramiento jurídico, sea retribuido o no.', null, '9342f8a25b6dc226975860f342a66fce1d534e34ce2862044e90be0d116de324', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9342f8a25b6dc226975860f342a66fce1d534e34ce2862044e90be0d116de324')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es compatible por no ser retribuida.', false), ('B', 'Es compatible si obtiene la previa autorización del Ministerio de Justicia o de la comunidad autónoma.', false), ('C', 'Es incompatible con su función, sea retribuida o no.', true), ('D', 'Es compatible si la asociación tiene su sede fuera del partido judicial de destino.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
