  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 500 de la Ley Orgánica del Poder Judicial, la incorporación de los funcionarios a la jornada de mañana y tarde:', 'El art. 500.3 LOPJ permite establecer jornadas de mañana y tarde por necesidades del servicio, pero la incorporación del funcionario es voluntaria y con medidas incentivadoras.', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 500.3 LOPJ', 'La incorporación de los funcionarios a la jornada de mañana y tarde será voluntaria y deberá ir acompañada de medidas incentivadoras.', null, '01fe68bd17439949356a5dd840573e230d6f85afba3aea58171907667f768fa6', false
