)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 504 de la Ley Orgánica del Poder Judicial, las licencias por asuntos propios:', 'El art. 504.3 LOPJ configura estas licencias sin retribución, con un máximo acumulado de tres meses cada dos años de servicios efectivos y subordinadas a las necesidades del servicio.', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 504.3 LOPJ', 'Los funcionarios podrán disfrutar de licencias por asuntos propios sin derecho a retribución alguna, cuya duración acumulada no podrá, en ningún caso, exceder de tres meses cada dos años de servicios efectivos y su concesión estará subordinada a las necesidades del servicio.', null, '4113f26c30e16cafa3cc75eb40ee29163a46f86bfca87fbe1feb21ee6e03f4f7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4113f26c30e16cafa3cc75eb40ee29163a46f86bfca87fbe1feb21ee6e03f4f7')
