with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario del Cuerpo de Auxilio Judicial no acude a su puesto por enfermedad. Según el artículo 504 de la Ley Orgánica del Poder Judicial, además de comunicar la imposibilidad de asistir, deberá solicitar licencia por enfermedad:', 'El art. 504.5 LOPJ obliga a solicitar la licencia en el cuarto día consecutivo de ausencia; la licencia inicial no puede superar quince días y se prorroga automáticamente si persiste la enfermedad.', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 504.5 LOPJ', 'los funcionarios deberán solicitar de la autoridad competente licencia por enfermedad en el cuarto día consecutivo a aquel en que se produjo la ausencia del puesto de trabajo.', null, '4682764834d1400aa82471873ea4b1b8e8f30dbb43b5a8d9a1add68af6cf12c4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4682764834d1400aa82471873ea4b1b8e8f30dbb43b5a8d9a1add68af6cf12c4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
