insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-13-cuerpos-generales-1' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Reglamento de Ingreso, Provisión de Puestos de Trabajo y Promoción Profesional del personal al servicio de la Administración de Justicia (RD 1451/2005), ¿cuál es el sistema ordinario de ingreso en los Cuerpos?', 'El art. 7 del RD 1451/2005 configura la oposición como sistema ordinario de ingreso y el concurso-oposición como excepcional (salvo para la promoción interna).', 'jus_13_cuerpos_generales_1', (select id from public.topics where slug = 'jus-13-cuerpos-generales-1'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2005-21264'), 'Art. 7.2-3 RD 1451/2005', 'La utilización del sistema de concurso-oposición tendrá carácter excepcional, sin perjuicio de lo establecido en el título II de este reglamento para la promoción interna. […] La selección por oposición es el sistema ordinario de ingreso', null, 'f684a3c0680d73929de3d081752831552b8b15bd30e401745c9c3f14bfc4d6fe', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f684a3c0680d73929de3d081752831552b8b15bd30e401745c9c3f14bfc4d6fe')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El concurso-oposición, siendo excepcional la oposición.', false), ('B', 'El concurso de méritos.', false), ('C', 'La oposición, siendo excepcional el concurso-oposición.', true), ('D', 'La oposición o el concurso-oposición, indistintamente.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
