insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-14-cuerpos-generales-2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de las siguientes es una de las situaciones administrativas de los funcionarios de los Cuerpos al servicio de la Administración de Justicia enumeradas en el artículo 506 de la Ley Orgánica del Poder Judicial?', 'El art. 506 LOPJ enumera servicio activo, servicios especiales, excedencia voluntaria por cuidado de familiares, por prestación de servicios en el sector público, por interés particular y por agrupación familiar, y suspensión de funciones.', 'jus_14_cuerpos_generales_2', (select id from public.topics where slug = 'jus-14-cuerpos-generales-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 506 LOPJ', 'a) Servicio activo. b) Servicios especiales. c) Excedencia voluntaria por cuidado de familiares. d) Excedencia voluntaria por prestación de servicios en el sector público. e) Excedencia voluntaria por interés particular. f) Excedencia voluntaria por agrupación familiar. g) Suspensión de funciones.', null, '915b5e4088939fa2d15d5c391fcff97213c96030ddd560b81aca1b6e24ea36c3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '915b5e4088939fa2d15d5c391fcff97213c96030ddd560b81aca1b6e24ea36c3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Expectativa de destino.', false), ('B', 'Excedencia voluntaria incentivada.', false), ('C', 'Servicio en otras Administraciones Públicas.', false), ('D', 'Excedencia voluntaria por agrupación familiar.', true)) as v(label, body, ok)
)
