)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario del Cuerpo de Auxilio Judicial es elegido concejal de su ayuntamiento. Según el artículo 507 de la Ley Orgánica del Poder Judicial, permanecerá en servicio activo:', 'El art. 507.2.d) LOPJ considera en servicio activo a los miembros de corporaciones locales salvo que desempeñen cargo retribuido y de dedicación exclusiva.', 'jus_14_cuerpos_generales_2', (select id from public.topics where slug = 'jus-14-cuerpos-generales-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 507.2.d LOPJ', 'd) Cuando accedan a la condición de miembros de las corporaciones locales, salvo que desempeñen cargo retribuido y de dedicación exclusiva en las mismas.', null, '4e680a939d7a375e546a7702299f85b8b4453ad577598cc1be19cca123b74bba', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4e680a939d7a375e546a7702299f85b8b4453ad577598cc1be19cca123b74bba')
  returning id
