)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 508 de la Ley Orgánica del Poder Judicial, los funcionarios en situación de servicios especiales:', 'El art. 508.5 LOPJ prohíbe en todo caso el asesoramiento pericial a órganos jurisdiccionales; además tienen derecho a reserva de puesto en la misma localidad (art. 508.3) y cobran la retribución del cargo efectivo, más los trienios (art. 508.4).', 'jus_14_cuerpos_generales_2', (select id from public.topics where slug = 'jus-14-cuerpos-generales-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 508.5 LOPJ', 'En ningún caso podrán asesorar pericialmente a órganos jurisdiccionales mientras permanezcan en esta situación.', null, '066db684d85da0f31df211cee11425a621542f0ff91cf9ae0b0ae3f08b6fc069', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '066db684d85da0f31df211cee11425a621542f0ff91cf9ae0b0ae3f08b6fc069')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En ningún caso podrán asesorar pericialmente a órganos jurisdiccionales mientras permanezcan en esa situación.', true), ('B', 'Podrán asesorar pericialmente a órganos jurisdiccionales con autorización del Ministerio de Justicia.', false), ('C', 'No tienen derecho a la reserva de un puesto de trabajo.', false), ('D', 'Perciben las retribuciones de su puesto de origen y no las del cargo que desempeñan.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
