with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 509 de la Ley Orgánica del Poder Judicial, los funcionarios tienen derecho a un período de excedencia para atender al cuidado de cada hijo de duración:', 'El art. 509.1 LOPJ reconoce una excedencia de hasta tres años por cuidado de cada hijo, a contar desde el nacimiento o la resolución judicial o administrativa.', 'jus_14_cuerpos_generales_2', (select id from public.topics where slug = 'jus-14-cuerpos-generales-2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 509.1 LOPJ', 'Los funcionarios tendrán derecho a un período de excedencia no superior a tres años para atender al cuidado de cada hijo', null, '904224b5907333e67c7c357abab06490d035d06b1e853cb45a2b941d1860eb5d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '904224b5907333e67c7c357abab06490d035d06b1e853cb45a2b941d1860eb5d')
