)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 509 de la Ley Orgánica del Poder Judicial, durante la excedencia por cuidado de familiares, el puesto desempeñado se reservará:', 'El art. 509.3 LOPJ reserva el puesto al menos dos años y, después, un puesto en la misma localidad y de igual retribución; el tiempo computa a efectos de trienios, carrera y Seguridad Social.', 'jus_14_cuerpos_generales_2', (select id from public.topics where slug = 'jus-14-cuerpos-generales-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 509.3 LOPJ', 'El puesto desempeñado se reservará al menos dos años. Transcurrido este periodo, dicha reserva lo será a un puesto en la misma localidad y de igual retribución.', null, '6cf0cef4d06aa370eba2ec7d26b4d78bcc7069197837fa6f2bca3689e5ae0976', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6cf0cef4d06aa370eba2ec7d26b4d78bcc7069197837fa6f2bca3689e5ae0976')
