  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 529 de la Ley Orgánica del Poder Judicial, no se puede tomar parte en un concurso de traslado para puestos genéricos hasta que hayan transcurrido, desde la resolución de convocatoria del concurso en el que se obtuvo el último destino definitivo:', 'El art. 529.3 LOPJ exige dos años, contándose como primer año el año natural de la resolución y como segundo el siguiente; quedan excluidos de esta limitación quienes carecen de destino definitivo y están obligados a concursar (art. 529.4).', 'jus_14_cuerpos_generales_2', (select id from public.topics where slug = 'jus-14-cuerpos-generales-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 529.3 LOPJ', 'No se podrá tomar parte en un concurso de traslado para la provisión de puestos de trabajo genéricos hasta tanto no hayan trancurrido dos años desde que se dictó la resolución por la que se convocó el concurso de traslado en el que el funcionario obtuvo su último destino definitivo', null, '3a7407ef2253876c0efed0ad5defb44f7a2ae382e50b29123c98cb87dc57040b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3a7407ef2253876c0efed0ad5defb44f7a2ae382e50b29123c98cb87dc57040b')
