with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 539 de la Ley Orgánica del Poder Judicial, la sanción de separación del servicio de un funcionario del Cuerpo de Tramitación Procesal y Administrativa destinado en una comunidad autónoma con competencias asumidas será acordada:', 'El art. 539 LOPJ reserva en todo caso la separación del servicio al Ministro de Justicia, aunque el resto de la potestad disciplinaria corresponda también a las comunidades autónomas con competencias.', 'jus_14_cuerpos_generales_2', (select id from public.topics where slug = 'jus-14-cuerpos-generales-2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 539 LOPJ', 'La separación del servicio, será acordada por el Ministro de Justicia en todo caso.', null, 'fd23bbbe560037069882827c0c426717c5fd80507f1505acf2aefadd5ed62d3d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fd23bbbe560037069882827c0c426717c5fd80507f1505acf2aefadd5ed62d3d')
