  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 540 de la Ley Orgánica del Poder Judicial, las faltas de los funcionarios de los Cuerpos al servicio de la Administración de Justicia prescriben:', 'El art. 540.1 LOPJ fija dos meses (leves), seis meses (graves) y un año (muy graves), desde su comisión. Los plazos de dos años, un año y seis meses son los de los LAJ (art. 469 bis).', 'jus_14_cuerpos_generales_2', (select id from public.topics where slug = 'jus-14-cuerpos-generales-2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 540.1 LOPJ', 'Las faltas leves prescribirán a los dos meses; las graves, a los seis meses, y las muy graves, al año. El plazo se computará desde al fecha de su comisión.', null, '4e871ac4753f7c1d61c8e5a19a3a1d0565e4cbc485c53c964a4c41f9d71ee714', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4e871ac4753f7c1d61c8e5a19a3a1d0565e4cbc485c53c964a4c41f9d71ee714')
  returning id
), o as (
