with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 28.1 de la Constitución Española, respecto del derecho a sindicarse de los funcionarios públicos, la ley:', 'El art. 28.1 CE permite a la ley limitar o exceptuar la sindicación de las Fuerzas o Institutos armados y Cuerpos sometidos a disciplina militar; para los funcionarios públicos solo prevé que regule las peculiaridades de su ejercicio.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 28.1 CE', 'La ley podrá limitar o exceptuar el ejercicio de este derecho a las Fuerzas o Institutos armados o a los demás Cuerpos sometidos a disciplina militar y regulará las peculiaridades de su ejercicio para los funcionarios públicos.', null, '5b706ff6c3893730a31ef7cf7f6bae8ca53fee05b46c3c07c020c58d92113b2f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5b706ff6c3893730a31ef7cf7f6bae8ca53fee05b46c3c07c020c58d92113b2f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Podrá limitarlo o exceptuarlo.', false), ('B', 'Regulará las peculiaridades de su ejercicio.', true), ('C', 'Podrá someterlo a autorización previa de la Administración.', false), ('D', 'Lo excluirá mientras se hallen en servicio activo.', false)) as v(label, body, ok)
)
