with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 11/1985, de Libertad Sindical, ¿cuál de los siguientes colectivos no puede pertenecer a sindicato alguno mientras se halle en activo?', 'El art. 1.4 LOLS, en desarrollo del art. 127.1 CE, impide a Jueces, Magistrados y Fiscales en activo pertenecer a sindicatos. Los funcionarios de los Cuerpos al servicio de la Administración de Justicia tienen derecho a la libre sindicación (art. 496.b LOPJ).', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-16660'), 'Art. 1.4 LOLS', 'De acuerdo con lo dispuesto en el artículo 127.1 de la Constitución, los Jueces, Magistrados y Fiscales no podrán pertenecer a sindicato alguno mientras se hallen en activo.', null, '2bd342681f6304f4953f241092ca3b6392603452b7b489b5f0960ed56a7727dc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2bd342681f6304f4953f241092ca3b6392603452b7b489b5f0960ed56a7727dc')
  returning id
), o as (
