with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 2 de la Ley Orgánica de Libertad Sindical, las organizaciones sindicales tienen derecho a no ser suspendidas ni disueltas sino mediante:', 'El art. 2.2.c) LOLS solo admite la suspensión o disolución de un sindicato por resolución judicial firme fundada en incumplimiento grave de las leyes.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-16660'), 'Art. 2.2.c LOLS', 'c) No ser suspendidas ni disueltas sino mediante resolución firme de la Autoridad Judicial, fundada en incumplimiento grave de las Leyes.', null, '90269c29ce27d66c05de3a9d41337217c7fc731c283756e6a78668ff5f4ea264', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '90269c29ce27d66c05de3a9d41337217c7fc731c283756e6a78668ff5f4ea264')
