with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7 de la Ley Orgánica de Libertad Sindical, para ser sindicato más representativo a nivel de Comunidad Autónoma, un sindicato de dicho ámbito no federado con organizaciones estatales debe obtener en ella:', 'El art. 7.1.a) LOLS exige al menos el 15 % de los delegados de personal y representantes en comités de empresa y órganos de las Administraciones públicas, con un mínimo de 1.500 representantes y sin federación con sindicatos estatales.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-16660'), 'Art. 7.1 LOLS', 'Los sindicatos de dicho ámbito que acrediten en el mismo una especial audiencia expresada en la obtención de, al menos, el 15 por 100 de los delegados de personal y de los representantes de los trabajadores en los comités de empresa, y en los órganos correspondientes de las Administraciones públicas, siempre que cuenten con un mínimo de 1.500 representantes y no estén federados o confederados con organizaciones sindicales de ámbito estatal', null, '9af8797b41a7d9a6ce957d68aaaecc8c4cbe35e02bd91aae13b14622946fa26a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9af8797b41a7d9a6ce957d68aaaecc8c4cbe35e02bd91aae13b14622946fa26a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al menos el 10 por 100 de los representantes, con un mínimo de 1.000 representantes.', false), ('B', 'Al menos el 15 por 100 de los representantes, sin mínimo absoluto.', false), ('C', 'Al menos el 15 por 100 de los representantes, con un mínimo de 1.500 representantes.', true), ('D', 'Al menos el 20 por 100 de los representantes, con un mínimo de 1.500 representantes.', false)) as v(label, body, ok)
)
