with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 496 de la Ley Orgánica del Poder Judicial, los funcionarios de los Cuerpos al servicio de la Administración de Justicia tienen derecho de huelga:', 'El art. 496.d) LOPJ reconoce el derecho de huelga en los términos de la legislación general para funcionarios, con garantía de los servicios esenciales de la Administración de Justicia.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 496.d LOPJ', 'd) De huelga, en los términos contenidos en la legislación general del Estado para funcionarios públicos, garantizándose el mantenimiento de los servicios esenciales de la Administración de Justicia.', null, '999ceedc25d512bf7ae065580c7723e77a4482c43ee28c5de0b2cf7902c5c412', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '999ceedc25d512bf7ae065580c7723e77a4482c43ee28c5de0b2cf7902c5c412')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
