with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 495 de la Ley Orgánica del Poder Judicial, para hacer efectivo el derecho de los funcionarios de la Administración de Justicia a la protección en materia de seguridad y salud en el trabajo, las Administraciones competentes procederán, entre otras medidas, a:', 'El art. 495.1.i) LOPJ obliga a evaluar los riesgos iniciales, establecer planes de emergencia y crear servicios de prevención y un Comité Central de Seguridad y Salud.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 495.1.i LOPJ', 'i) A recibir protección en materia de seguridad y salud en el trabajo, para lo cual las Administraciones competentes adoptarán aquellas medidas que sean necesarias para la aplicación efectiva de la normativa vigente sobre prevención de riesgos y salud laboral, procediendo a la evaluación de los riesgos iniciales y al establecimiento de planes de emergencia, así como a la creación de servicios de prevención y de un Comité Central de Seguridad y Salud.', null, '92aa2d7a5aaff802ea5d67c5be9183c55ad08ecb166ada7f4c0269eb5c734894', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '92aa2d7a5aaff802ea5d67c5be9183c55ad08ecb166ada7f4c0269eb5c734894')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La creación de una Junta de Personal de seguridad en cada órgano judicial.', false), ('B', 'La designación de un Delegado de Prevención por cada Letrado de la Administración de Justicia.', false), ('C', 'La evaluación de los riesgos iniciales, el establecimiento de planes de emergencia y la creación de servicios de prevención y de un Comité Central de Seguridad y Salud.', true), ('D', 'La atribución de la vigilancia de la salud al Instituto Nacional de Toxicología y Ciencias Forenses.', false)) as v(label, body, ok)
)
