with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 13 de la Ley 9/1987, de órganos de representación del personal al servicio de las Administraciones Públicas, cuando se promuevan elecciones para renovar la representación por conclusión del mandato, la promoción solo podrá efectuarse a partir de la fecha en que falten para el vencimiento del mandato:', 'El art. 13.4 de la Ley 9/1987, que sigue vigente como normativa básica por la disposición transitoria quinta del TREBEP, solo permite promover la renovación a partir de que falten tres meses para el vencimiento del mandato.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-14115'), 'Art. 13.4 Ley 9/1987', 'Cuando se promuevan elecciones para renovar la representación por conclusión de la duración del mandato, tal promoción sólo podrá efectuarse a partir de la fecha en que falten tres meses para el vencimiento del mandato.', null, '061da6bf93fdab60367e6426fa197587bb5f827aeadebd0ac4484407ef43fa1c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '061da6bf93fdab60367e6426fa197587bb5f827aeadebd0ac4484407ef43fa1c')
  returning id
