with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto-ley 17/1977, sobre relaciones de trabajo, cuando la huelga afecte a empresas encargadas de cualquier clase de servicios públicos, el preaviso al empresario y a la autoridad laboral habrá de ser, al menos, de:', 'El art. 4 del RDL 17/1977 eleva a diez días naturales el preaviso en servicios públicos; el general es de cinco días naturales (art. 3.3).', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1977-6061'), 'Art. 4 RDL 17/1977', 'Cuando la huelga afecte a empresas encargadas de cualquier clase de servicios públicos, el preaviso del comienzo de huelga al empresario y a la autoridad laboral habrá de ser, al menos, de diez días naturales.', null, '0843f59d05ea44088b9581cc3930d8b0631dd2f4b27b87eea37354dc085ef98e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0843f59d05ea44088b9581cc3930d8b0631dd2f4b27b87eea37354dc085ef98e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinco días naturales.', false), ('B', 'Diez días hábiles.', false), ('C', 'Diez días naturales.', true), ('D', 'Quince días naturales.', false)) as v(label, body, ok)
)
