insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-15-libertad-sindical' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 39 del texto refundido del Estatuto Básico del Empleado Público, en una unidad electoral con 40 funcionarios, su representación corresponderá a:', 'El art. 39.2 TREBEP atribuye la representación a Delegados de Personal en unidades de 6 a 49 funcionarios: uno hasta 30 y tres de 31 a 49, con representación conjunta y mancomunada. Las Juntas de Personal exigen un censo mínimo de 50.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 39.2 TREBEP', 'En las unidades electorales donde el número de funcionarios sea igual o superior a 6 e inferior a 50, su representación corresponderá a los Delegados de Personal. Hasta 30 funcionarios se elegirá un Delegado, y de 31 a 49 se elegirán tres, que ejercerán su representación conjunta y mancomunadamente.', null, 'acd0fab9b5fa78b5bda75bb9b065b04559a4bfd87af3209717e183eda075c484', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'acd0fab9b5fa78b5bda75bb9b065b04559a4bfd87af3209717e183eda075c484')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres Delegados de Personal, que ejercerán su representación conjunta y mancomunadamente.', true), ('B', 'Un Delegado de Personal.', false), ('C', 'Una Junta de Personal de cinco miembros.', false), ('D', 'Dos Delegados de Personal, que actuarán de forma solidaria.', false)) as v(label, body, ok)
)
