with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la escala del artículo 39 del texto refundido del Estatuto Básico del Empleado Público, ¿cuántos miembros tendrá la Junta de Personal de una unidad electoral de 180 funcionarios?', 'El art. 39.5 TREBEP asigna 9 representantes a las unidades de 101 a 250 funcionarios (5 de 50 a 100; 13 de 251 a 500). La antigua escala del art. 8 de la Ley 9/1987 (que daba 7) no está vigente: esa ley quedó derogada salvo su art. 7 y los artículos que mantiene la disposición transitoria quinta del TREBEP, entre los que no figura el art. 8.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 39.5 TREBEP', 'Cada Junta de Personal se compone de un número de representantes, en función del número de funcionarios de la Unidad electoral correspondiente, de acuerdo con la siguiente escala, en coherencia con lo establecido en el Estatuto de los Trabajadores: De 50 a 100 funcionarios: 5. De 101 a 250 funcionarios: 9.', null, '6f64a248e4e266595cbbcbf3ea6a2043ed72279cf4fc44cbb9ce1ab51fd6def1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6f64a248e4e266595cbbcbf3ea6a2043ed72279cf4fc44cbb9ce1ab51fd6def1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siete.', false), ('B', 'Cinco.', false), ('C', 'Nueve.', true), ('D', 'Trece.', false)) as v(label, body, ok)
)
