with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el texto refundido del Estatuto Básico del Empleado Público, el mandato de los miembros de las Juntas de Personal y de los Delegados de Personal será de:', 'El art. 42 TREBEP fija un mandato de cuatro años con posible reelección, que se entiende prorrogado si no se promueven nuevas elecciones.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 42 TREBEP', 'El mandato de los miembros de las Juntas de Personal y de los Delegados de Personal, en su caso, será de cuatro años, pudiendo ser reelegidos.', null, 'ee6a338385ab9ac54a941c89322c8be060b4fd35cd6029f0a0f68786d5cd0106', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ee6a338385ab9ac54a941c89322c8be060b4fd35cd6029f0a0f68786d5cd0106')
  returning id
), o as (
