  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuatro años, sin posibilidad de reelección.', false), ('B', 'Cuatro años, pudiendo ser reelegidos.', true), ('C', 'Tres años, pudiendo ser reelegidos.', false), ('D', 'Cinco años, pudiendo ser reelegidos una sola vez.', false)) as v(label, body, ok)
)
