with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 44 del texto refundido del Estatuto Básico del Empleado Público, las Juntas de Personal se eligen mediante:', 'El art. 44.d) TREBEP prevé listas cerradas y sistema proporcional corregido para las Juntas de Personal, y listas abiertas y sistema mayoritario para los Delegados de Personal.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 44.d TREBEP', 'd) Las Juntas de Personal se elegirán mediante listas cerradas a través de un sistema proporcional corregido, y los Delegados de Personal mediante listas abiertas y sistema mayoritario.', null, '6300a0cc5e4dd6bb0300f1c8ae73b13203a018bb906999dcde062eded279521e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6300a0cc5e4dd6bb0300f1c8ae73b13203a018bb906999dcde062eded279521e')
