with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 30 del texto refundido del Estatuto Básico del Empleado Público, los empleados públicos que ejerciten el derecho de huelga:', 'El art. 30.2 TREBEP excluye el devengo de retribuciones durante la huelga y aclara que la deducción no es sanción ni afecta a las prestaciones sociales.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 30.2 TREBEP', 'Quienes ejerciten el derecho de huelga no devengarán ni percibirán las retribuciones correspondientes al tiempo en que hayan permanecido en esa situación sin que la deducción de haberes que se efectúe tenga carácter de sanción, ni afecte al régimen respectivo de sus prestaciones sociales.', null, '26ae973a37b9b4e5665bbddeb6a5dff22f0572a8bf0c9b13a07b533f30a32753', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '26ae973a37b9b4e5665bbddeb6a5dff22f0572a8bf0c9b13a07b533f30a32753')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perciben el cincuenta por ciento de sus retribuciones durante el tiempo de huelga.', false), ('B', 'Sufren una deducción de haberes con carácter de sanción disciplinaria leve.', false), ('C', 'Perciben íntegras sus retribuciones, pero el tiempo de huelga no computa a efectos de trienios.', false), ('D', 'No devengan ni perciben las retribuciones del tiempo de huelga, sin que la deducción tenga carácter de sanción.', true)) as v(label, body, ok)
)
