insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 1/2000, de 7 de enero, de Enjuiciamiento Civil (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-16-declarativos-civiles', 'Tema 16. Los procedimientos declarativos en la Ley de Enjuiciamiento Civil y la jurisdicción voluntaria') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-16-declarativos-civiles' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 248 de la Ley de Enjuiciamiento Civil, pertenecen a la clase de los procesos declarativos:', 'El art. 248.2 LEC solo enumera dos procesos declarativos: el juicio ordinario y el juicio verbal. El monitorio y el cambiario son procesos especiales del libro IV.', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 248.2 LEC', '2. Pertenecen a la clase de los procesos declarativos: 1.º El juicio ordinario. 2.º El juicio verbal.', null, 'daef69a3b58e092899aec3ee94961778b7dccac100393473e5c485bdb1698ede', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'daef69a3b58e092899aec3ee94961778b7dccac100393473e5c485bdb1698ede')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El juicio ordinario, el juicio verbal y el juicio monitorio.', false), ('B', 'El juicio ordinario, el juicio verbal y el juicio cambiario.', false), ('C', 'El juicio ordinario y el juicio verbal.', true), ('D', 'Únicamente el juicio ordinario.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de Enjuiciamiento Civil, se decidirán en el juicio ordinario, por razón de la cuantía, las demandas cuya cuantía:', 'El art. 249.2 LEC atribuye al juicio ordinario las demandas de cuantía superior a 15.000 euros y aquellas cuyo interés económico sea imposible de calcular; las de cuantía no superior a 15.000 euros van al verbal (art. 250.2).', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 249.2 LEC', '2. Se decidirán también en el juicio ordinario las demandas cuya cuantía exceda de quince mil euros y aquéllas cuyo interés económico resulte imposible de calcular, ni siquiera de modo relativo.', null, 'ab6bf9b4f384def553794102565801b24e030a950771a2840f1f2eabce7539a9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ab6bf9b4f384def553794102565801b24e030a950771a2840f1f2eabce7539a9')
  returning id
), o as (
