)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 250 de la Ley de Enjuiciamiento Civil, ¿cuál de las siguientes demandas se decide en juicio verbal cualquiera que sea su cuantía?', 'La acción de división de cosa común figura en el art. 250.1.16.º LEC (juicio verbal por razón de la materia). El retracto, la tutela del honor y la impugnación de acuerdos sociales se deciden en juicio ordinario cualquiera que sea su cuantía (art. 249.1 LEC).', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 250.1.16.º LEC', '1. Se decidirán en juicio verbal, cualquiera que sea su cuantía, las demandas siguientes: […] 16.º Aquéllas en las que se ejercite la acción de división de cosa común.', null, 'a5a008d9d0bc45b7f14858d0a51d4f3f7cbfc48faea7d5fb99946f893379303d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a5a008d9d0bc45b7f14858d0a51d4f3f7cbfc48faea7d5fb99946f893379303d')
  returning id
