with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Los efectos y medidas provisionales acordados antes de la demanda de nulidad, separación o divorcio, ¿hasta cuándo subsisten según el artículo 771 de la Ley de Enjuiciamiento Civil?', 'Según el art. 771.5 LEC, las medidas previas solo subsisten si la demanda de nulidad, separación o divorcio se presenta en los treinta días siguientes a su adopción.', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 771.5 LEC', '5. Los efectos y medidas acordados de conformidad con lo dispuesto en este artículo sólo subsistirán si, dentro de los treinta días siguientes a su adopción se presenta la demanda de nulidad, separación o divorcio.', null, 'b35773a009cfcfcac9e427874196a01b526d48995fa615d14ba15e99aa1d5e70', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b35773a009cfcfcac9e427874196a01b526d48995fa615d14ba15e99aa1d5e70')
