  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 812 de la Ley de Enjuiciamiento Civil, puede acudir al proceso monitorio quien pretenda de otro el pago de deuda dineraria:', 'Tras su reforma, el art. 812.1 LEC no fija límite cuantitativo: el monitorio procede para deudas dinerarias de cualquier importe, siempre que sean líquidas, determinadas, vencidas y exigibles y se acrediten documentalmente.', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 812.1 LEC', '1. Podrá acudir al proceso monitorio quien pretenda de otro el pago de deuda dineraria de cualquier importe, líquida, determinada, vencida y exigible, cuando la deuda se acredite de alguna de las formas siguientes:', null, 'b9d803d9ed79135a857c05f7d461f7d80e8c1e20eb7c2a395688862ee689f4b8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b9d803d9ed79135a857c05f7d461f7d80e8c1e20eb7c2a395688862ee689f4b8')
  returning id
), o as (
