)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el proceso monitorio, ¿en qué plazo se requiere al deudor para que pague o comparezca y formule oposición?', 'El art. 815.1 LEC dispone que el LAJ requerirá al deudor para que, en veinte días, pague acreditándolo ante el tribunal o comparezca y formule oposición motivada.', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 815.1 LEC', 'el letrado o letrada de la Administración de Justicia requerirá al deudor para que, en el plazo de veinte días, pague al peticionario, acreditándolo ante el tribunal, o comparezca ante éste y alegue de forma fundada y motivada, en escrito de oposición, las razones por las que, a su entender, no debe, en todo o en parte, la cantidad reclamada.', null, 'a3bc658ca947c8ae9aab12371002ce127e89a338567527245a866e3af583a72e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a3bc658ca947c8ae9aab12371002ce127e89a338567527245a866e3af583a72e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el plazo de diez días.', false), ('B', 'En el plazo de cinco días.', false), ('C', 'En el plazo de veinte días.', true), ('D', 'En el plazo de un mes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario de auxilio judicial practicó el requerimiento de pago de un monitorio y el deudor ni pagó ni se opuso en plazo. Según el artículo 816 de la Ley de Enjuiciamiento Civil, ¿qué procede?', 'Ante la incomparecencia del deudor requerido, el art. 816.1 LEC prevé un decreto del LAJ que da por terminado el monitorio y el traslado al acreedor para que solicite la ejecución, sin necesidad de esperar los veinte días del art. 548.', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 816.1 LEC', '1. Si el deudor no atendiere el requerimiento de pago o no compareciere, el Letrado de la Administración de Justicia dictará decreto dando por terminado el proceso monitorio y dará traslado al acreedor para que inste el despacho de ejecución, bastando para ello con la mera solicitud, sin necesidad de que transcurra el plazo de veinte días previsto en el artículo 548 de esta Ley.', null, '122303fa386d707930d794afa88b031ef408757c4ae8fad41c833f3c1c434190', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '122303fa386d707930d794afa88b031ef408757c4ae8fad41c833f3c1c434190')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El juez dictará sentencia condenatoria sin necesidad de vista, que será notificada al deudor por edictos.', false), ('B', 'El Letrado de la Administración de Justicia convocará a las partes a una vista de juicio verbal para que el deudor exponga las razones del impago.', false), ('C', 'El acreedor deberá presentar demanda de juicio ordinario en el plazo de un mes, o se sobreseerán las actuaciones.', false), ('D', 'El Letrado de la Administración de Justicia dictará decreto dando por terminado el monitorio y dará traslado al acreedor para que inste el despacho de ejecución, bastando la mera solicitud.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un proceso monitorio en el que el deudor se ha opuesto y la cuantía excede de la propia del juicio verbal, si el peticionario no interpone la demanda correspondiente dentro del plazo de un mes desde el traslado del escrito de oposición:', 'El art. 818.2 LEC prevé que, si la cuantía excede del juicio verbal y el acreedor no presenta demanda en un mes desde el traslado de la oposición, el LAJ sobresee por decreto y condena en costas al acreedor.', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 818.2 LEC', 'Cuando el importe de la reclamación exceda de dicha cantidad, si el peticionario no interpusiera la demanda correspondiente dentro del plazo de un mes desde el traslado del escrito de oposición, el letrado o la letrada de la Administración de Justicia dictará decreto sobreseyendo las actuaciones y condenando en costas al acreedor.', null, '7f047bb390a34629d29220416693f120d32329f5777a307a16d9617e24c69b6d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7f047bb390a34629d29220416693f120d32329f5777a307a16d9617e24c69b6d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Letrado de la Administración de Justicia dictará decreto sobreseyendo las actuaciones y condenando en costas al acreedor.', true), ('B', 'El juez dictará auto despachando ejecución contra el deudor por la cantidad reclamada.', false), ('C', 'El proceso continuará de oficio por los trámites del juicio ordinario.', false), ('D', 'El Letrado de la Administración de Justicia dictará decreto dando por terminado el monitorio sin pronunciamiento sobre costas.', false)) as v(label, body, ok)
)
