insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 15/2015, de 2 de julio, de la Jurisdicción Voluntaria (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
