insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-16-declarativos-civiles' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 15/2015, de la Jurisdicción Voluntaria, ¿con qué antelación mínima deben ser citados los interesados a la comparecencia del expediente?', 'El art. 17.3 LJV exige citar con al menos quince días de antelación; quien vaya a oponerse debe hacerlo en los cinco días siguientes a su citación, sin que ello convierta el expediente en contencioso.', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391'), 'Art. 17.3 LJV', '3. Los interesados serán citados a la comparecencia con al menos quince días de antelación a su celebración, avisándoles de que deberán acudir a aquélla con los medios de prueba de que intenten valerse.', null, 'b0ba0e850e4d943579ee9a224f6ecc0e8f230d530d55ea2c449a829819a41fc8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b0ba0e850e4d943579ee9a224f6ecc0e8f230d530d55ea2c449a829819a41fc8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Con al menos diez días de antelación a su celebración.', false), ('B', 'Con al menos cinco días de antelación a su celebración.', false), ('C', 'Con al menos quince días de antelación a su celebración.', true), ('D', 'Con al menos veinte días de antelación a su celebración.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 19 de la Ley de la Jurisdicción Voluntaria, el expediente de jurisdicción voluntaria se resolverá:', 'El art. 19.1 LJV dispone que el expediente se resuelve por auto (juez) o decreto (Secretario judicial, hoy Letrado de la Administración de Justicia) en cinco días desde la comparecencia o, si no la hubo, desde la última diligencia.', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391'), 'Art. 19.1 LJV', '1. El expediente se resolverá por medio de auto o decreto, según corresponda la competencia al Juez o al Secretario judicial, en el plazo de cinco días a contar desde la terminación de la comparecencia o, si esta no se hubiera celebrado, desde la última diligencia practicada.', null, '9d9cdaaaaf131fcf386b4cc637cd87c24a879a98c2fc13628cdbd3731ba01ae2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9d9cdaaaaf131fcf386b4cc637cd87c24a879a98c2fc13628cdbd3731ba01ae2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por auto o decreto, según la competencia corresponda al juez o al Letrado de la Administración de Justicia, en el plazo de cinco días desde la terminación de la comparecencia.', true), ('B', 'Siempre por sentencia del juez, en el plazo de diez días desde la terminación de la comparecencia.', false), ('C', 'Por providencia o diligencia de ordenación, en el plazo de tres días desde la última diligencia practicada.', false), ('D', 'Por auto o decreto, según la competencia, en el plazo de veinte días desde la presentación de la solicitud.', false)) as v(label, body, ok)
)
