insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 1/2025, de 2 de enero, de medidas en materia de eficiencia del Servicio Público de Justicia (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2025-76', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-16-declarativos-civiles', 'Tema 16. Los procedimientos declarativos en la Ley de Enjuiciamiento Civil y la jurisdicción voluntaria') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-16-declarativos-civiles' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 1/2025, en el orden jurisdiccional civil, acudir previamente a algún medio adecuado de solución de controversias:', 'El art. 5.1 de la LO 1/2025 convierte el intento previo de negociación mediante un medio adecuado de solución de controversias en requisito de procedibilidad de la demanda civil, con las excepciones de los apartados 2 y 3.', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2025-76'), 'Art. 5.1 LO 1/2025', '1. En el orden jurisdiccional civil, con carácter general, para que sea admisible la demanda se considerará requisito de procedibilidad acudir previamente a algún medio adecuado de solución de controversias de los previstos en el artículo 2.', null, '6f4ec09d45706e443af5f999af7854278e3c6a4be14284510dd9e63fecb84819', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6f4ec09d45706e443af5f999af7854278e3c6a4be14284510dd9e63fecb84819')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es siempre voluntario y no afecta a la admisibilidad de la demanda.', false), ('B', 'Se considera, con carácter general, requisito de procedibilidad para que sea admisible la demanda.', true), ('C', 'Solo es obligatorio cuando la cuantía de la demanda exceda de quince mil euros.', false), ('D', 'Solo es exigible cuando lo acuerde el juez una vez admitida la demanda.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley Orgánica 1/2025, ¿cuál de las siguientes materias queda excluida, en todo caso, de la regulación de los medios adecuados de solución de controversias en vía no jurisdiccional?', 'El art. 3.2 de la LO 1/2025 excluye en todo caso las materias laboral, penal y concursal y los asuntos en que una parte sea una entidad del sector público. Los asuntos civiles y mercantiles, incluidos los transfronterizos, están dentro de su ámbito (art. 3.1).', 'jus_16_declarativos_civiles', (select id from public.topics where slug = 'jus-16-declarativos-civiles'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2025-76'), 'Art. 3.2 LO 1/2025', '2. Quedan excluidos, en todo caso, de lo dispuesto en este título las materias laboral, penal y concursal, así como los asuntos de cualquier naturaleza, con independencia del orden jurisdiccional ante el que deban ventilarse, en los que una de las partes sea una entidad perteneciente al sector público.', null, '3c6135ddfcc10fd6841d815eceab8d2e1ebd33f3bee7d7f9884be9a9244c0c54', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3c6135ddfcc10fd6841d815eceab8d2e1ebd33f3bee7d7f9884be9a9244c0c54')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La materia mercantil.', false), ('B', 'Los conflictos civiles transfronterizos.', false), ('C', 'Las reclamaciones de cantidad entre particulares.', false), ('D', 'La materia concursal.', true)) as v(label, body, ok)
)
