insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dictado por el juez el auto que contiene la orden general de ejecución, ¿cuándo debe dictar el Letrado de la Administración de Justicia el decreto con las medidas ejecutivas concretas?', 'El art. 551.3 LEC obliga al LAJ a dictar el decreto con las medidas ejecutivas, las de localización de bienes y el contenido del requerimiento de pago en el mismo día o en el siguiente día hábil al auto.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 551.3 LEC', '3. Dictado el auto por el juez o jueza, magistrado o magistrada, el letrado o letrada de la Administración de Justicia responsable de la ejecución, en el mismo día o en el siguiente día hábil a aquél en que hubiera sido dictado el auto despachando ejecución, dictará decreto en el que se contendrán:', null, 'c40069f9ca81a4c2cf878ee0908ae444099e68575b7afe16ac04a856efc4c3b4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c40069f9ca81a4c2cf878ee0908ae444099e68575b7afe16ac04a856efc4c3b4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el mismo día o en el siguiente día hábil a aquel en que se hubiera dictado el auto.', true), ('B', 'Dentro de los tres días hábiles siguientes a la notificación del auto al ejecutado.', false), ('C', 'Dentro de los cinco días siguientes a la firmeza del auto.', false), ('D', 'Una vez transcurrido el plazo de oposición del ejecutado.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si el título ejecutivo es una resolución procesal de condena, el ejecutado podrá oponerse a la ejecución por escrito:', 'El art. 556.1 LEC concede diez días desde la notificación del auto de despacho para oponerse alegando pago o cumplimiento, caducidad de la acción o pactos y transacciones en documento público.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 556.1 LEC', 'el ejecutado, dentro de los diez días siguientes a la notificación del auto en que se despache ejecución, podrá oponerse a ella por escrito alegando el pago o cumplimiento de lo ordenado en la sentencia, laudo o acuerdo, que habrá de justificar documentalmente.', null, '52703d9165f6a88c1c85a7dc7f1cb582941deb6ac2e76d645c34bb029e387311', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '52703d9165f6a88c1c85a7dc7f1cb582941deb6ac2e76d645c34bb029e387311')
  returning id
), o as (
