)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un funcionario de auxilio judicial asiste a una diligencia de embargo de bienes muebles. Según el artículo 624 de la Ley de Enjuiciamiento Civil, ¿cuál de los siguientes extremos debe incluirse en el acta?', 'El art. 624.1 LEC exige en el acta la relación detallada de los bienes, las manifestaciones de los intervinientes y la persona designada depositaria con el lugar de depósito. La tasación y las condiciones de subasta son trámites posteriores.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 624.1 LEC', '3.º Persona a la que se designa depositario y lugar donde se depositan los bienes.', null, 'b5f9f2ce00da78d5047c1a2ebb708ec5a6a4daaad8ada0016c6304c8181b3bc2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b5f9f2ce00da78d5047c1a2ebb708ec5a6a4daaad8ada0016c6304c8181b3bc2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
