)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 626 de la Ley de Enjuiciamiento Civil, se nombrará depositario de los bienes embargados al propio ejecutado:', 'El art. 626.3 LEC prevé nombrar depositario al ejecutado cuando destina los bienes a una actividad productiva o son de difícil o costoso transporte o almacenamiento. Los objetos especialmente valiosos pueden depositarse en establecimiento adecuado (art. 626.1).', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 626.3 LEC', '3. Se nombrará depositario al ejecutado si éste viniere destinando los bienes embargados a una actividad productiva o si resultaran de difícil o costoso transporte o almacenamiento.', null, 'def7350f1f4f0b1d5d78ed6e0c70e760a714ec465fa35e1f222bf7e8abe6fe53', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'def7350f1f4f0b1d5d78ed6e0c70e760a714ec465fa35e1f222bf7e8abe6fe53')
  returning id
), o as (
