)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si el depositario judicial no cumple sus obligaciones de conservación de los bienes embargados, ¿quién puede removerlo de su cargo y mediante qué resolución?', 'El art. 627.1 LEC permite al LAJ, de oficio o a instancia de parte, remover al depositario mediante decreto y designar a otro, sin perjuicio de su responsabilidad civil y penal.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 627.1 LEC', 'A instancia de parte o, de oficio, si no cumpliere sus obligaciones, el Letrado de la Administración de Justicia encargado de la ejecución, mediante decreto, podrá remover de su cargo al depositario, designando a otro, sin perjuicio de la responsabilidad penal y civil en que haya podido incurrir el depositario removido.', null, 'fbbc49d6736a3260726ac15e71fd18d9ad6b0e031966de0d98660a2751e5a741', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fbbc49d6736a3260726ac15e71fd18d9ad6b0e031966de0d98660a2751e5a741')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El juez, mediante providencia.', false), ('B', 'El Letrado de la Administración de Justicia encargado de la ejecución, mediante decreto.', true), ('C', 'El juez, mediante auto, solo a instancia del ejecutado.', false), ('D', 'El Letrado de la Administración de Justicia, mediante diligencia de ordenación.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando el ejecutado no lleva a cabo en plazo un hacer no personalísimo, según el artículo 706 de la Ley de Enjuiciamiento Civil el ejecutante podrá pedir:', 'En el hacer no personalísimo el art. 706.1 LEC permite encargarlo a un tercero a costa del ejecutado o pedir daños y perjuicios. Las multas mensuales y el equivalente pecuniario con multa única corresponden al hacer personalísimo (art. 709).', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 706.1 LEC', '1. Cuando el hacer a que obligue el título ejecutivo no sea personalísimo, si el ejecutado no lo llevara a cabo en el plazo señalado por el Letrado de la Administración de Justicia, el ejecutante podrá pedir que se le faculte para encargarlo a un tercero, a costa del ejecutado, o reclamar el resarcimiento de daños y perjuicios.', null, '8ee18158d8795b9f9d46a36c64345905dd18fa57bb5945788d1c8c1ec322731b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8ee18158d8795b9f9d46a36c64345905dd18fa57bb5945788d1c8c1ec322731b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que se imponga al ejecutado una multa por cada mes de retraso durante un año.', false), ('B', 'Que se le faculte para encargarlo a un tercero, a costa del ejecutado, o reclamar el resarcimiento de daños y perjuicios.', true), ('C', 'Que se decrete el arresto del ejecutado hasta que cumpla.', false), ('D', 'Únicamente que se le entregue un equivalente pecuniario con imposición de una multa única.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En los casos de desahucio por falta de pago de rentas, para evitar demoras en la práctica del lanzamiento, el artículo 703 de la Ley de Enjuiciamiento Civil permite, previa autorización del Letrado de la Administración de Justicia:', 'El art. 703.1 LEC dispone que en los desahucios por falta de pago o expiración del plazo basta, previa autorización del LAJ, un único funcionario con categoría de Gestor, que puede pedir el auxilio de la fuerza pública.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 703.1 LEC', 'En los casos de desahucio por falta de pago de rentas o cantidades debidas, o por expiración legal o contractual del plazo, para evitar demoras en la práctica del lanzamiento, previa autorización del Letrado de la Administración de Justicia, bastará con la presencia de un único funcionario con categoría de Gestor, que podrá solicitar el auxilio, en su caso, de la fuerza pública.', null, '59185fdd784d7453e9be0d7a22e76541815550d82834791762bf2cb956bcd044', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '59185fdd784d7453e9be0d7a22e76541815550d82834791762bf2cb956bcd044')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el lanzamiento lo practique el procurador del ejecutante sin presencia de funcionario alguno.', false), ('B', 'Que baste con la presencia de un único funcionario del Cuerpo de Auxilio Judicial, sin auxilio de la fuerza pública.', false), ('C', 'Que el lanzamiento lo practique directamente la fuerza pública, sin funcionarios de la oficina judicial.', false), ('D', 'Que baste con la presencia de un único funcionario con categoría de Gestor, que podrá solicitar el auxilio de la fuerza pública.', true)) as v(label, body, ok)
)
