with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando el inmueble cuya posesión deba entregarse sea la vivienda habitual del ejecutado, el Letrado de la Administración de Justicia le dará para desalojarlo un plazo de:', 'El art. 704.1 LEC concede un mes para desalojar la vivienda habitual, prorrogable un mes más con motivo fundado; transcurridos los plazos se procede al lanzamiento con día y hora exactos.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 704.1 LEC', '1. Cuando el inmueble cuya posesión se deba entregar fuera vivienda habitual del ejecutado o de quienes de él dependan, el Letrado de la Administración de Justicia les dará un plazo de un mes para desalojarlo. De existir motivo fundado, podrá prorrogarse dicho plazo un mes más.', null, '3518c43c0eed60cc9bb082f9321c5636d75350598bacada91d5056bff87d1f04', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3518c43c0eed60cc9bb082f9321c5636d75350598bacada91d5056bff87d1f04')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes, prorrogable un mes más si existe motivo fundado.', true), ('B', 'Quince días, prorrogables otros quince si existe motivo fundado.', false), ('C', 'Dos meses, improrrogables.', false), ('D', 'Diez días, prorrogables un mes más si existe motivo fundado.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
