with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Las medidas cautelares adoptadas antes de la demanda por razones de urgencia o necesidad quedarán sin efecto si la demanda no se presenta ante el mismo tribunal:', 'El art. 730.2 LEC fija veinte días desde la adopción de las medidas previas para presentar la demanda; si no se presenta, el LAJ las alza de oficio, condena en costas al solicitante y declara su responsabilidad por daños.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 730.2 LEC', 'En este caso, las medidas que se hubieran acordado quedarán sin efecto si la demanda no se presentare ante el mismo tribunal que conoció de la solicitud de aquéllas en los veinte días siguientes a su adopción.', null, 'c354b394208c1cf9efe7abb68e77650f9f2749bd108b47729aede2622504439f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c354b394208c1cf9efe7abb68e77650f9f2749bd108b47729aede2622504439f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En los treinta días siguientes a su adopción.', false), ('B', 'En los diez días siguientes a su adopción.', false), ('C', 'En los veinte días siguientes a su adopción.', true), ('D', 'En los dos meses siguientes a su adopción.', false)) as v(label, body, ok)
)
