with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Tras la vista sobre medidas cautelares, contra el auto que las acuerde cabrá:', 'Según el art. 735 LEC, el tribunal decide por auto en cinco días tras la vista y, contra el auto que acuerde las medidas, cabe apelación sin efectos suspensivos.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 735.2 LEC', 'Contra el auto que acuerde medidas cautelares cabrá recurso de apelación, sin efectos suspensivos.', null, '34dde391c8a6510db1c626533e66ed6fea7717fb1341015d0a2e7419dc0b5442', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '34dde391c8a6510db1c626533e66ed6fea7717fb1341015d0a2e7419dc0b5442')
