insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto de 14 de septiembre de 1882, Ley de Enjuiciamiento Criminal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-18-procedimientos-penales', 'Tema 18. Los procedimientos penales en la Ley de Enjuiciamiento Criminal') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-18-procedimientos-penales' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 757 de la Ley de Enjuiciamiento Criminal, el procedimiento abreviado se aplica al enjuiciamiento de los delitos castigados con pena privativa de libertad:', 'El art. 757 LECrim reserva el procedimiento abreviado para los delitos con pena privativa de libertad no superior a nueve años, o con penas de distinta naturaleza de cualquier cuantía o duración.', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 757 LECrim', 'el procedimiento regulado en este Título se aplicará al enjuiciamiento de los delitos castigados con pena privativa de libertad no superior a nueve años, o bien con cualesquiera otras penas de distinta naturaleza bien sean únicas, conjuntas o alternativas, cualquiera que sea su cuantía o duración.', null, '1c4d6ada0386fda11aeb1f6354943b8e95c0053acb8e7f2afdd473d8ca435ca0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1c4d6ada0386fda11aeb1f6354943b8e95c0053acb8e7f2afdd473d8ca435ca0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No superior a nueve años.', true), ('B', 'No superior a cinco años.', false), ('C', 'No superior a tres años.', false), ('D', 'No superior a diez años.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 14 de la Ley de Enjuiciamiento Criminal, ¿a quién corresponde con carácter general el conocimiento y fallo de las causas por delitos castigados con pena privativa de libertad de duración no superior a cinco años?', 'El art. 14.3 LECrim atribuye a la Sección de lo Penal del Tribunal de Instancia el enjuiciamiento de los delitos con pena privativa de libertad no superior a cinco años; en los demás casos conoce, según el art. 14.4, la Audiencia Provincial (o el Tribunal del Jurado o la Sala de lo Penal de la Audiencia Nacional cuando proceda).', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 14.3 LECrim', 'Para el conocimiento y fallo de las causas por delitos a los que la ley señale pena privativa de libertad de duración no superior a cinco años o pena de multa cualquiera que sea su cuantía, o cualesquiera otras de distinta naturaleza, bien sean únicas, conjuntas o alternativas, siempre que la duración de estas no exceda de diez años, así como por delitos leves, sean o no incidentales, imputables a los autores de estos delitos o a otras personas, cuando la comisión del delito leve o su prueba estuviesen relacionadas con aquellos, la Sección de lo Penal del Tribunal de Instancia de la circunscripción donde el delito fue cometido', null, '72e6ff4d273d490db13a8e13dd850e82a401794f717bb3be6c6513c12f28ef81', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '72e6ff4d273d490db13a8e13dd850e82a401794f717bb3be6c6513c12f28ef81')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A la Audiencia Provincial de la circunscripción donde el delito se haya cometido.', false), ('B', 'A la Sección de Instrucción del Tribunal de Instancia del partido en que se cometió el delito.', false), ('C', 'Al Tribunal del Jurado.', false), ('D', 'A la Sección de lo Penal del Tribunal de Instancia de la circunscripción donde el delito fue cometido.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el procedimiento ordinario por delitos graves, cuando se mande abrir el juicio oral, ¿en qué plazo deben el Fiscal o, en su caso, el acusador privado calificar por escrito los hechos, según el artículo 649 de la Ley de Enjuiciamiento Criminal?', 'El art. 649 LECrim fija en cinco días el término para la calificación escrita de los hechos una vez acordada la apertura del juicio oral.', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 649 LECrim', 'Cuando se mande abrir el juicio oral, el Secretario judicial comunicará la causa al Fiscal, o al acusador privado si versa sobre delito que no pueda ser perseguido de oficio, para que en el término de cinco días califiquen por escrito los hechos.', null, '0b9998bd6635be3375022d035690419ac6bc6b08c7bc38b421a575fc10f9e1e1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0b9998bd6635be3375022d035690419ac6bc6b08c7bc38b421a575fc10f9e1e1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres días.', false), ('B', 'Cinco días.', true), ('C', 'Diez días.', false), ('D', 'Quince días.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 627 de la Ley de Enjuiciamiento Criminal, recibido el sumario en el Tribunal, los autos se pasan para instrucción a las partes por un término que:', 'El art. 627 LECrim fija un término de tres a diez días según el volumen del proceso; si la causa excede de mil folios puede prorrogarse, como máximo, por otro tanto.', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 627 LECrim', 'Transcurrido dicho término, el Secretario judicial pasará los autos para instrucción por otro, que no bajará de tres días ni excederá de diez, según el volumen del proceso', null, '6c9438fe7c02eaad5932c04b2b35e2dec9a3669aeae2a73b86ed8538fd4fdf12', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6c9438fe7c02eaad5932c04b2b35e2dec9a3669aeae2a73b86ed8538fd4fdf12')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No bajará de cinco días ni excederá de quince, según el volumen del proceso.', false), ('B', 'Será en todo caso de diez días, improrrogables.', false), ('C', 'No bajará de tres días ni excederá de diez, según el volumen del proceso.', true), ('D', 'No bajará de tres días ni excederá de cinco, sin posibilidad de prórroga.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
