  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Abierto el juicio oral en un procedimiento abreviado, se emplaza al encausado con entrega de copia de los escritos de acusación. Según el artículo 784 de la Ley de Enjuiciamiento Criminal, ¿en qué plazo debe comparecer en la causa con Abogado y Procurador?', 'El art. 784.1 LECrim concede tres días para comparecer con Abogado y Procurador; después se da traslado a la defensa para presentar escrito de defensa en el plazo común de diez días.', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 784.1 LECrim', 'Abierto el juicio oral, el Secretario judicial emplazará al encausado, con entrega de copia de los escritos de acusación, para que en el plazo de tres días comparezca en la causa con Abogado que le defienda y Procurador que le represente.', null, '995c14cfec67e6be170bcf56656ad5953fb42e2117af6ba80c1907a0a2895463', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '995c14cfec67e6be170bcf56656ad5953fb42e2117af6ba80c1907a0a2895463')
  returning id
