with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 787 de la Ley de Enjuiciamiento Criminal, la ausencia injustificada de la persona acusada citada en forma no impide celebrar el juicio oral del procedimiento abreviado, si concurren los demás requisitos, cuando la pena más grave solicitada no exceda de:', 'El art. 787.1.a) LECrim permite el juicio en ausencia si la pena más grave pedida no excede de dos años de prisión o de seis años si es de distinta naturaleza (o es multa), y la suma de penas privativas de libertad no excede de cinco años.', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 787.1 LECrim', 'a) Que la pena más grave solicitada no exceda de dos años de privación de libertad, que no exceda de seis años si se trata de pena de distinta naturaleza o que se trate de pena de multa cualquiera que sea su cuantía o duración.', null, '7ef357e51fe55eae6512939430bfb2ec35b4f0646ea89676ca2e2b503b950aa9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7ef357e51fe55eae6512939430bfb2ec35b4f0646ea89676ca2e2b503b950aa9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos años de privación de libertad, o seis años si se trata de pena de distinta naturaleza.', true), ('B', 'Cinco años de privación de libertad, o diez años si se trata de pena de distinta naturaleza.', false), ('C', 'Un año de privación de libertad, o tres años si se trata de pena de distinta naturaleza.', false), ('D', 'Tres años de privación de libertad, o seis años si se trata de pena de distinta naturaleza.', false)) as v(label, body, ok)
)
