with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 795 de la Ley de Enjuiciamiento Criminal, el procedimiento de enjuiciamiento rápido no se aplicará:', 'El art. 795.3 LECrim excluye el juicio rápido si procede el secreto de las actuaciones; en cambio, los hurtos, robos, delitos contra la seguridad del tráfico y los delitos flagrantes están expresamente incluidos en su ámbito.', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 795.3 LECrim', '3. No se aplicará este procedimiento en aquellos casos en que sea procedente acordar el secreto de las actuaciones conforme a lo establecido en el artículo 302.', null, 'fc56324570a8796d7dbcd1c0055523778faf41f2bc27b14891bbedb2a665d1eb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fc56324570a8796d7dbcd1c0055523778faf41f2bc27b14891bbedb2a665d1eb')
