  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En unas diligencias urgentes en las que se ha abierto el juicio oral ante el Juzgado de guardia, el señalamiento del juicio debe hacerse en la fecha más próxima posible y, en cualquier caso, según el artículo 800 de la Ley de Enjuiciamiento Criminal:', 'El art. 800.3 LECrim obliga a señalar el juicio oral en la fecha más próxima posible y, en todo caso, dentro de los quince días siguientes.', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 800.3 LECrim', 'El Secretario del Juzgado de Guardia hará el señalamiento para la celebración del juicio oral en la fecha más próxima posible y, en cualquier caso, dentro de los quince días siguientes', null, '4aaab0279133b276c0b8108be94cdb1f99d50af500b9eea1c9f3e1ecae2fdc8c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4aaab0279133b276c0b8108be94cdb1f99d50af500b9eea1c9f3e1ecae2fdc8c')
