with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando el acusado presta su conformidad ante el juzgado de guardia en un juicio rápido, la sentencia de conformidad impondrá, según el artículo 801 de la Ley de Enjuiciamiento Criminal:', 'El art. 801.2 LECrim impone la pena solicitada reducida en un tercio, aun cuando quede por debajo del mínimo legal previsto en el Código Penal.', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 801.2 LECrim', 'en la que impondrá la pena solicitada reducida en un tercio, aun cuando suponga la imposición de una pena inferior al límite mínimo previsto en el Código Penal.', null, '017437bac062b532ab3b16e8d2c639e2a8acdc651b109bd1c1dda84abdcfe277', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '017437bac062b532ab3b16e8d2c639e2a8acdc651b109bd1c1dda84abdcfe277')
