insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-19-contencioso' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 46 de la Ley 29/1998, reguladora de la Jurisdicción Contencioso-administrativa, el plazo para interponer el recurso contencioso-administrativo contra un acto expreso que ponga fin a la vía administrativa es de:', 'El art. 46.1 LJCA fija dos meses desde el día siguiente a la publicación o notificación del acto expreso; si el acto no es expreso, el plazo es de seis meses.', 'jus_19_contencioso', (select id from public.topics where slug = 'jus-19-contencioso'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 46.1 LJCA', 'El plazo para interponer el recurso contencioso-administrativo será de dos meses contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.', null, '3922a6ba5526bc89873501c7e50a8f660ecb56056c8692c51b0becd3bde492c5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3922a6ba5526bc89873501c7e50a8f660ecb56056c8692c51b0becd3bde492c5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes, contado desde el día siguiente al de su notificación o publicación.', false), ('B', 'Seis meses, contados desde el día siguiente al de su notificación o publicación.', false), ('C', 'Dos meses, contados desde el día siguiente al de su notificación o publicación.', true), ('D', 'Tres meses, contados desde el día de su notificación o publicación.', false)) as v(label, body, ok)
)
