with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 46 de la Ley 29/1998, si el recurso contencioso-administrativo se dirige contra una actuación en vía de hecho y no hubo requerimiento previo a la Administración, el plazo para interponerlo será de:', 'El art. 46.3 LJCA fija diez días desde que termina el plazo del requerimiento del art. 30 y, si no hubo requerimiento, veinte días desde que se inició la vía de hecho.', 'jus_19_contencioso', (select id from public.topics where slug = 'jus-19-contencioso'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 46.3 LJCA', 'Si no hubiere requerimiento, el plazo será de veinte días desde el día en que se inició la actuación administrativa en vía de hecho.', null, '822f1d5553a1c2d83a15ffb61344c3354679e74c9fb911a34b82cb7780259897', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '822f1d5553a1c2d83a15ffb61344c3354679e74c9fb911a34b82cb7780259897')
  returning id
), o as (
