  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 48 de la Ley 29/1998, la Administración requerida debe remitir el expediente administrativo al órgano judicial en el plazo:', 'El art. 48.3 LJCA fija un plazo improrrogable de veinte días a contar desde la entrada de la comunicación judicial en el registro general del órgano requerido.', 'jus_19_contencioso', (select id from public.topics where slug = 'jus-19-contencioso'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 48.3 LJCA', 'El expediente deberá ser remitido en el plazo improrrogable de veinte días, a contar desde que la comunicación judicial tenga entrada en el registro general del órgano requerido.', null, 'fa03c34609d1a915413741c24438076b5af1d4a5c382351c63732c7c6bdaf299', false
