with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 48 de la Ley 29/1998, si, reiterada la reclamación, la Administración no envía el expediente completo, el juez o tribunal impondrá a la autoridad o empleado responsable una multa coercitiva de:', 'El art. 48.7 LJCA prevé una multa coercitiva de 300 a 1.200 euros, reiterada cada veinte días; tras tres multas sin éxito se ponen los hechos en conocimiento del Ministerio Fiscal (art. 48.10).', 'jus_19_contencioso', (select id from public.topics where slug = 'jus-19-contencioso'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 48.7 LJCA', 'el juez, la jueza o el tribunal impondrán una multa coercitiva de trescientos a mil doscientos euros a la autoridad o empleado responsable. La multa será reiterada cada veinte días, hasta el cumplimiento de lo requerido.', null, '68e1060e0426d18afd318b8b8f967b4df3116c6a6733bc9cf2c8324aedfac8ce', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '68e1060e0426d18afd318b8b8f967b4df3116c6a6733bc9cf2c8324aedfac8ce')
