insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 36/2011, de 10 de octubre, reguladora de la jurisdicción social (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-20-proceso-laboral', 'Tema 20. El proceso laboral: ordinario, despido y seguridad social') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-20-proceso-laboral' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 63 de la Ley 36/2011, reguladora de la jurisdicción social, ¿qué es requisito previo, con carácter general, para la tramitación del proceso laboral?', 'El art. 63 LRJS exige como requisito previo el intento de conciliación o mediación ante el servicio administrativo correspondiente o el órgano creado por acuerdos interprofesionales o convenios colectivos.', 'jus_20_proceso_laboral', (select id from public.topics where slug = 'jus-20-proceso-laboral'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 63 LRJS', 'Será requisito previo para la tramitación del proceso el intento de conciliación o, en su caso, de mediación ante el servicio administrativo correspondiente o ante el órgano que asuma estas funciones', null, 'ac20a66e6eab892536269d4242681075fbef9976760beaf4e13b21d64b5b452a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ac20a66e6eab892536269d4242681075fbef9976760beaf4e13b21d64b5b452a')
  returning id
