select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 242 de la Ley Orgánica del Poder Judicial, las actuaciones judiciales realizadas fuera del tiempo establecido:', 'El art. 242 LOPJ dispone que la actuación realizada fuera de tiempo solo puede anularse cuando lo imponga la naturaleza del término o plazo.', 'jus_21_actos_procesales', (select id from public.topics where slug = 'jus-21-actos-procesales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 242 LOPJ', 'Las actuaciones judiciales realizadas fuera del tiempo establecido sólo podrán anularse si lo impusiere la naturaleza del término o plazo.', null, 'e4175cacc657c9a846e70f2327c21d5952f5dacb912a000f44879a7e77276aa8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e4175cacc657c9a846e70f2327c21d5952f5dacb912a000f44879a7e77276aa8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Son siempre nulas de pleno derecho.', false), ('B', 'Son anulables a instancia de cualquier parte en todo caso.', false), ('C', 'Sólo podrán anularse si lo impusiere la naturaleza del término o plazo.', true), ('D', 'No pueden anularse en ningún caso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 243 de la Ley Orgánica del Poder Judicial, el juzgado o tribunal cuidará de que puedan ser subsanados los defectos en que incurran los actos procesales de las partes:', 'El art. 243.3 LOPJ impone al órgano judicial facilitar la subsanación cuando la parte haya manifestado la voluntad de cumplir los requisitos legales; la nulidad de un acto no arrastra a los sucesivos independientes (art. 243.1).', 'jus_21_actos_procesales', (select id from public.topics where slug = 'jus-21-actos-procesales'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 243.3 LOPJ', 'El juzgado o tribunal cuidará de que puedan ser subsanados los defectos en que incurran los actos procesales de las partes, siempre que en dichos actos se hubiese manifestado la voluntad de cumplir los requisitos exigidos por la ley.', null, '1415aeaf452aad8b9b223a941f4616fc2c5ad5260eeeca5670d8a54b5e476976', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1415aeaf452aad8b9b223a941f4616fc2c5ad5260eeeca5670d8a54b5e476976')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre que en dichos actos se hubiese manifestado la voluntad de cumplir los requisitos exigidos por la ley.', true), ('B', 'Solo cuando lo solicite la parte contraria.', false), ('C', 'Solo si el defecto se advierte antes de la admisión a trámite.', false), ('D', 'Únicamente en el proceso penal.', false)) as v(label, body, ok)
)
