insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-22-resoluciones' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 206 de la Ley de Enjuiciamiento Civil, cuando la ley no exprese la clase de resolución, el Letrado de la Administración de Justicia dictará diligencia de ordenación cuando la resolución tenga por objeto:', 'El art. 206.2.1.ª LEC reserva la diligencia de ordenación para dar a los autos el curso legal; admitir la demanda, poner término al procedimiento de su competencia exclusiva o razonar lo resuelto exige decreto (regla 2.ª).', 'jus_22_resoluciones', (select id from public.topics where slug = 'jus-22-resoluciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 206.2 LEC', '1.ª Se dictará diligencia de ordenación cuando la resolución tenga por objeto dar a los autos el curso que la ley establezca.', null, 'e8897929ebe5ae7ebbd23aa9b61ca718f4623692c9f56af496301cda3a5d8de5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e8897929ebe5ae7ebbd23aa9b61ca718f4623692c9f56af496301cda3a5d8de5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Admitir a trámite la demanda.', false), ('B', 'Poner término a un procedimiento de su competencia exclusiva.', false), ('C', 'Razonar lo resuelto por ser preciso o conveniente.', false), ('D', 'Dar a los autos el curso que la ley establezca.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de Enjuiciamiento Civil, los errores materiales manifiestos y los aritméticos en que incurran las resoluciones de los Tribunales y de los Letrados de la Administración de Justicia podrán ser rectificados:', 'El art. 214.3 LEC permite rectificar en cualquier momento los errores materiales manifiestos y los aritméticos; el plazo de dos días hábiles es el de la aclaración de conceptos oscuros (art. 214.2).', 'jus_22_resoluciones', (select id from public.topics where slug = 'jus-22-resoluciones'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 214.3 LEC', '3. Los errores materiales manifiestos y los aritméticos en que incurran las resoluciones de los Tribunales y Letrados de la Administración de Justicia podrán ser rectificados en cualquier momento.', null, '7636d61117b3dcec5362c03dfb79ad4a12460712d78b285570216265e205da95', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7636d61117b3dcec5362c03dfb79ad4a12460712d78b285570216265e205da95')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo dentro de los dos días hábiles siguientes al de la publicación de la resolución.', false), ('B', 'En cualquier momento.', true), ('C', 'Solo dentro de los cinco días siguientes a la notificación de la resolución.', false), ('D', 'Solo mientras la resolución no haya adquirido firmeza.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 206 de la Ley de Enjuiciamiento Civil, cuando la ley no exprese la clase de resolución, el Letrado de la Administración de Justicia dictará decreto:', 'El art. 206.2.2.ª LEC prevé el decreto para admitir a trámite la demanda, poner término al procedimiento de competencia exclusiva del LAJ y cuando sea preciso o conveniente razonar lo resuelto; los recursos contra providencias se resuelven por auto del tribunal.', 'jus_22_resoluciones', (select id from public.topics where slug = 'jus-22-resoluciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 206.2 LEC', '2.ª Se dictará decreto cuando se admita a trámite la demanda, cuando se ponga término al procedimiento del que el Secretario tuviera atribuida competencia exclusiva y, en cualquier clase de procedimiento, cuando fuere preciso o conveniente razonar lo resuelto.', null, '0d9d29bbafdd00f18bb45af457612d4f08711b2915211ac1b34737c4c17d6b40', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0d9d29bbafdd00f18bb45af457612d4f08711b2915211ac1b34737c4c17d6b40')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando la resolución tenga por objeto dar a los autos el curso que la ley establezca.', false), ('B', 'Cuando deba reflejar en autos hechos o actos con trascendencia procesal.', false), ('C', 'Cuando se decidan recursos contra providencias.', false), ('D', 'Cuando se admita a trámite la demanda.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Civil, las aclaraciones de algún concepto oscuro de una resolución podrán hacerse de oficio:', 'El art. 214.2 LEC fija dos días hábiles desde la publicación para aclarar de oficio o a petición de parte o del Ministerio Fiscal; la solicitud de parte se resuelve en los tres días siguientes.', 'jus_22_resoluciones', (select id from public.topics where slug = 'jus-22-resoluciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 214.2 LEC', '2. Las aclaraciones a que se refiere el apartado anterior podrán hacerse de oficio, por el Tribunal o Letrado de la Administración de Justicia, según corresponda, dentro de los dos días hábiles siguientes al de la publicación de la resolución', null, '29e094446aebc01774635616f5866efe8a76a4942820baed6fc348bfff74ba7c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '29e094446aebc01774635616f5866efe8a76a4942820baed6fc348bfff74ba7c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dentro de los cinco días siguientes al de la notificación de la resolución.', false), ('B', 'Dentro de los dos días hábiles siguientes al de la publicación de la resolución.', true), ('C', 'Dentro de los tres días hábiles siguientes al de la firma de la resolución.', false), ('D', 'En cualquier momento, mientras no se haya iniciado la ejecución.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de Enjuiciamiento Civil, en la votación de las resoluciones de los tribunales colegiados:', 'El art. 198.2 LEC (y el art. 254.2 LOPJ) ordena votar primero al ponente, después a los demás por orden inverso a su antigüedad (de menor a mayor) y en último lugar al Presidente.', 'jus_22_resoluciones', (select id from public.topics where slug = 'jus-22-resoluciones'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 198.2 LEC', '2. Votará primero el ponente y después los restantes Magistrados, por el orden inverso a su antigüedad. El Presidente votará el último.', null, '0bdd446739d06ea4b02667398b97d383fefe5e29dac048216e768dd691fa342e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0bdd446739d06ea4b02667398b97d383fefe5e29dac048216e768dd691fa342e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Votará primero el Presidente, después el ponente y luego los restantes magistrados por orden de antigüedad.', false), ('B', 'Votará primero el magistrado más moderno, después los restantes por orden de antigüedad y el ponente votará el último.', false), ('C', 'Votará primero el ponente, después los restantes magistrados de mayor a menor antigüedad y el Presidente votará el último.', false), ('D', 'Votará primero el ponente, después los restantes magistrados por el orden inverso a su antigüedad y el Presidente votará el último.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 215 de la Ley de Enjuiciamiento Civil, si una sentencia ha omitido manifiestamente pronunciamientos relativos a pretensiones oportunamente deducidas, la parte podrá solicitar que se complete:', 'El art. 215.2 LEC establece la solicitud escrita en cinco días desde la notificación, traslado por el LAJ a las demás partes por otros cinco días y resolución mediante auto.', 'jus_22_resoluciones', (select id from public.topics where slug = 'jus-22-resoluciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 215.2 LEC', '2. Si se tratase de sentencias o autos que hubieren omitido manifiestamente pronunciamientos relativos a pretensiones oportunamente deducidas y sustanciadas en el proceso, el Tribunal, a solicitud escrita de parte en el plazo de cinco días a contar desde la notificación de la resolución, previo traslado por el Letrado de la Administración de Justicia de dicha solicitud a las demás partes, para alegaciones escritas por otros cinco días, dictará auto', null, '3a379e9f9c37045be4a424bd7f3d08e8f7a0373ad377f417142db2d45b179415', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3a379e9f9c37045be4a424bd7f3d08e8f7a0373ad377f417142db2d45b179415')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por escrito, en el plazo de cinco días desde la notificación, con traslado a las demás partes para alegaciones escritas por otros cinco días, resolviéndose por auto.', true), ('B', 'Por escrito, en el plazo de dos días hábiles desde la publicación, con traslado a las demás partes por tres días, resolviéndose por providencia.', false), ('C', 'Verbalmente, en el plazo de diez días desde la notificación, sin traslado a las demás partes, resolviéndose por decreto.', false), ('D', 'Por escrito, en el plazo de cinco días desde la publicación, con traslado a las demás partes por diez días, resolviéndose por sentencia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Civil, si en un tribunal colegiado no se obtuviere acuerdo y la discordia se resuelve mediante nueva vista, a los magistrados que asistieron a la primera se sumarán:', 'El art. 202.2 LEC (igual que el art. 262.2 LOPJ) aumenta la Sala de discordia en dos magistrados si los discordantes fueron impares y en tres si fueron pares.', 'jus_22_resoluciones', (select id from public.topics where slug = 'jus-22-resoluciones'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 202.2 LEC', '2. Si no se obtuviere acuerdo, la discordia se resolverá mediante celebración de nueva vista, concurriendo los Magistrados que hubieran asistido a la primera, aumentándose dos más, si hubiese sido impar el número de los discordantes, y tres en el caso de haber sido par.', null, '489fd1ff5bd115dfb4dd61a83950e4ef3f59392d9a26f4650a97458db0343d58', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '489fd1ff5bd115dfb4dd61a83950e4ef3f59392d9a26f4650a97458db0343d58')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos más, si hubiese sido impar el número de los discordantes, y tres si hubiese sido par.', true), ('B', 'Tres más, si hubiese sido impar el número de los discordantes, y dos si hubiese sido par.', false), ('C', 'Dos más en todo caso.', false), ('D', 'Uno más, si hubiese sido impar el número de los discordantes, y dos si hubiese sido par.', false)) as v(label, body, ok)
)
