  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de Enjuiciamiento Civil, los actos de comunicación que hayan de practicarse por tribunal distinto del que los hubiere ordenado se cumplimentarán en un plazo:', 'El art. 165 LEC fija un plazo no superior a veinte días desde la recepción; si no se cumple, deben expresarse las causas de la dilación.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 165 LEC', 'Estos actos de comunicación se cumplimentarán en un plazo no superior a veinte días, contados a partir de su recepción', null, 'a45bb24dc47eeab78b3bb85c4c67e113e2609c47cc35ad91dfb668c026447f86', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a45bb24dc47eeab78b3bb85c4c67e113e2609c47cc35ad91dfb668c026447f86')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No superior a diez días, contados a partir de su recepción.', false), ('B', 'No superior a un mes, contado desde su expedición.', false), ('C', 'No superior a veinte días, contados a partir de su recepción.', true), ('D', 'No superior a cinco días hábiles, contados desde su expedición.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 169 de la Ley de Enjuiciamiento Civil, cuando el domicilio de un testigo se encuentre fuera de la circunscripción judicial del tribunal que conoce del asunto, su declaración se realizará como regla:', 'El art. 169.4 LEC remite al art. 137 bis (videoconferencia) cuando el domicilio está fuera de la circunscripción; el auxilio judicial queda para cuando el juez no considere conveniente la videoconferencia y la comparecencia sea imposible o muy gravosa.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 169.4 LEC', '4. El interrogatorio de las partes, la declaración de los testigos y la ratificación de los peritos se realizará en la sede del juzgado o tribunal que esté conociendo del asunto de que se trate, salvo que el domicilio de las personas mencionadas se encuentre fuera de la circunscripción judicial correspondiente, en cuyo caso se realizarán en la forma prevista en el artículo 137 bis. […] Sólo cuando a juicio del juez o de la jueza no sea conveniente realizarlas por videoconferencia y por razón de la distancia, dificultad del desplazamiento, circunstancias personales de la parte, del testigo o del perito, o por cualquier otra causa de análogas características resulte imposible o muy gravosa la comparecencia de las personas citadas en la sede del juzgado o tribunal, se podrá solicitar el auxilio judicial para la práctica de los actos de prueba señalados en este artículo.', null, '87e2e0e47b8d4f0f493d8d99b90d6ed112995fce08f379772a99e5d72e0b16ca', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '87e2e0e47b8d4f0f493d8d99b90d6ed112995fce08f379772a99e5d72e0b16ca')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre mediante exhorto al tribunal del domicilio del testigo.', false), ('B', 'Siempre en la sede del tribunal que conoce del asunto, corriendo los gastos de desplazamiento a cargo de la parte proponente.', false), ('C', 'En la forma prevista en el artículo 137 bis (por videoconferencia), y solo se pedirá auxilio judicial si no es conveniente la videoconferencia y la comparecencia resulta imposible o muy gravosa.', true), ('D', 'Mediante comisión rogatoria dirigida al Ministerio de Justicia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Civil, el litigante que, sin justa causa, demore la presentación al exhortado o la devolución al exhortante de los despachos cuya gestión le haya sido confiada será corregido con:', 'El art. 176 LEC sanciona la demora injustificada con multa de 30 euros por cada día de retraso respecto del final del plazo correspondiente.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 176 LEC', 'El litigante que, sin justa causa, demore la presentación al exhortado o la devolución al exhortante de los despachos cuya gestión le haya sido confiada será corregido con multa de 30 euros por cada día de retraso', null, '07776da794c37fec1b64cb29bb05a772ac9943f2c0723e5990d3b20ab4e0db52', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '07776da794c37fec1b64cb29bb05a772ac9943f2c0723e5990d3b20ab4e0db52')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Multa de 30 euros por cada día de retraso.', true), ('B', 'Multa de 60 euros por cada día de retraso.', false), ('C', 'Multa de 30 euros por cada semana de retraso.', false), ('D', 'Multa única de 300 euros.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el proceso civil, si el órgano exhortado no cumple el exhorto en plazo y la situación persiste tras el recordatorio del Letrado de la Administración de Justicia del órgano exhortante, ¿qué prevé el artículo 173 de la Ley de Enjuiciamiento Civil?', 'El art. 173 LEC prevé primero el recordatorio por el LAJ del exhortante y, si persiste la demora, la comunicación a la Sala de Gobierno del Tribunal exhortado; el suplicatorio al superior inmediato es la solución del art. 192 LECrim.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 173 LEC', 'Cuando no ocurriere así, el Letrado de la Administración de Justicia del órgano exhortante, de oficio o a instancia de parte, recordará al exhortado la urgencia del cumplimiento. Si la situación persistiere, el órgano para el que se haya solicitado el auxilio pondrá los hechos en conocimiento de la Sala de Gobierno correspondiente al Tribunal exhortado.', null, '8e72feae5580ee60f89dd270f0256642b9c71034e6644e29ed0c8e7d218d798f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8e72feae5580ee60f89dd270f0256642b9c71034e6644e29ed0c8e7d218d798f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el órgano exhortante practique por sí mismo la diligencia, desplazándose al lugar.', false), ('B', 'Que el órgano para el que se haya solicitado el auxilio ponga los hechos en conocimiento de la Sala de Gobierno correspondiente al Tribunal exhortado.', true), ('C', 'Que se dirija suplicatorio al superior inmediato del exhortado.', false), ('D', 'Que se ponga en conocimiento del Consejo General del Poder Judicial para la incoación de expediente disciplinario.', false)) as v(label, body, ok)
)
