insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-23-comunicacion-tribunales', 'Tema 23. Actos de comunicación con otros Tribunales y Autoridades. Auxilio judicial y cooperación internacional') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-23-comunicacion-tribunales' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, la petición de cooperación judicial, cualquiera que sea el Juzgado o Tribunal al que se dirija:', 'El art. 274.2 LOPJ exige que la petición de cooperación se haga siempre directamente, sin órganos intermedios.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 274.2 LOPJ', '2. La petición de cooperación, cualquiera que sea el Juzgado o Tribunal a quien se dirija, se efectuará siempre directamente, sin dar lugar a traslados ni reproducciones a través de órganos intermedios.', null, 'e2f6a2028a0af777213624d41f266e3124a784cdd36947ee1ee7def54c373550', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e2f6a2028a0af777213624d41f266e3124a784cdd36947ee1ee7def54c373550')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se cursará a través del Tribunal Superior de Justicia correspondiente.', false), ('B', 'Se tramitará por conducto del Consejo General del Poder Judicial.', false), ('C', 'Se remitirá a través del superior jerárquico común de ambos órganos.', false), ('D', 'Se efectuará siempre directamente, sin dar lugar a traslados ni reproducciones a través de órganos intermedios.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley Orgánica del Poder Judicial, ¿cuál de los siguientes es un motivo por el que los Juzgados y Tribunales españoles denegarán la cooperación internacional solicitada?', 'El art. 278.1 LOPJ enumera cuatro motivos tasados de denegación: orden público, competencia exclusiva española, acto ajeno a las atribuciones del órgano requerido y falta de contenido o requisitos mínimos.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 278.1 LOPJ', '1. La prestación de cooperación internacional sólo será denegada por los Juzgados y Tribunales españoles: 1.º Cuando el objeto o finalidad de la cooperación solicitada sea manifiestamente contrario al orden público.', null, '9025a6796431e5332fbc59154e5f68026b3854a5af68d875404fa40186cb45ab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9025a6796431e5332fbc59154e5f68026b3854a5af68d875404fa40186cb45ab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que la parte interesada no haya anticipado los gastos de la diligencia.', false), ('B', 'Que la solicitud no venga traducida al castellano y a la lengua cooficial de la Comunidad Autónoma.', false), ('C', 'Que la diligencia solicitada deba practicarse fuera de la sede del órgano requerido.', false), ('D', 'Que el objeto o finalidad de la cooperación sea manifiestamente contrario al orden público.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, un Juez puede realizar diligencias de instrucción penal en un lugar no comprendido en el territorio de su jurisdicción:', 'El art. 275 LOPJ permite al Juez practicar diligencias de instrucción penal en lugar próximo fuera de su territorio cuando sea conveniente, informando de inmediato al Juez competente.', 'jus_23_comunicacion_tribunales', (select id from public.topics where slug = 'jus-23-comunicacion-tribunales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 275 LOPJ', 'No obstante, podrán los Jueces realizar cualesquiera diligencias de instrucción penal en lugar no comprendido en el territorio de su jurisdicción, cuando el mismo se hallare próximo y ello resultare conveniente, dando inmediata noticia al Juez competente.', null, '4b34b7c279f2bba4ba0a8641087f2b73f7af30a8b45ca640f47c340057ee2003', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4b34b7c279f2bba4ba0a8641087f2b73f7af30a8b45ca640f47c340057ee2003')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando el lugar se hallare próximo y ello resultare conveniente, dando inmediata noticia al Juez competente.', true), ('B', 'Solo previa autorización de la Sala de Gobierno del Tribunal Superior de Justicia.', false), ('C', 'Nunca, pues debe recabar siempre el auxilio del juez del lugar mediante exhorto.', false), ('D', 'Solo si lo solicita el Ministerio Fiscal y lo autoriza el Juez del lugar.', false)) as v(label, body, ok)
)
