  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 152 de la Ley de Enjuiciamiento Civil, los actos de comunicación se realizarán bajo la dirección del Letrado de la Administración de Justicia y se ejecutarán por:', 'El art. 152.1 LEC encomienda la ejecución material de los actos de comunicación a los funcionarios del Cuerpo de Auxilio Judicial y al procurador de la parte que lo solicite.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 152.1 LEC', '1. Los actos de comunicación se realizarán bajo la dirección del letrado de la Administración de Justicia, que será el responsable de la adecuada organización del servicio. Tales actos se ejecutarán por: 1.º Los funcionarios del Cuerpo de Auxilio Judicial. 2.º El procurador de la parte que lo solicite.', null, 'a907bbb8c0639571bb5e80b3d9b68795a187e1adada03275ba522c66bbe127e8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a907bbb8c0639571bb5e80b3d9b68795a187e1adada03275ba522c66bbe127e8')
