with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de Enjuiciamiento Civil, cuando, practicadas las averiguaciones oportunas, no pudiere conocerse el domicilio del destinatario, el Letrado de la Administración de Justicia mandará que la comunicación se haga a través de:', 'El art. 164 LEC establece la comunicación edictal a través del Tablón Edictal Judicial Único, omitiendo los datos que permitan identificar a menores.', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 164 LEC', 'el letrado o letrada de la Administración de Justicia, consignadas estas circunstancias, mandará que se haga la comunicación, a través del Tablón Edictal Judicial Único', null, 'f2f9d3881f4c4b02b3c6d8548382c5a2a783e24f35c92b52349539ee1dfa2903', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f2f9d3881f4c4b02b3c6d8548382c5a2a783e24f35c92b52349539ee1dfa2903')
  returning id
