  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 175 de la Ley de Enjuiciamiento Criminal, la cédula de citación expresará, en su caso, la obligación de concurrir al primer llamamiento bajo la multa de:', 'El art. 175 LECrim prevé multa de 200 a 5.000 euros en el primer llamamiento y, en el segundo, el apercibimiento de ser perseguido por obstrucción a la justicia (art. 463.1 CP).', 'jus_24_comunicacion_partes', (select id from public.topics where slug = 'jus-24-comunicacion-partes'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 175 LECrim', '5. La obligación, si la hubiere, de concurrir al primer llamamiento, bajo la multa de 200 a 5.000 euros o si fuese ya el segundo el que se hiciere, la de concurrir bajo apercibimiento de ser perseguido como reo del delito de obstrucción a la justicia tipificado en el artículo 463.1 del Código Penal.', null, 'a66908058e78c7bc4c146c2ca56c1d0021897c2b596b78f26ac0d07d4e63b35e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a66908058e78c7bc4c146c2ca56c1d0021897c2b596b78f26ac0d07d4e63b35e')
