with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 de la Ley 20/2011, del Registro Civil, son elementos definitorios del Registro Civil que:', 'El art. 3 LRC declara que el Registro Civil es único para toda España y electrónico, con una base de datos única cuya estructura corresponde al Ministerio de Justicia.', 'jus_25_registro_civil', (select id from public.topics where slug = 'jus-25-registro-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628'), 'Art. 3 LRC', '1. El Registro Civil es único para toda España. 2. El Registro Civil es electrónico.', null, 'a5b2b07ae3649d23384ab66320411afe06d501ae4c3c0dc1d19bfce9979460f0', false
