  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Los progenitores no se ponen de acuerdo sobre el orden de los apellidos de su hijo. Según el artículo 49 de la Ley 20/2011, del Registro Civil, el Encargado los requerirá para que comuniquen el orden de apellidos en el plazo máximo de:', 'El art. 49.2 LRC fija tres días para comunicar el orden; si no se comunica, decide el Encargado atendiendo al interés superior del menor.', 'jus_25_registro_civil', (select id from public.topics where slug = 'jus-25-registro-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628'), 'Art. 49.2 LRC', 'En caso de desacuerdo o cuando no se hayan hecho constar los apellidos en la solicitud de inscripción, el Encargado del Registro Civil requerirá a los progenitores, o a quienes ostenten la representación legal del menor, para que en el plazo máximo de tres días comuniquen el orden de apellidos. Transcurrido dicho plazo sin comunicación expresa, el Encargado acordará el orden de los apellidos atendiendo al interés superior del menor.', null, 'dabebf5054dcf2eedc390b3010cca0c1593e0a3d21c3ff302f31307ec197581a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dabebf5054dcf2eedc390b3010cca0c1593e0a3d21c3ff302f31307ec197581a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres días; transcurrido sin comunicación expresa, el Encargado acordará el orden atendiendo al interés superior del menor.', true), ('B', 'Diez días; transcurrido sin comunicación expresa, se aplicará el orden paterno-materno.', false), ('C', 'Tres días; transcurrido sin comunicación expresa, se aplicará el orden alfabético.', false), ('D', 'Un mes; transcurrido sin comunicación expresa, decidirá el juez en expediente de jurisdicción voluntaria.', false)) as v(label, body, ok)
)
