with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si el parte facultativo indica la condición intersexual del nacido, según la Ley 20/2011, del Registro Civil, los progenitores, de común acuerdo, podrán solicitar que la mención del sexo figure en blanco por el plazo máximo de:', 'El art. 49.5 LRC permite dejar en blanco la mención del sexo un máximo de un año; después es obligatoria y deben solicitarla los progenitores.', 'jus_25_registro_civil', (select id from public.topics where slug = 'jus-25-registro-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628'), 'Art. 49.5 LRC', '5. En el caso de que el parte facultativo indicara la condición intersexual del nacido, los progenitores, de común acuerdo, podrán solicitar que la mención del sexo figure en blanco por el plazo máximo de un año.', null, '2e6abca39397f12d81e1f2eca44e7e04972a7575d97bd7a4c17d27e39bf61958', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2e6abca39397f12d81e1f2eca44e7e04972a7575d97bd7a4c17d27e39bf61958')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Seis meses.', false), ('B', 'Un año.', true), ('C', 'Dos años.', false), ('D', 'Hasta que el menor cumpla dieciséis años.', false)) as v(label, body, ok)
)
