with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 85 de la Ley 20/2011, del Registro Civil, contra las decisiones adoptadas por los Encargados de las Oficinas Central, Generales y Consulares del Registro Civil, los interesados solo podrán interponer recurso ante la Dirección General competente en el plazo de:', 'El art. 85.1 LRC fija un mes para recurrir ante la Dirección General las decisiones de los Encargados.', 'jus_25_registro_civil', (select id from public.topics where slug = 'jus-25-registro-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628'), 'Art. 85.1 LRC', '1. Contra las decisiones adoptadas por los Encargados de las Oficinas Central, Generales y Consulares del Registro Civil en el ámbito de las competencias atribuidas por esta Ley, los interesados sólo podrán interponer recurso ante la Dirección General de los Registros y del Notariado, en el plazo de un mes.', 'El art. 85.1 LRC consolidado sigue nombrando a la «Dirección General de los Registros y del Notariado», mientras que los arts. 22, 58 y 86 ya se refieren a la «Dirección General de Seguridad Jurídica y Fe Pública» (denominación actual). Por eso el enunciado habla de «la Dirección General competente».', '7b3d1e449c86e39693bb4d9696c6a4ad94d21a6eb2f7b0c62af3a9ad1ffcc733', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7b3d1e449c86e39693bb4d9696c6a4ad94d21a6eb2f7b0c62af3a9ad1ffcc733')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quince días.', false), ('B', 'Dos meses.', false), ('C', 'Tres meses.', false), ('D', 'Un mes.', true)) as v(label, body, ok)
)
