with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley 20/2011, del Registro Civil, si la Dirección General de Seguridad Jurídica y Fe Pública no dicta y notifica resolución expresa del recurso en el plazo de seis meses desde la recepción del escrito de interposición:', 'El art. 86.2 LRC fija seis meses para resolver; el silencio es desestimatorio y deja abierta la vía jurisdiccional.', 'jus_25_registro_civil', (select id from public.topics where slug = 'jus-25-registro-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628'), 'Art. 86.2 LRC', '2. La Dirección General resolverá el recurso en el plazo de seis meses siguientes a la recepción del escrito de interposición. Transcurrido este plazo sin que la Dirección General de Seguridad Jurídica y Fe Pública haya dictado y notificado resolución expresa, se entenderá desestimada la pretensión, quedando expedita la vía jurisdiccional correspondiente.', null, '6e35556f4adc140d3711e7eae703ad3615cee94952cc7fe1187725d1b81b5207', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6e35556f4adc140d3711e7eae703ad3615cee94952cc7fe1187725d1b81b5207')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se entenderá estimada la pretensión y el Encargado deberá practicar el asiento.', false), ('B', 'El recurso caducará y se archivarán las actuaciones.', false), ('C', 'Se entenderá desestimada la pretensión, quedando expedita la vía jurisdiccional correspondiente.', true), ('D', 'El interesado deberá reiterar el recurso ante el Ministerio de Justicia.', false)) as v(label, body, ok)
)
