select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 20/2011, del Registro Civil, los procedimientos registrales (expedientes):', 'El art. 88 LRC atribuye la tramitación y resolución al Encargado de la Oficina donde se pretende el asiento (los de rectificación, a la que lo practicó), aplica la Ley 39/2015 y establece silencio negativo.', 'jus_25_registro_civil', (select id from public.topics where slug = 'jus-25-registro-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628'), 'Art. 88 LRC', '1. Los procedimientos registrales serán tramitados y resueltos por el Encargado del Registro Civil de la Oficina donde se pretendiera efectuar el asiento. […] El silencio administrativo en los procedimientos registrales será negativo.', null, '4ad08e4d680580b8f3bbbc046ef645f9b2e534bd9d0cab043bb9d2e416ae066d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4ad08e4d680580b8f3bbbc046ef645f9b2e534bd9d0cab043bb9d2e416ae066d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se tramitan y resuelven por el Encargado del Registro Civil de la Oficina donde se pretenda efectuar el asiento, y el silencio administrativo en ellos es negativo.', true), ('B', 'Se tramitan por el Encargado de la Oficina del domicilio del solicitante y el silencio administrativo es positivo.', false), ('C', 'Se tramitan y resuelven siempre por la Oficina Central del Registro Civil, con silencio negativo.', false), ('D', 'Se tramitan conforme a la Ley de Enjuiciamiento Civil y se resuelven por el Juez de Primera Instancia.', false)) as v(label, body, ok)
)
