insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-26-archivo-judicial' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Civil, el libro de sentencias de cada tribunal, en el que se incluyen firmadas todas las sentencias definitivas, autos de igual carácter y votos particulares, se lleva bajo la custodia de:', 'El art. 213 LEC sitúa el libro de sentencias bajo la custodia del Letrado de la Administración de Justicia, ordenado correlativamente según su fecha.', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 213 LEC', 'En cada tribunal se llevará, bajo la custodia del letrado o letrada de la Administración de Justicia, un libro de sentencias, en el que se incluirán firmadas todas las definitivas, autos de igual carácter, así como los votos particulares que se hubieren formulado, que serán ordenados correlativamente según su fecha.', null, '688d5ae586ddd134134cfebaa2ec507eae0eff059972b6393c77da938e2c367a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '688d5ae586ddd134134cfebaa2ec507eae0eff059972b6393c77da938e2c367a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Presidente del tribunal.', false), ('B', 'El Letrado o Letrada de la Administración de Justicia.', true), ('C', 'El magistrado ponente de cada asunto.', false), ('D', 'El funcionario del Cuerpo de Tramitación Procesal y Administrativa.', false)) as v(label, body, ok)
)
