with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Civil, ¿quién puede acceder a los libros, archivos y registros judiciales que no tengan carácter reservado y obtener, a su costa, testimonio o certificación de los extremos que indique?', 'El art. 141 LEC reconoce el acceso a libros, archivos y registros judiciales no reservados a quienes acrediten un interés legítimo, que pueden obtener testimonio o certificación a su costa.', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 141 LEC', 'Las personas que acrediten un interés legítimo podrán acceder a los libros, archivos y registros judiciales que no tengan carácter reservado y obtener, a su costa, testimonio o certificación de los extremos que indiquen.', null, '9d58ab1d96edf437d2042c7766b431e4ced9842e703df120e41651bb95d555bb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9d58ab1d96edf437d2042c7766b431e4ced9842e703df120e41651bb95d555bb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
