with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley Orgánica del Poder Judicial, las actuaciones orales y vistas grabadas y documentadas en soporte digital:', 'El art. 230.3 LOPJ prohíbe transcribir las actuaciones grabadas en soporte digital salvo previsión legal expresa (en igual sentido, art. 147 LEC).', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 230.3 LOPJ', '3. Las actuaciones orales y vistas grabadas y documentadas en soporte digital no podrán transcribirse, salvo en los casos expresamente previstos en la ley.', null, '78dd8718eebc5be7876c6cbb1accef47714cb958051b5432baf436faf323e552', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '78dd8718eebc5be7876c6cbb1accef47714cb958051b5432baf436faf323e552')
