  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Ministerio de Justicia, y su llevanza es responsabilidad del Letrado de la Administración de Justicia.', true), ('B', 'Al Consejo General del Poder Judicial, y su llevanza es responsabilidad del juez.', false), ('C', 'A las Salas de Gobierno, y su llevanza corresponde al Cuerpo de Gestión Procesal.', false), ('D', 'A cada Letrado de la Administración de Justicia, y su llevanza corresponde al Cuerpo de Auxilio Judicial.', false)) as v(label, body, ok)
)
