  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, con carácter general se procederá a la destrucción de autos y expedientes judiciales transcurridos:', 'El art. 458.2 LOPJ fija como regla general la destrucción a los seis años de la firmeza de la resolución que puso fin definitivamente al procedimiento.', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 458.2 LOPJ', 'Con carácter general se procederá a la destrucción de autos y expedientes judiciales transcurridos seis años desde la firmeza de la resolución que de manera definitiva puso término al procedimiento que dio lugar a la formación de aquéllos.', null, '58b82cea5e521f4a8cb2e5c3ecb836a023f42430d5131e99d87879f990c3b7ff', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '58b82cea5e521f4a8cb2e5c3ecb836a023f42430d5131e99d87879f990c3b7ff')
