with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto-ley 6/2023, el sistema de archivo judicial electrónico que asegure el acceso y la conservación a largo plazo de los expedientes y documentos judiciales electrónicos:', 'El art. 79 RDL 6/2023 encomienda a las Administraciones con competencias en materia de Justicia disponer de un sistema de archivo judicial electrónico interoperable.', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 79 RDL 6/2023', 'Las Administraciones públicas con competencias en materias de Administración de Justicia dispondrán de un sistema de archivo judicial electrónico que asegurará el acceso y la conservación a largo plazo de los expedientes y documentos judiciales electrónicos.', null, 'a7f447e287f71c3ce4d294d9e5b1ae82470cc657ba315849b3e9ad2f69358743', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a7f447e287f71c3ce4d294d9e5b1ae82470cc657ba315849b3e9ad2f69358743')
  returning id
