with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto-ley 6/2023, el número de identificación general que se asigna a cada expediente judicial electrónico:', 'El art. 47.2 RDL 6/2023 dispone que el número de identificación general del expediente es único e inalterable durante todo el proceso, lo que permite identificarlo por cualquier tribunal u oficina.', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 47.2 RDL 6/2023', '2. Se asignará un número de identificación general a cada expediente judicial electrónico, que será único e inalterable a lo largo de todo el proceso, permitiendo su identificación unívoca por cualquier tribunal u oficina del ámbito judicial en un entorno de intercambio de datos.', null, 'd30fb35c269b7b921ecd0d504cc07a2b62d096f61de4841429eb0b9066bfcf70', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd30fb35c269b7b921ecd0d504cc07a2b62d096f61de4841429eb0b9066bfcf70')
  returning id
