with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al Real Decreto-ley 6/2023, el elemento que garantiza la integridad del expediente judicial electrónico y permite su recuperación siempre que sea preciso es:', 'El art. 47.3 RDL 6/2023 exige que todo expediente judicial electrónico tenga un índice electrónico firmado que garantiza su integridad y su recuperación.', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 47.3 RDL 6/2023', '3. Todo expediente judicial electrónico tendrá un índice electrónico, firmado por la oficina judicial actuante o por procesos automatizados conforme a lo previsto en este real decreto-ley. Este índice garantizará la integridad del expediente judicial electrónico y permitirá su recuperación siempre que sea preciso', null, '60df30fdca839d564f9c0fc27f6384f7839db65fa224b0ffe61b34ad66b9cb17', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '60df30fdca839d564f9c0fc27f6384f7839db65fa224b0ffe61b34ad66b9cb17')
  returning id
