  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El libro de sentencias electrónico.', false), ('B', 'El código seguro de verificación de cada documento.', false), ('C', 'La diligencia de constancia del Letrado de la Administración de Justicia.', false), ('D', 'El índice electrónico, firmado por la oficina judicial actuante o por procesos automatizados.', true)) as v(label, body, ok)
)
