with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto-ley 6/2023, en el ámbito del expediente judicial electrónico, la remisión de expedientes:', 'El art. 47.4 RDL 6/2023 sustituye la remisión de expedientes por su puesta a disposición electrónica, pudiendo obtener copia electrónica quienes tengan derecho.', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 47.4 RDL 6/2023', '4. La remisión de expedientes se sustituirá a todos los efectos legales por la puesta a disposición del expediente judicial electrónico, pudiendo obtener copia electrónica del mismo todos aquellos que tengan derecho conforme a lo dispuesto en las normas procesales.', null, '2a78a8e529801e814dd8fa4e41eeddc5a535371f920dd9faef9aaeace4816dbe', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2a78a8e529801e814dd8fa4e41eeddc5a535371f920dd9faef9aaeace4816dbe')
  returning id
), o as (
