with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto-ley 6/2023, el sistema que tiene por objeto posibilitar la itineración de expedientes electrónicos y la transmisión de documentos electrónicos entre oficinas u órganos judiciales o fiscales, aunque usen distintos sistemas de gestión procesal, es:', 'El art. 48.1 RDL 6/2023 crea el Sistema Común de Intercambio para la itineración de expedientes y la transmisión de documentos entre órganos y oficinas, bajo la responsabilidad del Ministerio de la Presidencia, Justicia y Relaciones con las Cortes.', 'jus_26_archivo_judicial', (select id from public.topics where slug = 'jus-26-archivo-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 48.1 RDL 6/2023', '1. El Sistema Común de Intercambio de documentos y expedientes judiciales electrónicos tendrá por objeto posibilitar la itineración de expedientes electrónicos y la transmisión de documentos electrónicos de una oficina u órgano judicial o fiscal a otro, en los casos en los que corresponda por aplicación de las leyes procesales, e independientemente de que los tribunales u oficinas implicados utilicen el mismo o distintos sistemas de gestión procesal', null, '44f9ff29e524ff11091e129dab6f9839d00d28e9c3b2480f829fe4d7931bfcbc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '44f9ff29e524ff11091e129dab6f9839d00d28e9c3b2480f829fe4d7931bfcbc')
  returning id
), o as (
