with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley de Enjuiciamiento Civil, contra las diligencias de ordenación y los decretos no definitivos cabrá recurso de reposición:', 'El art. 451.1 LEC atribuye la reposición contra diligencias de ordenación y decretos no definitivos al propio LAJ que los dictó; contra providencias y autos no definitivos la reposición se interpone ante el mismo tribunal (art. 451.2).', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 451.1 LEC', '1. Contra las diligencias de ordenación y decretos no definitivos cabrá recurso de reposición ante el Letrado de la Administración de Justicia que dictó la resolución recurrida, excepto en los casos en que la ley prevea recurso directo de revisión.', null, '5aaec79be340eb79e75ecd3c38172302c0b7d46475fed2cb79e8978927bc8e65', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5aaec79be340eb79e75ecd3c38172302c0b7d46475fed2cb79e8978927bc8e65')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ante el Letrado de la Administración de Justicia que dictó la resolución recurrida, salvo que la ley prevea recurso directo de revisión.', true), ('B', 'Ante el juez o tribunal del que dependa el Letrado de la Administración de Justicia.', false), ('C', 'Ante la Audiencia Provincial correspondiente.', false), ('D', 'Ante el Secretario de Gobierno del Tribunal Superior de Justicia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
