with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el proceso civil, el recurso de reposición deberá interponerse en el plazo de:', 'El art. 452.1 LEC fija cinco días para interponer la reposición, expresando la infracción en que habría incurrido la resolución.', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 452.1 LEC', '1. El recurso de reposición deberá interponerse en el plazo de cinco días, expresándose la infracción en que la resolución hubiera incurrido a juicio del recurrente.', null, 'ce121187d92365dd4ea86538ef54753122470d8b10ea10fea3b5d17330c80d91', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ce121187d92365dd4ea86538ef54753122470d8b10ea10fea3b5d17330c80d91')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres días.', false), ('B', 'Diez días.', false), ('C', 'Cinco días.', true), ('D', 'Veinte días.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 454 de la Ley de Enjuiciamiento Civil, contra el auto que resuelva el recurso de reposición interpuesto contra una resolución judicial:', 'El art. 454 LEC declara irrecurrible el auto que resuelve la reposición contra resoluciones judiciales, salvo la queja, aunque la cuestión puede reproducirse al recurrir la resolución definitiva.', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 454 LEC', 'Salvo los casos en que proceda el recurso de queja, contra el auto que resuelva el recurso de reposición no cabrá recurso alguno, sin perjuicio de reproducir la cuestión objeto de la reposición al recurrir, si fuere procedente, la resolución definitiva.', null, '136e3c2802b4e547a10a953672d23d5d4c2568a0cd5ba06210e7e8cffb016685', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '136e3c2802b4e547a10a953672d23d5d4c2568a0cd5ba06210e7e8cffb016685')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cabrá siempre recurso de apelación, sin efectos suspensivos.', false), ('B', 'No cabrá recurso alguno, salvo los casos en que proceda el recurso de queja, sin perjuicio de reproducir la cuestión al recurrir la resolución definitiva.', true), ('C', 'Cabrá recurso de revisión ante el mismo tribunal en el plazo de cinco días.', false), ('D', 'Cabrá recurso de casación cuando concurra interés casacional.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 454 bis de la Ley de Enjuiciamiento Civil, ¿contra qué resoluciones cabe recurso directo de revisión ante el tribunal?', 'El art. 454 bis.1 LEC prevé recurso de revisión contra el decreto que resuelve la reposición y recurso directo de revisión contra los decretos que ponen fin al procedimiento o impiden su continuación, y en los demás casos que la ley prevea expresamente. Carecen de efectos suspensivos.', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 454 bis.1 LEC', '1. Cabrá recurso de revisión ante el tribunal contra el decreto resolutivo de la reposición y recurso directo de revisión contra los decretos por los que se ponga fin al procedimiento o impidan su continuación.', null, 'd2f1fcca7d59422bee1b3130c2cdf25031f551337bfac21b7337b51c621df601', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd2f1fcca7d59422bee1b3130c2cdf25031f551337bfac21b7337b51c621df601')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Contra las providencias del juez que resuelvan cuestiones procesales.', false), ('B', 'Contra todas las diligencias de ordenación del Letrado de la Administración de Justicia.', false), ('C', 'Contra los autos definitivos dictados por el juez en primera instancia.', false), ('D', 'Contra los decretos del Letrado de la Administración de Justicia por los que se ponga fin al procedimiento o impidan su continuación.', true)) as v(label, body, ok)
)
