with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El recurso de revisión contra los decretos del Letrado de la Administración de Justicia deberá interponerse en el plazo de:', 'El art. 454 bis.2 LEC establece cinco días; el LAJ lo admite por diligencia de ordenación y da cinco días a las demás partes para impugnarlo, resolviendo el tribunal por auto en otros cinco días.', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 454 bis.2 LEC', '2. El recurso de revisión deberá interponerse en el plazo de cinco días mediante escrito en el que deberá citarse la infracción en que la resolución hubiera incurrido.', null, '58550d8f8458777d881f166278189a2157219c62abfb06d1e0729f68ec5d4198', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '58550d8f8458777d881f166278189a2157219c62abfb06d1e0729f68ec5d4198')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tres días, verbalmente o por escrito.', false), ('B', 'Cinco días, mediante escrito en el que se cite la infracción en que hubiera incurrido la resolución.', true), ('C', 'Diez días, mediante escrito con firma de abogado y procurador en todo caso.', false), ('D', 'Veinte días, mediante escrito presentado ante el tribunal que deba resolverlo.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
