with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 455 de la Ley de Enjuiciamiento Civil, ¿cuál de las siguientes resoluciones no es apelable?', 'El art. 455.1 LEC declara apelables las sentencias de toda clase de juicio y los autos definitivos, con excepción de las sentencias de juicios verbales por razón de la cuantía que no supere los 3.000 euros.', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 455.1 LEC', '1. Las sentencias dictadas en toda clase de juicio, los autos definitivos y aquéllos otros que la ley expresamente señale, serán apelables, con excepción de las sentencias dictadas en los juicios verbales por razón de la cuantía cuando ésta no supere los 3.000 euros.', null, '7e18704fd08cb8578cb1fcdd4c9a59389323d12a73562ad6058440ba654ddd4c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7e18704fd08cb8578cb1fcdd4c9a59389323d12a73562ad6058440ba654ddd4c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La sentencia dictada en un juicio ordinario por razón de la cuantía.', false), ('B', 'El auto definitivo que pone fin al proceso.', false), ('C', 'La sentencia dictada en un juicio verbal por razón de la cuantía de 10.000 euros.', false), ('D', 'La sentencia dictada en un juicio verbal por razón de la cuantía cuando esta no supere los 3.000 euros.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la redacción vigente del artículo 458 de la Ley de Enjuiciamiento Civil, el recurso de apelación se interpondrá:', 'El art. 458.1 LEC, en la redacción dada por el RDL 6/2023 (vigente desde el 20 de marzo de 2024), ordena interponer la apelación directamente ante el tribunal competente para resolverla, en veinte días, acompañando copia de la resolución; la fase de preparación (art. 457) carece hoy de contenido.', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 458.1 LEC', '1. El recurso de apelación se interpondrá, cumpliendo en su caso con lo dispuesto en el artículo 276, ante el tribunal que sea competente para conocer del mismo, en el plazo de veinte días desde la notificación de la resolución impugnada, debiendo acompañarse copia de dicha resolución.', null, '1e88b22362c286204f8df2cd2a182bd4ef9df25169ff25bb64e51b805ea3432c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1e88b22362c286204f8df2cd2a182bd4ef9df25169ff25bb64e51b805ea3432c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ante el tribunal que sea competente para conocer del mismo, en el plazo de veinte días desde la notificación de la resolución impugnada.', true), ('B', 'Ante el tribunal que dictó la resolución impugnada, en el plazo de veinte días desde su notificación.', false), ('C', 'Ante el tribunal competente para conocer del mismo, en el plazo de diez días desde la notificación de la resolución impugnada.', false), ('D', 'Ante el tribunal que dictó la resolución impugnada, previa preparación en el plazo de cinco días.', false)) as v(label, body, ok)
)
