with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Del escrito de interposición del recurso de apelación se dará traslado a las demás partes para que presenten escrito de oposición o de impugnación en el plazo de:', 'El art. 461.1 LEC emplaza a las demás partes por diez días para oponerse al recurso o impugnar la resolución en lo que les sea desfavorable.', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 461.1 LEC', '1. Del escrito de interposición del recurso de apelación, el letrado o letrada de la Administración de Justicia dará traslado a las demás partes, emplazándolas por diez días para que presenten escrito de oposición al recurso o, en su caso, de impugnación de la resolución apelada en lo que le resulte desfavorable.', null, '2bca83d735e23dcf97db2857f14af594eb34a245b7a5bd02439ecbbb3af0d173', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2bca83d735e23dcf97db2857f14af594eb34a245b7a5bd02439ecbbb3af0d173')
  returning id
), o as (
