insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Con carácter general, el conocimiento del recurso de casación civil corresponde a:', 'El art. 478.1 LEC atribuye la casación civil a la Sala Primera del TS; las Salas de lo Civil y Penal de los TSJ solo conocen cuando el recurso se funda en Derecho civil, foral o especial propio de la Comunidad y el Estatuto lo prevé.', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 478.1 LEC', '1. El conocimiento del recurso de casación corresponde a la Sala Primera del Tribunal Supremo.', null, '48ff83c76fd30d5cdcd07bf508f1464fb5a4b25407e1a71a5c43e6fb4b029b5e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '48ff83c76fd30d5cdcd07bf508f1464fb5a4b25407e1a71a5c43e6fb4b029b5e')
  returning id
), o as (
