  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Sala Primera del Tribunal Supremo.', true), ('B', 'La Sala Segunda del Tribunal Supremo.', false), ('C', 'La Sala de lo Civil y Penal del Tribunal Superior de Justicia, en todo caso.', false), ('D', 'La Audiencia Provincial que dictó la sentencia de apelación.', false)) as v(label, body, ok)
)
