  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el procedimiento abreviado, la sentencia dictada por el Juez de lo Penal es apelable:', 'El art. 790.1 LECrim atribuye la apelación de las sentencias del Juez de lo Penal a la Audiencia Provincial (y las del Juez Central de lo Penal a la Sala de lo Penal de la Audiencia Nacional), con un plazo de diez días.', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 790.1 LECrim', '1. La sentencia dictada por el Juez de lo Penal es apelable ante la Audiencia Provincial correspondiente, y la del Juez Central de lo penal, ante la Sala de lo Penal de la Audiencia Nacional. El recurso podrá ser interpuesto por cualquiera de las partes, dentro de los diez días siguientes a aquel en que se les hubiere notificado la sentencia.', 'El art. 790 LECrim conserva la denominación «Juez de lo Penal»; tras la LO 1/2025 (disp. adic. 1.ª) las referencias a los Juzgados de lo Penal se entienden hechas a las Secciones de lo Penal de los Tribunales de Instancia. Revisar si conviene adaptar el enunciado.', 'c25e2e02fb744490fe4d3ce31f78ddc74b6fd1c6f2ac70d8092cef32ddf31d76', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c25e2e02fb744490fe4d3ce31f78ddc74b6fd1c6f2ac70d8092cef32ddf31d76')
