with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 954 de la Ley de Enjuiciamiento Criminal, ¿cuál de los siguientes es un supuesto en que se puede solicitar la revisión de una sentencia firme?', 'El art. 954.1 LECrim enumera los motivos de revisión: prueba falsa declarada por sentencia, prevaricación del juez, dos sentencias firmes sobre el mismo hecho y encausado, nuevos hechos o pruebas y contradicción con una sentencia no penal sobre la cuestión prejudicial.', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 954.1 LECrim', 'c) Cuando sobre el mismo hecho y encausado hayan recaído dos sentencias firmes.', null, 'd97b9d2b027aeadacd24fba5efd3a88643ac9f7a3933dffba549a767fbc3fb59', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd97b9d2b027aeadacd24fba5efd3a88643ac9f7a3933dffba549a767fbc3fb59')
  returning id
), o as (
