with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la disposición adicional decimoquinta de la Ley Orgánica del Poder Judicial, en el orden penal el depósito para recurrir es exigible:', 'La DA 15.ª.1 LOPJ exige el depósito en los órdenes civil, social y contencioso-administrativo; en el orden penal solo a la acusación popular. El Ministerio Fiscal y las Administraciones públicas están exentos (apartado 5).', 'justra_24_recursos', (select id from public.topics where slug = 'justra-24-recursos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'DA 15.ª.1 LOPJ', 'En el orden penal este depósito será exigible únicamente a la acusación popular.', null, '2bba45703938b41648dd67d67fc09b3bb7de61486b6191d64bfac19aa026f496', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2bba45703938b41648dd67d67fc09b3bb7de61486b6191d64bfac19aa026f496')
  returning id
), o as (
