insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 36/2011, de 10 de octubre, reguladora de la jurisdicción social (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-20-proceso-laboral', 'Tema 20. El proceso laboral: ordinario, despido y seguridad social') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-20-proceso-laboral' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Ámbito del orden jurisdiccional social (art. 2 LRJS)"},{"n":"2","title":"Evitación del proceso: conciliación o mediación previas (arts. 63-65 LRJS)"},{"n":"3","title":"El proceso ordinario (arts. 80-101 LRJS)"},{"n":"3.1","title":"Demanda, admisión y señalamiento (arts. 80-82 LRJS)"},{"n":"3.2","title":"Conciliación y juicio: suspensión, incomparecencia y celebración (arts. 83-87 LRJS)"},{"n":"3.3","title":"La sentencia (art. 97 LRJS)"},{"n":"4","title":"El proceso por despido disciplinario (arts. 103-113 LRJS)"},{"n":"4.1","title":"Plazo de caducidad y posición de las partes (arts. 103 y 105 LRJS)"},{"n":"4.2","title":"Calificación del despido y efectos (arts. 108-113 LRJS)"},{"n":"5","title":"Procesos de Seguridad Social (arts. 71 y 140-147 LRJS)"},{"n":"5.1","title":"Reclamación administrativa previa (art. 71 LRJS)"},{"n":"5.2","title":"Impugnación de altas médicas (art. 140 LRJS)"}]'::jsonb, '["Art. 63 Ley 36/2011: «Será requisito previo para la tramitación del proceso el intento de conciliación o, en su caso, de mediación ante el servicio administrativo correspondiente o ante el órgano que asuma estas funciones»","Art. 65.1 Ley 36/2011: «La presentación de la solicitud de conciliación o de mediación interrumpirá la prescripción o suspenderá la caducidad de acciones desde la fecha de dicha presentación, reiniciándose o reanudándose respectivamente el cómputo de los plazos al día siguiente de intentada la conciliación o mediación o transcurridos quince días hábiles desde su presentación sin que se haya celebrado.»","Art. 82.1 Ley 36/2011: «De ser admitida la demanda, una vez verificada la concurrencia de los requisitos exigidos, en la misma resolución de admisión a trámite el letrado o letrada de la Administración de Justicia señalará el día y la hora en que hayan de tener lugar, separada o sucesivamente, los actos de conciliación y de juicio, debiendo mediar un mínimo de diez días entre la citación y la efectiva celebración de dichos actos»","Art. 83.2 Ley 36/2011: «Si el actor, citado en forma, no compareciese ni alegase justa causa que motive la suspensión del acto de conciliación o del juicio, el secretario judicial en el primer caso y el juez o tribunal en el segundo, le tendrán por desistido de su demanda.»","Art. 83.3 Ley 36/2011: «La incomparecencia injustificada del demandado al acto de conciliación no impedirá la celebración de los actos de conciliación y juicio, continuando este sin necesidad de declarar su rebeldía»","Art. 97.1 Ley 36/2011: «El juez o tribunal dictará sentencia en el plazo de cinco días, publicándose inmediatamente y notificándose a las partes o a sus representantes dentro de los dos días siguientes.»","Art. 103.1 Ley 36/2011: «El trabajador podrá reclamar contra el despido, dentro de los veinte días hábiles siguientes a aquél en que se hubiera producido. Dicho plazo será de caducidad a todos los efectos y no se computarán los sábados, domingos y los festivos en la sede del órgano jurisdiccional.»","Art. 105.1 Ley 36/2011: «Ratificada, en su caso, la demanda, tanto en la fase de alegaciones como en la práctica de la prueba, y en la fase de conclusiones corresponderá al demandado exponer sus posiciones en primer lugar. Asimismo, le corresponderá la carga de probar la veracidad de los hechos imputados en la carta de despido como justificativos del mismo.»","Art. 108.1 Ley 36/2011: «En el fallo de la sentencia, el juez calificará el despido como procedente, improcedente o nulo.»","Art. 110.3 Ley 36/2011: «La opción deberá ejercitarse mediante escrito o comparecencia ante la oficina del Juzgado de lo Social, dentro del plazo de cinco días desde la notificación de la sentencia que declare el despido improcedente, sin esperar a la firmeza de la misma, si fuera la de instancia.»","Art. 113 Ley 36/2011: «Si el despido fuera declarado nulo se condenará a la inmediata readmisión del trabajador con abono de los salarios dejados de percibir.»","Art. 71.1 Ley 36/2011: «Será requisito necesario para formular demanda en materia de prestaciones de Seguridad Social, que los interesados interpongan reclamación previa ante la Entidad gestora de las mismas.»","Art. 71.5 Ley 36/2011: «Formulada reclamación previa en cualquiera de los supuestos mencionados en el presente artículo, la Entidad deberá contestar expresamente a la misma en el plazo de cuarenta y cinco días. En caso contrario se entenderá denegada la reclamación por silencio administrativo.»","Art. 71.6 Ley 36/2011: «La demanda habrá de formularse en el plazo de treinta días, a contar desde la fecha en que se notifique la denegación de la reclamación previa o desde el día en que se entienda denegada por silencio administrativo.»","Art. 140.3 Ley 36/2011: «c) El acto de la vista habrá de señalarse dentro de los cinco días siguientes a la admisión de la demanda, y la sentencia, que no tendrá recurso, se dictará en el plazo de tres días»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936', null, null, null, null
  from public.topics t where t.slug = 'jus-20-proceso-laboral'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
